const READING_EXTRA = {"N5":{"1":{"ext":"ベトナムは あつい くにです。わたしは まいにち びょういんで はたらきます。にほんごは むずかしいですが、がんばります。","qs":[{"q":"Người viết làm việc ở đâu mỗi ngày?","options":["がっこう (trường học)","びょういん (bệnh viện)","かいしゃ (công ty)","としょかん (thư viện)"],"answer":1,"explain":"Phần mở rộng: 「まいにち びょういんで はたらきます」 = mỗi ngày làm việc ở bệnh viện."},{"q":"Việt Nam là đất nước thế nào?","options":["さむい (lạnh)","あつい (nóng)","ちいさい (nhỏ)","くらい (tối)"],"answer":1,"explain":"「ベトナムは あつい くにです」 = Việt Nam là đất nước nóng."},{"q":"Người viết thấy tiếng Nhật thế nào?","options":["かんたん (dễ)","むずかしい (khó)","つまらない (chán)","やすい (rẻ)"],"answer":1,"explain":"「にほんごは むずかしいですが、がんばります」 = tiếng Nhật khó nhưng sẽ cố gắng."},{"q":"Câu nào KHÔNG đúng với đoạn văn?","options":["Người viết là bác sĩ","Người viết 24 tuổi","Người viết làm việc ở trường học","Người viết đến từ Việt Nam"],"answer":2,"explain":"Người viết là bác sĩ ở bệnh viện ABC, không làm ở trường học."},{"q":"Từ 「びょういん」 nghĩa là gì?","options":["Trường học","Bệnh viện","Công ty","Ngân hàng"],"answer":1,"explain":"「びょういん」 = bệnh viện."},{"q":"Đoạn văn chủ yếu giới thiệu điều gì?","options":["Một chuyến du lịch","Bản thân người viết","Thời tiết Việt Nam","Cách học tiếng Nhật"],"answer":1,"explain":"Cả đoạn là lời tự giới thiệu: tên, quê, tuổi, nghề nghiệp."}]},"2":{"ext":"これは いすです。この いすも わたしの いすです。","qs":[{"q":"Vật được giới thiệu thêm ở phần cuối là gì?","options":["いす (ghế)","とけい (đồng hồ)","かさ (ô)","じてんしゃ (xe đạp)"],"answer":0,"explain":"「これは いすです」 = Đây là cái ghế."},{"q":"Cái ghế là của ai?","options":["たなかさん","せんせい","Người viết","ともだち"],"answer":2,"explain":"「この いすも わたしの いすです」 = cái ghế này cũng là của tôi."},{"q":"Từ 「その」 dùng cho vật ở vị trí nào so với người nói?","options":["Ngay cạnh người nói","Gần người nghe","Rất xa cả hai người","Ở trong phòng khác"],"answer":1,"explain":"Hệ これ・それ・あれ: それ/その chỉ vật gần người nghe."},{"q":"Câu nào đúng với đoạn văn?","options":["Tivi là của Tanaka","Cặp là của người viết","Sách là của người viết","Bàn là của Tanaka"],"answer":2,"explain":"「この ほんは わたしの ほんです」 — chỉ sách là của người viết; cặp mới là của Tanaka."},{"q":"Từ 「つくえ」 nghĩa là gì?","options":["Giường","Ghế","Bàn học/bàn làm việc","Tủ"],"answer":2,"explain":"「つくえ」 = cái bàn."},{"q":"Đoạn văn chủ yếu giới thiệu điều gì?","options":["Gia đình người viết","Căn phòng và đồ vật trong phòng","Lớp học","Nhà của Tanaka"],"answer":1,"explain":"Đoạn liệt kê phòng và các đồ vật: giường, bàn, tivi, sách, cặp."}]},"3":{"ext":"エレベーターは １かいに あります。レストランの りょうりは おいしいです。かいぎしつは ひろいです。","qs":[{"q":"Thang máy ở tầng mấy?","options":["２かい","３かい","１かい","ちか１かい"],"answer":2,"explain":"「エレベーターは １かいに あります」 = thang máy ở tầng 1."},{"q":"Đồ ăn của nhà hàng thế nào?","options":["たかい (đắt)","おいしい (ngon)","からい (cay)","すくない (ít)"],"answer":1,"explain":"「レストランの りょうりは おいしいです」 = đồ ăn nhà hàng ngon."},{"q":"Phòng họp thế nào?","options":["せまい (chật)","くらい (tối)","ひろい (rộng)","ふるい (cũ)"],"answer":2,"explain":"「かいぎしつは ひろいです」 = phòng họp rộng."},{"q":"Tầng 1 của khách sạn có những gì?","options":["フロント・トイレ・エレベーター","レストラン・トイレ","かいぎしつ・フロント","Chỉ có レストラン"],"answer":0,"explain":"Tầng 1 gồm quầy lễ tân (フロント), nhà vệ sinh và thang máy."},{"q":"Từ 「かいぎしつ」 nghĩa là gì?","options":["Phòng ăn","Phòng họp","Phòng ngủ","Phòng tắm"],"answer":1,"explain":"「かいぎしつ」 = phòng họp."},{"q":"Đoạn văn giới thiệu về điều gì?","options":["Giá phòng khách sạn","Các tầng của khách sạn Sakura","Thực đơn nhà hàng","Nhân viên khách sạn"],"answer":1,"explain":"Đoạn giới thiệu từng tầng của khách sạn Sakura."}]},"4":{"ext":"１２じはんに ひるごはんを たべます。５じはんに うちへ かえります。テレビを みてから ねます。","qs":[{"q":"Người viết ăn trưa lúc mấy giờ?","options":["１２じ","１２じはん","１じ","１１じはん"],"answer":1,"explain":"「１２じはんに ひるごはんを たべます」 = ăn trưa lúc 12 giờ rưỡi."},{"q":"Người viết về nhà lúc mấy giờ chiều?","options":["５じ","６じはん","５じはん","７じ"],"answer":2,"explain":"「５じはんに うちへ かえります」 = 5 giờ rưỡi về nhà."},{"q":"Trước khi ngủ, người viết làm gì?","options":["ほんを よむ","おんがくを きく","テレビを みる","てがみを かく"],"answer":2,"explain":"「テレビを みてから ねます」 = xem tivi rồi mới ngủ."},{"q":"Buổi sáng người viết học tiếng Nhật trong bao lâu?","options":["２じかん","３じかん","５じかん","４じかん"],"answer":3,"explain":"Học từ 8 giờ đến 12 giờ = 4 tiếng."},{"q":"Trình tự một ngày đúng là gì?","options":["Dậy → làm việc → ăn sáng → học → ngủ","Dậy → ăn sáng → học → làm việc → ngủ","Ăn sáng → dậy → học → ngủ → làm việc","Dậy → học → ăn trưa → ngủ → làm việc"],"answer":1,"explain":"Theo đoạn: dậy 6:30, ăn sáng 7:00, học 8–12h, làm việc 13–17h, ngủ 23h."},{"q":"Từ 「はたらきます」 nghĩa là gì?","options":["Học","Làm việc","Ngủ","Chơi"],"answer":1,"explain":"「はたらきます」 = làm việc."}]},"5":{"ext":"きょうとで さくらを みました。さくらは とても きれいでした。ともだちは しゃしんを たくさん とりました。","qs":[{"q":"Ở Kyoto, họ đã ngắm gì?","options":["ゆき (tuyết)","うみ (biển)","さくら (hoa anh đào)","やま (núi)"],"answer":2,"explain":"「きょうとで さくらを みました」 = ngắm hoa anh đào ở Kyoto."},{"q":"Hoa anh đào thế nào?","options":["とても きれいだった","あまり きれいじゃなかった","ちいさかった","たかかった"],"answer":0,"explain":"「さくらは とても きれいでした」 = hoa anh đào rất đẹp."},{"q":"Người bạn đã làm gì nhiều?","options":["しゃしんを とる (chụp ảnh)","てがみを かく (viết thư)","うたを うたう (hát)","かいものを する (mua sắm)"],"answer":0,"explain":"「しゃしんを たくさん とりました」 = chụp rất nhiều ảnh."},{"q":"Câu nào đúng với chuyến đi?","options":["Trời nóng và chuyến đi chán","Trời lạnh nhưng chuyến đi rất vui","Đi một mình bằng xe buýt","Về nhà lúc 7 giờ"],"answer":1,"explain":"「さむかったです。でも、とても たのしかったです」 — lạnh nhưng vui."},{"q":"Động từ 「かえりました」 ở thể từ điển là gì?","options":["かえる","かう","かく","かける"],"answer":0,"explain":"かえります → thể từ điển かえる (về)."},{"q":"Chuyến đi Kyoto diễn ra khi nào?","options":["きょう (hôm nay)","あした (ngày mai)","きのう (hôm qua)","らいしゅう (tuần sau)"],"answer":2,"explain":"Đoạn bắt đầu bằng 「きのう」 = hôm qua."}]},"6":{"ext":"へいじつは がっこうで にほんごを べんきょうします。よるは ときどき おんがくを ききます。","qs":[{"q":"Ngày thường, người viết học tiếng Nhật ở đâu?","options":["うち (nhà)","としょかん (thư viện)","がっこう (trường)","こうえん (công viên)"],"answer":2,"explain":"「へいじつは がっこうで にほんごを べんきょうします」."},{"q":"Ban đêm, thỉnh thoảng người viết làm gì?","options":["おんがくを きく (nghe nhạc)","えいがを みる (xem phim)","りょうりを する (nấu ăn)","うんどうを する (tập thể thao)"],"answer":0,"explain":"「よるは ときどき おんがくを ききます」."},{"q":"Từ 「ときどき」 nghĩa là gì?","options":["Mỗi ngày","Thỉnh thoảng","Không bao giờ","Luôn luôn"],"answer":1,"explain":"「ときどき」 = thỉnh thoảng, đôi khi."},{"q":"Câu nào đúng với đoạn văn?","options":["Mỗi tối người viết xem tivi","Cuối tuần người viết đi デパート mua sắm","Người viết đi dạo một mình","Ngày thường người viết không học"],"answer":1,"explain":"「しゅうまつは デパートへ いきます。デパートで かいものを します」."},{"q":"Người viết đi dạo cùng ai?","options":["かぞく","せんせい","ひとり","ともだち"],"answer":3,"explain":"「ときどき ともだちと こうえんで さんぽを します」."},{"q":"Chủ đề chính của đoạn văn là gì?","options":["Cách mua sắm ở デパート","Thói quen hằng ngày và cuối tuần của người viết","Cách đi dạo ở công viên","Trường học của người viết"],"answer":1,"explain":"Đoạn kể thói quen: mỗi tối đọc sách, cuối tuần đi mua sắm, ngày thường học ở trường."}]},"7":{"ext":"クリスマスは １２がつ ２５にちです。ことしの クリスマスは ともだちと パーティーを します。","qs":[{"q":"Giáng sinh là ngày nào?","options":["１２がつ ２４にち","１２がつ ２５にち","１がつ １にち","１２がつ ３１にち"],"answer":1,"explain":"「クリスマスは １２がつ ２５にちです」."},{"q":"Giáng sinh năm nay người viết sẽ làm gì?","options":["くにへ かえる","ともだちと パーティーを する","ひとりで ねる","はたらく"],"answer":1,"explain":"「ことしの クリスマスは ともだちと パーティーを します」 = tổ chức tiệc với bạn."},{"q":"Từ 「もう」 trong câu 「もう クリスマスの プレゼントを かいました」 nghĩa là gì?","options":["Chưa","Đã (rồi)","Sắp","Chỉ"],"answer":1,"explain":"「もう + quá khứ」 = đã làm rồi."},{"q":"Câu nào KHÔNG đúng với đoạn văn?","options":["Hôm qua là sinh nhật người viết","Người viết nhận hoa từ bạn","Người viết chưa mua quà Giáng sinh","Người viết tặng quà cho thầy/cô"],"answer":2,"explain":"Đoạn nói 「もう かいました」 = đã mua rồi, nên 'chưa mua' là sai."},{"q":"Trong câu 「はなを もらいました」, người nhận hoa là ai?","options":["ともだち","せんせい","Người viết","おかあさん"],"answer":2,"explain":"もらいます: người viết nhận từ bạn — 「ともだちに はなを もらいました」."},{"q":"Đoạn văn chủ yếu kể về điều gì?","options":["Sinh nhật và quà tặng","Một bữa tiệc Giáng sinh năm ngoái","Cách làm bánh sinh nhật","Sinh nhật của thầy/cô"],"answer":0,"explain":"Đoạn xoay quanh sinh nhật hôm qua và các món quà cho/nhận."}]},"8":{"ext":"わたしは この まちが すきです。まいあさ こうえんで さんぽを します。","qs":[{"q":"Người viết có thích thị trấn của mình không?","options":["Không thích lắm","Rất thích (すきです)","Ghét","Không nói gì"],"answer":1,"explain":"「わたしは この まちが すきです」."},{"q":"Mỗi sáng người viết làm gì ở công viên?","options":["さんぽ (đi dạo)","サッカー (đá bóng)","べんきょう (học)","かいもの (mua sắm)"],"answer":0,"explain":"「まいあさ こうえんで さんぽを します」."},{"q":"Từ 「べんり」 nghĩa là gì?","options":["Yên tĩnh","Tiện lợi","Ngon","Tốt bụng"],"answer":1,"explain":"「べんり」 = tiện lợi, thuận tiện."},{"q":"Điểm chưa tốt của thị trấn là gì?","options":["Nhà hàng không ngon","Mọi người lạnh lùng","Giao thông không tiện lắm","Thị trấn quá ồn"],"answer":2,"explain":"「こうつうは あまり べんりじゃありません」."},{"q":"Câu nào đúng với đoạn văn?","options":["Thị trấn ồn ào và bẩn","Nhà hàng rất ngon và mọi người tốt bụng","Giao thông rất tiện","Người viết không thích thị trấn"],"answer":1,"explain":"「レストランは とても おいしいです。ひとびとは しんせつです」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Giới thiệu thị trấn của người viết","Hướng dẫn đường đi","Thực đơn nhà hàng","Lịch trình xe buýt"],"answer":0,"explain":"Đoạn giới thiệu thị trấn: cảnh quan, giao thông, nhà hàng, con người."}]},"9":{"ext":"まいにち サッカーの れんしゅうを します。らいねん サッカーの しあいに でたいです。","qs":[{"q":"Mỗi ngày người viết luyện tập môn gì?","options":["テニス","すいえい","サッカー","やきゅう"],"answer":2,"explain":"「まいにち サッカーの れんしゅうを します」."},{"q":"Năm sau người viết muốn làm gì?","options":["サッカーの しあいに でる (tham gia trận bóng đá)","テニスを やめる (bỏ tennis)","えいごを ならう (học tiếng Anh)","くにへ かえる (về nước)"],"answer":0,"explain":"「らいねん サッカーの しあいに でたいです」."},{"q":"Khả năng tiếng Anh của người viết so với tiếng Nhật thế nào?","options":["Giỏi hơn tiếng Nhật","Bằng tiếng Nhật","Kém hơn hẳn — tiếng Nhật hiểu một chút, tiếng Anh hoàn toàn không","Cả hai đều giỏi"],"answer":2,"explain":"Tiếng Nhật 「すこし わかります」 còn tiếng Anh 「ぜんぜん わかりません」."},{"q":"Câu nào KHÔNG đúng với đoạn văn?","options":["Người viết thích thể thao","Người viết rất thích tennis","Người viết hiểu tiếng Nhật một chút","Người viết đặc biệt thích bóng đá"],"answer":1,"explain":"「テニスは あまり すきじゃありません」 — không thích tennis lắm."},{"q":"Từ 「わかります」 nghĩa là gì?","options":["Nói được","Hiểu","Đọc được","Viết được"],"answer":1,"explain":"「わかります」 = hiểu."},{"q":"Đoạn văn chủ yếu nói về điều gì?","options":["Sở thích thể thao và khả năng ngôn ngữ của người viết","Một trận bóng đá","Cách học tiếng Anh","Trường học của người viết"],"answer":0,"explain":"Nửa đầu nói sở thích thể thao, nửa sau nói mức độ hiểu tiếng Nhật/tiếng Anh."}]},"10":{"ext":"ドアの まえに いすが あります。ほんだなには ほんが たくさん あります。","qs":[{"q":"Trước cửa có vật gì?","options":["いす (ghế)","テーブル (bàn ăn)","ソファ","とけい (đồng hồ)"],"answer":0,"explain":"「ドアの まえに いすが あります」."},{"q":"Trên giá sách có gì?","options":["かばん","ほんが たくさん","テレビ","パソコン"],"answer":1,"explain":"「ほんだなには ほんが たくさん あります」 = trên giá sách có nhiều sách."},{"q":"Vật nào KHÔNG xuất hiện trong đoạn văn?","options":["パソコン","テレビ","ベッド","ソファ"],"answer":3,"explain":"Đoạn nhắc máy tính, tivi, giường, cặp, ghế, sách — không có ghế sofa."},{"q":"Từ 「ちかく」 nghĩa là gì?","options":["Bên trên","Gần","Bên trong","Đằng sau"],"answer":1,"explain":"「ちかく」 = gần, vùng lân cận."},{"q":"Câu nào đúng về vị trí đồ vật?","options":["Cặp ở trên bàn","Máy tính ở dưới bàn","Cặp ở dưới bàn","Giường ở cạnh bàn"],"answer":2,"explain":"「つくえの したに かばんが あります」 = cặp ở dưới bàn."},{"q":"Chủ đề của đoạn văn là gì?","options":["Giới thiệu căn phòng của người viết","Cách dọn phòng","Mua đồ nội thất","Phòng của bạn người viết"],"answer":0,"explain":"Đoạn mô tả căn phòng và vị trí các đồ vật trong phòng."}]},"11":{"ext":"こうえんで かぞくと おべんとうを たべました。おべんとうは おかあさんが つくりました。","qs":[{"q":"Họ đã ăn gì ở công viên?","options":["おべんとう (cơm hộp)","りんご (chỉ táo)","サンドイッチ","ケーキ"],"answer":0,"explain":"「こうえんで かぞくと おべんとうを たべました」."},{"q":"Ai đã làm cơm hộp?","options":["おとうさん","おかあさん","Người viết","おねえさん"],"answer":1,"explain":"「おべんとうは おかあさんが つくりました」."},{"q":"Từ 「たくさん」 nghĩa là gì?","options":["Một chút","Nhiều","Tất cả","Một nửa"],"answer":1,"explain":"「たくさん」 = nhiều."},{"q":"Câu nào đúng với đoạn văn?","options":["Hôm nay người viết đi công viên với gia đình","Công viên không có ai","Họ mua 3 quả táo","Họ đi dạo 2 tiếng"],"answer":0,"explain":"「きょうは かぞくと こうえんへ いきました」."},{"q":"Họ mua táo ở đâu?","options":["Ở công viên","Ở siêu thị","Đoạn văn không nhắc đến","Ở nhà"],"answer":2,"explain":"Đoạn chỉ nói mua 5 quả táo, không nói mua ở đâu."},{"q":"Trợ từ đếm 「つ」 trong 「りんごを ５つ」 dùng để đếm gì?","options":["Người","Vật nói chung","Quyển sách","Con vật"],"answer":1,"explain":"「～つ」 là cách đếm vật thông dụng (1つ、2つ…5つ)."}]},"12":{"ext":"あしたは そらが はれます。でも、きょうの よるは すこし さむく なります。","qs":[{"q":"Đêm nay thời tiết sẽ thế nào?","options":["すこし さむく なる (hơi lạnh hơn)","もっと あたたかく なる","あめが ふる","ゆきが ふる"],"answer":0,"explain":"「きょうの よるは すこし さむく なります」."},{"q":"Ngày mai bầu trời thế nào?","options":["くもり (nhiều mây)","はれる (nắng, quang đãng)","あめ (mưa)","かぜが つよい (gió mạnh)"],"answer":1,"explain":"「あしたは そらが はれます」."},{"q":"Từ 「もっと」 nghĩa là gì?","options":["Ít hơn","Hơn nữa","Bằng nhau","Một chút"],"answer":1,"explain":"「もっと」 = hơn nữa — mai còn ấm hơn nữa."},{"q":"Câu nào đúng với đoạn văn?","options":["Hôm qua nắng, hôm nay lạnh","Hôm qua mưa, hôm nay ấm hơn hôm qua","Ngày mai lạnh nhất tháng","Cả tháng trời đều mưa"],"answer":1,"explain":"「きのうは あめでした。きょうは きのうより あたたかいです」."},{"q":"Từ nào được dùng để nói 'nhất' trong đoạn?","options":["もっと","より","いちばん","すこし"],"answer":2,"explain":"「いちばん あたたかい」 = ấm nhất (so sánh nhất)."},{"q":"Chủ đề của đoạn văn là gì?","options":["Thời tiết mấy ngày liên tiếp","Một chuyến đi chơi","Quần áo theo mùa","Dự báo bão"],"answer":0,"explain":"Đoạn so sánh thời tiết hôm qua – hôm nay – ngày mai."}]},"13":{"ext":"じてんしゃは デパートの ５かいで うって います。あかい じてんしゃが いいですが、たかいです。","qs":[{"q":"Xe đạp được bán ở tầng mấy của デパート?","options":["３かい","５かい","１かい","２かい"],"answer":1,"explain":"「じてんしゃは デパートの ５かいで うって います」."},{"q":"Chiếc xe đạp màu đỏ thế nào?","options":["Rẻ và đẹp","Thích nhưng đắt","Không thích","Đã bán hết"],"answer":1,"explain":"「あかい じてんしゃが いいですが、たかいです」 = xe đỏ thì thích nhưng đắt."},{"q":"Người viết có nhiều tiền không?","options":["Có rất nhiều","Không — chỉ có một ít tiền","Vừa đủ mua xe đắt","Không nhắc đến tiền"],"answer":1,"explain":"「おかねは すこししか ありません」 = tiền chỉ có ít thôi."},{"q":"Từ 「さがします」 nghĩa là gì?","options":["Mua","Tìm kiếm","Bán","Sửa"],"answer":1,"explain":"「さがします」 = tìm, tìm kiếm."},{"q":"Mục đích người viết đi デパート tuần sau là gì?","options":["Mua xe đạp","Xem phim","Gặp bạn","Mua quần áo"],"answer":0,"explain":"「デパートへ じてんしゃを かいに いきます」 = đi mua xe đạp."},{"q":"Câu nào đúng với đoạn văn?","options":["Người viết muốn xe rẻ vì ít tiền","Người viết muốn xe đắt nhất","Người viết đã mua xe rồi","Người viết không thích xe màu đỏ"],"answer":0,"explain":"Ít tiền (すこししか ない) nên tìm xe rẻ (やすい じてんしゃを さがします)."}]},"14":{"ext":"かいぎは １０じからです。しりょうは ２０まい コピーしました。","qs":[{"q":"Cuộc họp bắt đầu lúc mấy giờ?","options":["９じ","１０じ","１１じ","あしたの ごご"],"answer":1,"explain":"「かいぎは １０じからです」."},{"q":"Tài liệu đã được copy bao nhiêu tờ?","options":["１０まい","１５まい","２０まい","５０まい"],"answer":2,"explain":"「しりょうは ２０まい コピーしました」."},{"q":"Từ 「わたします」 nghĩa là gì?","options":["Nhận","Đưa/giao cho","Đọc","Viết"],"answer":1,"explain":"「わたします」 = trao, đưa cho người khác."},{"q":"Trình tự đúng trong đoạn là gì?","options":["Đưa tài liệu → copy","Copy xong → đưa tài liệu","Họp → copy","Đọc tài liệu → họp"],"answer":1,"explain":"「コピーが おわってから、しりょうを わたします」."},{"q":"Mẫu 「～てから」 diễn tả điều gì?","options":["Đang làm dở","Sau khi làm xong việc trước mới làm việc sau","Cùng lúc hai việc","Lý do"],"answer":1,"explain":"Vてから = sau khi V (nhấn mạnh thứ tự)."},{"q":"Câu nào đúng với đoạn văn?","options":["Tài liệu dùng cho cuộc họp ngày mai","Tài liệu dùng cho buổi học hôm nay","Người viết đang họp","Người nghe phải đi copy"],"answer":0,"explain":"「あしたの かいぎで つかいます」."}]},"15":{"ext":"としょかんは ９じから ５じまでです。ほんは ２しゅうかん かりることが できます。","qs":[{"q":"Thư viện mở cửa trong khoảng thời gian nào?","options":["８じから ６じまで","９じから ５じまで","１０じから ４じまで","９じから ９じまで"],"answer":1,"explain":"「としょかんは ９じから ５じまでです」."},{"q":"Sách được mượn trong bao lâu?","options":["１しゅうかん","３しゅうかん","２しゅうかん","１かげつ"],"answer":2,"explain":"「ほんは ２しゅうかん かりることが できます」."},{"q":"Cụm 「おおきな こえ」 nghĩa là gì?","options":["Tiếng cười","Giọng nói lớn","Tiếng nhạc","Tiếng chuông"],"answer":1,"explain":"「おおきな こえで はなす」 = nói bằng giọng lớn."},{"q":"Mẫu 「～ては いけません」 nghĩa là gì?","options":["Được phép làm","Không được phép làm (cấm)","Nên làm","Phải làm"],"answer":1,"explain":"Vては いけません = cấm, không được làm."},{"q":"Việc nào bị cấm ở thư viện?","options":["Mượn sách","Nói chuyện to","Ngồi đọc sách","Vào thư viện buổi sáng"],"answer":1,"explain":"「おおきな こえで はなしては いけません」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Quy định ở thư viện","Cách mượn sách online","Giới thiệu một cuốn sách","Lịch học ở trường"],"answer":0,"explain":"Đoạn nêu điều cấm, điều được phép và giờ mở cửa của thư viện."}]},"16":{"ext":"がっこうで ともだちと あそんでから、うちへ かえります。よるは テレビを すこし みます。","qs":[{"q":"Sau khi chơi với bạn ở trường, người viết làm gì?","options":["うちへ かえる (về nhà)","としょかんへ いく","かいものを する","そのまま ねる"],"answer":0,"explain":"「ともだちと あそんでから、うちへ かえります」."},{"q":"Buổi tối người viết xem tivi thế nào?","options":["みない","すこし みる","３じかん みる","まいばん えいがを みる"],"answer":1,"explain":"「よるは テレビを すこし みます」 = xem một chút."},{"q":"Thứ tự đúng vào buổi sáng là gì?","options":["Ăn sáng → rửa mặt → dậy → đi học","Dậy → rửa mặt → ăn sáng → đi học","Dậy → đi học → ăn sáng → rửa mặt","Rửa mặt → dậy → đi học → ăn sáng"],"answer":1,"explain":"「おきます。かおを あらって、あさごはんを たべて、がっこうへ いきます」."},{"q":"Cụm 「かえってから」 nghĩa là gì?","options":["Trước khi về","Sau khi về","Trong lúc về","Vì đã về"],"answer":1,"explain":"Vてから = sau khi làm xong hành động đó."},{"q":"Người viết đến trường bằng phương tiện gì?","options":["でんしゃ","バス","じてんしゃ","あるいて"],"answer":2,"explain":"「がっこうは じてんしゃで １５ふんです」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Một ngày thường nhật của người viết","Một ngày nghỉ lễ","Chuyến dã ngoại của trường","Bài tập về nhà"],"answer":0,"explain":"Đoạn kể trình tự hoạt động từ sáng đến tối."}]},"17":{"ext":"あめが ふったら、たいいくかんで します。たべものは もって こないで ください。","qs":[{"q":"Nếu trời mưa, ngày thể thao sẽ tổ chức ở đâu?","options":["がっこうの にわ","たいいくかん (nhà thi đấu)","こうえん","きょうしつ"],"answer":1,"explain":"「あめが ふったら、たいいくかんで します」."},{"q":"Học sinh không được mang theo thứ gì?","options":["みず","たべもの (đồ ăn)","ぼうし","くつ"],"answer":1,"explain":"「たべものは もって こないで ください」 = đừng mang đồ ăn."},{"q":"Mẫu 「～なければ なりません」 nghĩa là gì?","options":["Không được làm","Phải làm","Được phép không làm","Muốn làm"],"answer":1,"explain":"Vなければ なりません = phải (không làm không được)."},{"q":"Mẫu 「～ないで ください」 trong đoạn dùng để nói gì?","options":["Xin hãy làm","Xin đừng làm","Hãy làm nhanh","Được phép làm"],"answer":1,"explain":"「わすれないで ください」 = xin đừng quên."},{"q":"Câu nào đúng với đoạn văn?","options":["Học sinh phải đến trường trước 8 giờ","Học sinh không được mang nước","Ngày mai là ngày nghỉ","Giày có thể quên cũng được"],"answer":0,"explain":"「８じまでに がっこうへ こなければ なりません」."},{"q":"Đoạn văn là loại thông báo về sự kiện nào?","options":["Ngày hội thể thao","Ngày thi","Ngày dã ngoại","Ngày khai giảng"],"answer":0,"explain":"「あしたは スポーツの ひです」."}]},"18":{"ext":"まいしゅう ともだちに すしを つくります。ともだちは「おいしい」と いいます。","qs":[{"q":"Mỗi tuần người viết làm sushi cho ai?","options":["かぞく","ともだち","せんせい","じぶん"],"answer":1,"explain":"「まいしゅう ともだちに すしを つくります」."},{"q":"Người bạn nói gì về món sushi?","options":["「からい」 (cay)","「おいしい」 (ngon)","「たかい」 (đắt)","「すくない」 (ít)"],"answer":1,"explain":"「ともだちは『おいしい』と いいます」."},{"q":"Từ 「しゅみ」 nghĩa là gì?","options":["Công việc","Sở thích","Thói quen xấu","Ước mơ"],"answer":1,"explain":"「しゅみは りょうりです」 = sở thích là nấu ăn."},{"q":"Mẫu 「～ことが できます」 diễn tả điều gì?","options":["Kinh nghiệm đã từng","Khả năng — có thể làm được","Nghĩa vụ phải làm","Mong muốn"],"answer":1,"explain":"「すしを つくることが できます」 = làm được sushi."},{"q":"Câu nào đúng với đoạn văn?","options":["Người viết làm được sushi nhưng không làm được bánh kem","Người viết làm được bánh kem nhưng không làm được sushi","Người viết không biết nấu ăn","Người viết ghét nấu ăn"],"answer":0,"explain":"「すしを つくることが できます。でも、ケーキを つくることは できません」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Sở thích nấu ăn và khả năng của người viết","Một bữa tiệc sushi","Cách làm bánh kem","Nhà hàng yêu thích"],"answer":0,"explain":"Đoạn nói về sở thích nấu ăn, món làm được và chưa làm được."}]},"19":{"ext":"ふじさんは にほんで いちばん たかい やまです。のぼる まえに、れんしゅうを します。","qs":[{"q":"Núi Phú Sĩ là ngọn núi thế nào ở Nhật Bản?","options":["いちばん ひくい","いちばん たかい (cao nhất)","いちばん ゆうめいな だけ","いちばん ちいさい"],"answer":1,"explain":"「ふじさんは にほんで いちばん たかい やまです」."},{"q":"Trước khi leo núi, người viết làm gì?","options":["れんしゅう (luyện tập)","りょこうの よていを たてる","やすむ","しゃしんを とる"],"answer":0,"explain":"「のぼる まえに、れんしゅうを します」 — mẫu ～まえに."},{"q":"Mẫu 「～たことが あります」 diễn tả điều gì?","options":["Khả năng","Kinh nghiệm — đã từng làm","Dự định","Nghĩa vụ"],"answer":1,"explain":"「およいだことが あります」 = đã từng bơi."},{"q":"Câu nào đúng với đoạn văn?","options":["Đã bơi ở biển nhưng chưa leo núi Phú Sĩ","Đã leo Phú Sĩ nhiều lần","Không muốn leo núi nữa","Cơ thể yếu đi"],"answer":0,"explain":"「うみに およいだことが あります。でも、ふじさんに のぼったことは ありません」."},{"q":"Cụm 「つよく なりました」 chỉ sự thay đổi nào?","options":["Đã trở nên khỏe hơn","Đã trở nên yếu hơn","Đã trở nên bận hơn","Không thay đổi"],"answer":0,"explain":"なりました diễn tả sự thay đổi trạng thái: cơ thể đã khỏe lên."},{"q":"Mong muốn của người viết vào mùa hè năm nay là gì?","options":["およぐ","ふじさんに のぼる","くにへ かえる","スキーを する"],"answer":1,"explain":"「ことしの なつ、ふじさんに のぼりたいです」."}]},"20":{"ext":"「えいがは ２じかんぐらいだよ。」「じゃ、ポップコーンを かおう。」","qs":[{"q":"Bộ phim dài khoảng bao lâu?","options":["１じかん","２じかんぐらい","３じかん","３０ぷん"],"answer":1,"explain":"「えいがは ２じかんぐらいだよ」 = phim khoảng 2 tiếng."},{"q":"Họ định mua thêm gì?","options":["のみもの","ポップコーン (bỏng ngô)","チケット","おかし"],"answer":1,"explain":"「じゃ、ポップコーンを かおう」 — thể ý chí thân mật かおう."},{"q":"Thể thường (thể từ điển) của 「みます」 là gì?","options":["みる","みた","みない","みよう"],"answer":0,"explain":"Trong hội thoại thân mật: みます → みる."},{"q":"Câu 「わかった」 trong đoạn thể hiện điều gì?","options":["Từ chối","Đồng ý / đã hiểu (nói thân mật)","Ngạc nhiên","Xin lỗi"],"answer":1,"explain":"「わかった。じゃ、あした。」 = Rồi, hiểu rồi. Mai nhé."},{"q":"Họ hẹn gặp nhau lúc mấy giờ ở ga?","options":["３じ","２じ","Đoạn văn không nói giờ gặp","５じ"],"answer":2,"explain":"Đoạn chỉ nói phim bắt đầu lúc 3 giờ và hẹn gặp ở ga, không nói giờ gặp."},{"q":"Đoạn hội thoại này diễn ra giữa những người có quan hệ thế nào?","options":["Bạn bè thân mật","Thầy và trò","Khách và nhân viên","Cấp trên và cấp dưới"],"answer":0,"explain":"Toàn bộ dùng thể thường (みる？・わかった・あおう) — chỉ dùng với bạn bè thân thiết."}]},"21":{"ext":"ともだちは「いっしょに べんきょうしよう」と いいました。わたしも がんばると おもいます。","qs":[{"q":"Người bạn đã nói gì?","options":["Rủ người viết cùng học","Hẹn đi chơi","Nói mai không có kiểm tra","Nhờ làm bài hộ"],"answer":0,"explain":"「いっしょに べんきょうしようと いいました」 = nói 'cùng học nhé'."},{"q":"Người viết nghĩ mình sẽ làm gì?","options":["がんばる (cố gắng)","やすむ (nghỉ)","あそぶ (chơi)","てつだう (giúp bạn)"],"answer":0,"explain":"「わたしも がんばると おもいます」."},{"q":"Mẫu 「～と おもいます」 dùng để làm gì?","options":["Trích dẫn lời người khác","Nói suy nghĩ / dự đoán của mình","Ra lệnh","Xin phép"],"answer":1,"explain":"「あめが ふると おもいます」 = tôi nghĩ trời sẽ mưa."},{"q":"Vì sao tối nay người viết học bài?","options":["Vì bạn rủ đi chơi","Vì ngày mai có bài kiểm tra","Vì bài kiểm tra dễ","Vì thầy giáo đến nhà"],"answer":1,"explain":"Thầy nói 「あした テストが あります」 nên 「ですから、きょうの よる べんきょうします」."},{"q":"Từ 「でしょう」 ở cuối đoạn diễn tả điều gì?","options":["Sự chắc chắn tuyệt đối","Dự đoán — 'chắc là...'","Câu hỏi về quá khứ","Mệnh lệnh"],"answer":1,"explain":"「テストは むずかしいでしょう」 = bài kiểm tra chắc sẽ khó."},{"q":"Chủ đề của đoạn văn là gì?","options":["Chuẩn bị cho bài kiểm tra ngày mai","Dự báo thời tiết cuối tuần","Kế hoạch đi chơi với bạn","Kết quả bài kiểm tra"],"answer":0,"explain":"Mưa dự đoán, thông báo kiểm tra và quyết định học bài tối nay đều hướng về bài kiểm tra ngày mai."}]},"22":{"ext":"せんせいが かいた ほんも としょかんに あります。わたしは その ほんを よみたいです。","qs":[{"q":"Cuốn sách do thầy viết được để ở đâu?","options":["がっこう","としょかん (thư viện)","ほんや","せんせいの うち"],"answer":1,"explain":"「せんせいが かいた ほんも としょかんに あります」."},{"q":"Người viết muốn làm gì với cuốn sách đó?","options":["かいたい","よみたい (muốn đọc)","かりたくない","うりたい"],"answer":1,"explain":"「その ほんを よみたいです」."},{"q":"Cụm 「きのう よんだ ほん」 nghĩa là gì?","options":["Cuốn sách sẽ đọc hôm qua","Cuốn sách đã đọc hôm qua","Cuốn sách mua hôm qua","Cuốn sách của hôm qua"],"answer":1,"explain":"Mệnh đề thể thường đứng trước danh từ để bổ nghĩa: ほん mà (tôi) đã đọc hôm qua."},{"q":"Mệnh đề bổ nghĩa đứng ở vị trí nào so với danh từ?","options":["Sau danh từ","Trước danh từ","Cuối câu","Sau trợ từ は"],"answer":1,"explain":"「はなして いる ひと」「よんだ ほん」 — mệnh đề luôn đứng trước danh từ được bổ nghĩa."},{"q":"Khẳng định nào sau đây phù hợp với nội dung đoạn văn?","options":["Người đang nói chuyện ở đằng kia là thầy của người viết","Cuốn sách là của bạn người viết","Người viết chưa từng đọc sách của thầy","Thầy đang ở thư viện"],"answer":0,"explain":"「あそこで はなして いる ひとは、わたしの せんせいです」."},{"q":"Ngữ pháp trọng tâm của Bài 22 là gì?","options":["Thể たら điều kiện","Thể thường bổ nghĩa cho danh từ (mệnh đề quan hệ)","Thể khả năng","Thể て いけません"],"answer":1,"explain":"Cả đoạn dùng các cụm mệnh đề thường + danh từ: はなしている ひと, よんだ ほん, かいた ほん."}]},"23":{"ext":"みぎに まがると、ゆうびんきょくが あります。コンビニの まえに バスの ていりゅうじょが あります。","qs":[{"q":"Rẽ phải thì sẽ thấy gì?","options":["びょういん","ゆうびんきょく (bưu điện)","がっこう","えき"],"answer":1,"explain":"「みぎに まがると、ゆうびんきょくが あります」."},{"q":"Trạm xe buýt ở đâu?","options":["えきの まえ","コンビニの まえ","ゆうびんきょくの うしろ","ひだりがわ"],"answer":1,"explain":"「コンビニの まえに バスの ていりゅうじょが あります」."},{"q":"Mẫu 「～とき」 trong đoạn nghĩa là gì?","options":["Sau khi","Khi (vào lúc)","Vì","Dù"],"answer":1,"explain":"「えきに ついたとき」 = khi đến ga."},{"q":"Theo chỉ đường trong đoạn, đi thẳng thì bên trái có gì?","options":["ゆうびんきょく","コンビニ","びょういん","バスの ていりゅうじょ"],"answer":1,"explain":"「まっすぐ いくと、ひだりに コンビニが あります」."},{"q":"Trong 「ボタンを おすと、ドアが あきます」, mẫu 「と」 nối hai vế theo quan hệ nào?","options":["Nguyên nhân chủ quan","Cứ làm A thì tất yếu xảy ra B","Hai việc cùng lúc","Điều kiện ước muốn"],"answer":1,"explain":"～と chỉ hệ quả tất yếu/tự nhiên, cũng dùng khi chỉ đường."},{"q":"Đoạn văn gồm các tình huống dùng những mẫu nào?","options":["～たら và ～ば","～と và ～とき","～ても và ～のに","～ながら và ～つつ"],"answer":1,"explain":"Ba câu dùng おすと・ついたとき・いくと — trọng tâm Bài 23."}]},"24":{"ext":"せんせいは わたしに にほんごを おしえて くださいました。わたしは ともだちに ケーキの つくりかたを おしえて あげました。","qs":[{"q":"Thầy/cô đã làm gì cho người viết?","options":["おしえて くださいました — dạy tiếng Nhật cho","ほんを かして くださいました","ケーキを つくって くださいました","にもつを もって くださいました"],"answer":0,"explain":"「せんせいは わたしに にほんごを おしえて くださいました」 — người trên làm cho mình nên dùng くださる."},{"q":"Người viết đã dạy người bạn điều gì?","options":["にほんご","ケーキの つくりかた (cách làm bánh)","しゅくだい","りょうりの れしぴ"],"answer":1,"explain":"「ともだちに ケーキの つくりかたを おしえて あげました」."},{"q":"Trong mẫu 「～て もらいました」, người nhận ân huệ là ai?","options":["Người làm hành động","Người nói — nhận việc người khác làm cho mình","Người thứ ba","Không có ai"],"answer":1,"explain":"「たなかさんに おしえて もらいました」 = tôi được Tanaka dạy cho."},{"q":"Câu nào diễn tả đúng chiều ân huệ 'anh trai xách hành lý giúp tôi'?","options":["あには わたしに にもつを もって くれました","わたしは あにに にもつを もって あげました","あには にもつを もらいました","わたしは あにから にもつです"],"answer":0,"explain":"Người khác làm cho mình (hướng vào mình) dùng ～て くれました."},{"q":"Từ 「にもつ」 nghĩa là gì?","options":["Bài tập","Hành lý","Quà tặng","Tài liệu"],"answer":1,"explain":"「にもつを もつ」 = xách/cầm hành lý."},{"q":"Chủ đề ngữ pháp của Bài 24 là gì?","options":["Cho – nhận ân huệ: あげる・もらう・くれる","Điều kiện giả định","Kinh nghiệm quá khứ","Khả năng"],"answer":0,"explain":"Cả đoạn xoay quanh ai làm gì cho ai bằng các động từ ân huệ."}]},"25":{"ext":"じかんが あったら、ともだちに あいたいです。おかねが なくても、しあわせです。","qs":[{"q":"Nếu có thời gian, người viết muốn gặp ai?","options":["せんせい","ともだち","かぞく","ともだちの かぞく"],"answer":1,"explain":"「じかんが あったら、ともだちに あいたいです」."},{"q":"Dù không có tiền, người viết cảm thấy thế nào?","options":["かなしい","しあわせ (hạnh phúc)","たいへん","さびしい"],"answer":1,"explain":"「おかねが なくても、しあわせです」 — ～ても nhượng bộ."},{"q":"Mẫu 「～たら」 dùng để diễn tả điều gì?","options":["Điều kiện giả định — 'nếu... thì...'","Kinh nghiệm quá khứ","Thứ tự thời gian đơn thuần","Sự cho phép"],"answer":0,"explain":"「おかねが あったら」 = nếu có tiền (giả định)."},{"q":"Theo đoạn văn, để đi du lịch cần những điều kiện nào?","options":["Chỉ cần tiền","Chỉ cần thời gian","Cần cả tiền và thời gian","Không cần điều kiện gì"],"answer":2,"explain":"「おかねが あっても、じかんが なければ いけません」 — có tiền mà không có thời gian cũng không đi được."},{"q":"Từ 「もし」 thường đi kèm với mẫu nào để nhấn mạnh giả định?","options":["～たら","～てから","～とき","～ながら"],"answer":0,"explain":"「もし １００まんえん あったら…」 — もし tăng sắc thái giả định cho ～たら."},{"q":"Nếu có 100 vạn yên, ước muốn lớn nhất của người viết là gì?","options":["Mua xe mới","Về nước gặp gia đình","Đi du lịch châu Âu","Mở cửa hàng"],"answer":1,"explain":"「くにへ かえって、かぞくに あいたいです」."}]}},"N4":{"1":{"ext":"会社（かいしゃ）まで 電車（でんしゃ）で ３０分（ぷん）ぐらいの ところが いいです。スーパーに 近（ちか）いと、もっと 便利（べんり）です。","qs":[{"q":"Người viết muốn nhà cách công ty bao lâu đi tàu?","options":["Khoảng 10 phút","Khoảng 30 phút","Khoảng 1 giờ","Khoảng 5 phút"],"answer":1,"explain":"「会社まで電車で３０分ぐらいのところがいいです」."},{"q":"Nhà gần siêu thị thì sẽ thế nào?","options":["Đắt hơn","Ồn hơn","Tiện lợi hơn","Chật hơn"],"answer":2,"explain":"「スーパーに近いと、もっと便利です」."},{"q":"Mẫu 「んです」 trong đoạn dùng để làm gì?","options":["Ra lệnh","Giải thích tình hình / hoàn cảnh","Hỏi về quá khứ","Xin phép"],"answer":1,"explain":"「働くんです」「いいんです」 — ～んです giải thích bối cảnh cho người nghe."},{"q":"Câu nào đúng với đoạn văn?","options":["Đang tìm nhà gần ga, yên tĩnh, tiền thuê tối đa khoảng 8 vạn yên","Đã tìm được nhà và dọn vào ở","Muốn nhà rộng và đắt cũng được","Muốn nhà gần trường học"],"answer":0,"explain":"Tổng hợp cả đoạn: 「駅に近くて、静かなところ」「家賃は８万円ぐらいまで」."},{"q":"Từ 「家賃（やちん）」 nghĩa là gì?","options":["Tiền điện nước","Tiền thuê nhà","Tiền đặt cọc","Tiền sửa nhà"],"answer":1,"explain":"家賃 = tiền thuê nhà hàng tháng."},{"q":"Người viết bắt đầu làm việc ở Tokyo từ khi nào?","options":["Từ tuần sau","Từ tháng sau","Từ năm sau","Đã làm từ tháng trước"],"answer":1,"explain":"「来月から東京で働くんです」."}]},"2":{"ext":"ピアノも 弾（ひ）けますが、ギターは 弾（ひ）けません。来年（らいねん）は 中国語（ちゅうごくご）も 話（はな）せるように なりたいです。","qs":[{"q":"Anh Miller chơi được nhạc cụ nào?","options":["Đàn guitar","Đàn piano","Violin","Sáo"],"answer":1,"explain":"「ピアノも弾けますが、ギターは弾けません」."},{"q":"Năm sau anh ấy muốn nói được thêm ngôn ngữ nào?","options":["Tiếng Pháp","Tiếng Trung","Tiếng Đức","Tiếng Việt"],"answer":1,"explain":"「来年は中国語も話せるようになりたいです」."},{"q":"Thể khả năng của động từ 「話（はな）す」 là gì?","options":["話される","話させる","話せる","話した"],"answer":2,"explain":"Động từ nhóm 1: 話す → 話せる (Bài 27)."},{"q":"Câu nào đúng với đoạn văn?","options":["Đọc được khoảng 500 chữ Hán nhưng chưa đọc nhanh được","Nói được tiếng Anh và tiếng Trung","Không đọc được chữ Hán nào","Viết chữ Hán rất nhanh"],"answer":0,"explain":"「漢字は５００字ぐらい読めます。でも、速く読むことはまだできません」."},{"q":"Cụm 「まだ できません」 nghĩa là gì?","options":["Không bao giờ làm được","Vẫn chưa làm được","Không muốn làm","Làm được một chút"],"answer":1,"explain":"まだ + phủ định khả năng = vẫn chưa thể."},{"q":"Chủ đề của đoạn văn là gì?","options":["Khả năng ngôn ngữ và nhạc cụ của anh Miller","Lịch học của anh Miller","Công việc của anh Miller","Sở thích du lịch"],"answer":0,"explain":"Đoạn liệt kê những việc anh Miller làm được và chưa làm được."}]},"3":{"ext":"休（やす）みの 日（ひ）は、音楽（おんがく）を 聞（き）きながら 掃除（そうじ）を します。弟（おとうと）は テレビを 見（み）ながら 宿題（しゅくだい）を します。","qs":[{"q":"Vào ngày nghỉ, chị gái làm gì trong khi nghe nhạc?","options":["Nấu ăn","Dọn dẹp","Học bài","Chạy bộ"],"answer":1,"explain":"「休みの日は、音楽を聞きながら掃除をします」."},{"q":"Em trai làm gì trong khi xem tivi?","options":["Ăn tối","Ngủ","Làm bài tập","Chơi game"],"answer":2,"explain":"「テレビを見ながら宿題をします」."},{"q":"Mẫu 「ながら」 yêu cầu hai hành động phải thế nào?","options":["Do hai người khác nhau làm","Do cùng một chủ ngữ thực hiện đồng thời","Xảy ra ở hai thời điểm khác nhau","Một hành động là nguyên nhân của hành động kia"],"answer":1,"explain":"～ながら nối hai hành động cùng lúc của cùng một người."},{"q":"Từ 「別（べつ）の」 nghĩa là gì?","options":["Đặc biệt","Khác","Giống hệt","Quan trọng"],"answer":1,"explain":"「別のこと」 = việc khác."},{"q":"Câu nào đúng về chị gái?","options":["Chị chỉ làm được một việc một lúc","Chị có thể làm việc khác trong khi đang làm một việc","Chị ghét âm nhạc","Chị không bao giờ nghe điện thoại"],"answer":1,"explain":"「何かをしながら、別のこともできる人です」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Thói quen làm hai việc cùng lúc","Âm nhạc yêu thích của gia đình","Việc nhà trong gia đình","Bài tập của em trai"],"answer":0,"explain":"Cả đoạn minh họa mẫu ～ながら qua các thành viên gia đình."}]},"4":{"ext":"母（はは）が 帰（かえ）って きたとき、窓（まど）は 閉（し）まって いました。弟（おとうと）は もう 謝（あやま）りました。","qs":[{"q":"Khi mẹ về đến nhà, cửa sổ ở trạng thái nào?","options":["Đang mở","Đã đóng","Bị vỡ","Không có cửa sổ"],"answer":1,"explain":"「窓は閉まっていました」 — tự động từ 閉まる chỉ trạng thái đã đóng."},{"q":"Em trai đã làm gì sau sự việc?","options":["Bỏ chạy ra ngoài","Đã xin lỗi","Lau sàn ngay","Gọi mẹ về"],"answer":1,"explain":"「弟はもう謝りました」 = em trai đã xin lỗi rồi."},{"q":"Cụm 「濡（ぬ）れて いました」 diễn tả điều gì?","options":["Hành động đang lau sàn","Trạng thái sàn đang bị ướt","Lệnh cấm làm ướt","Nguyên nhân trời mưa"],"answer":1,"explain":"Tự động từ + ています = trạng thái kết quả còn tồn tại (Bài 29)."},{"q":"Mẫu 「て しまって」 trong việc làm vỡ cốc mang sắc thái gì?","options":["Vui mừng","Đáng tiếc, ngoài ý muốn","Ra lệnh","Dự định"],"answer":1,"explain":"割ってしまって = lỡ làm vỡ mất — sắc thái hối tiếc của ～てしまう."},{"q":"Câu nào đúng với đoạn văn?","options":["Vào phòng thấy cửa sổ mở, đèn bật và sàn bị ướt","Vào phòng thấy mọi thứ gọn gàng","Em trai làm vỡ đĩa","Mẹ làm vỡ cốc"],"answer":0,"explain":"Tổng hợp ba câu đầu của đoạn gốc."},{"q":"Ai là người làm vỡ cốc?","options":["Mẹ","Người viết","Em trai","Chị gái"],"answer":2,"explain":"「弟がコップを割ってしまって」."}]},"5":{"ext":"ケーキも 買（か）って おきました。友達（ともだち）は ６時（じ）に 来（く）る 予定（よてい）です。","qs":[{"q":"Người viết đã mua sẵn thêm món gì?","options":["Hoa quả","Bánh kem","Nước hoa quả","Bánh mì"],"answer":1,"explain":"「ケーキも買っておきました」 — Vて おく chuẩn bị trước."},{"q":"Người bạn dự định đến lúc mấy giờ?","options":["５時","６時","７時","６時半"],"answer":1,"explain":"「友達は６時に来る予定です」."},{"q":"Mẫu 「Vて おきます」 diễn tả điều gì?","options":["Làm xong rồi bỏ đi","Làm trước để chuẩn bị cho việc sau","Làm thử một lần","Làm hộ người khác"],"answer":1,"explain":"掃除しておきました = dọn sẵn từ trước vì mai bạn đến."},{"q":"Trạng thái 「貼（は）って あります」 cho thấy điều gì?","options":["Ai đó đang dán ảnh ngay lúc này","Ảnh đã được dán sẵn và kết quả còn đó","Ảnh sắp bị gỡ xuống","Không có ảnh nào"],"answer":1,"explain":"Vて あります = trạng thái đã được sắp đặt có chủ đích."},{"q":"Câu nào đúng với đoạn văn?","options":["Mọi thứ đã được chuẩn bị sẵn sàng cho bạn đến chơi","Người viết quên chuẩn bị đồ uống","Bạn sẽ đến vào sáng mai","Tường chưa được trang trí"],"answer":0,"explain":"Dọn phòng, dán ảnh, để đồ uống vào tủ lạnh, mua bánh — tất cả đều là chuẩn bị."},{"q":"Chủ đề của đoạn văn là gì?","options":["Chuẩn bị trước để đón bạn đến nhà","Dọn nhà cuối năm","Sinh nhật của người bạn","Chuyển nhà mới"],"answer":0,"explain":"Toàn đoạn là các hành động ～ておく/～てある chuẩn bị cho khách."}]},"6":{"ext":"店（みせ）の 名前（なまえ）は もう 決（き）めました。「さくら」です。お金（かね）は 銀行（ぎんこう）に 相談（そうだん）する つもりです。","qs":[{"q":"Tên cửa hàng được chọn là gì?","options":["「ゆき」","「さくら」","「うみ」","「ほし」"],"answer":1,"explain":"「店の名前はもう決めました。『さくら』です」."},{"q":"Về vấn đề tiền vốn, người viết dự định làm gì?","options":["Vay bạn bè","Bàn bạc với ngân hàng","Bán nhà","Chờ trúng thưởng"],"answer":1,"explain":"「お金は銀行に相談するつもりです」 — dự định chắc chắn ～つもりです."},{"q":"Mẫu 「ようと 思（おも）っています」 diễn tả mức độ ý định nào?","options":["Ý định đang cân nhắc, đã nghĩ đến nhưng chưa hoàn toàn cố định","Dự định đã quyết chắc chắn từ lâu","Hối tiếc về quá khứ","Mệnh lệnh cho người khác"],"answer":0,"explain":"Bài 31: ～ようと思っています nhẹ hơn ～つもりです."},{"q":"Cho đến nay, ai chưa được nghe kế hoạch về nước?","options":["Bạn bè","Bố mẹ","Ngân hàng","Anh chị em"],"answer":1,"explain":"「まだ両親には話していません」."},{"q":"Từ 「開（ひら）く」 trong 「店（みせ）を 開（ひら）く」 nghĩa là gì?","options":["Đóng","Mở (khai trương)","Thuê","Sửa"],"answer":1,"explain":"店を開く = mở cửa hàng."},{"q":"Kế hoạch sau khi về nước của người viết gồm điều gì?","options":["Mở cửa hàng nhỏ cùng gia đình","Đi du học tiếp","Làm việc cho công ty Nhật ở quê","Nghỉ ngơi một năm"],"answer":0,"explain":"「家族といっしょに小さな店を開くつもりです」."}]},"7":{"ext":"午後（ごご）は 風（かぜ）も 強（つよ）く なるでしょう。出（で）かける 人（ひと）は 早（はや）めに 帰（かえ）ったほうが いいでしょう。","qs":[{"q":"Buổi chiều, gió sẽ thay đổi thế nào?","options":["Yếu dần","Mạnh lên","Đổi hướng","Ngừng hẳn"],"answer":1,"explain":"「午後は風も強くなるでしょう」."},{"q":"Người phải ra ngoài được khuyên làm gì?","options":["Mang theo áo khoác dày","Nên về sớm","Hủy bỏ kế hoạch","Đi bằng taxi"],"answer":1,"explain":"「早めに帰ったほうがいいでしょう」 — lời khuyên ～たほうがいい."},{"q":"Mẫu 「たほうが いい」 dùng để làm gì?","options":["Cấm đoán tuyệt đối","Khuyên nên làm như vậy thì tốt hơn","Kể lại quá khứ","Đặt điều kiện"],"answer":1,"explain":"傘を持って行ったほうがいい = nên mang ô đi."},{"q":"Mẫu ngược lại 「ないほうが いい」 khuyên điều gì?","options":["Nên làm ngay","Không nên làm","Phải làm hai lần","Làm lúc nào cũng được"],"answer":1,"explain":"無理をしないほうがいい = không nên gắng sức."},{"q":"Thông tin thời tiết trong đoạn lấy từ nguồn nào?","options":["Tin tức buổi sáng","Dự báo thời tiết","Quan sát bầu trời","Ứng dụng điện thoại"],"answer":1,"explain":"「天気予報によると」 = theo dự báo thời tiết."},{"q":"Chủ đề của đoạn văn là gì?","options":["Dự báo thời tiết ngày mai và lời khuyên đi kèm","Cách chữa cảm cúm","Lịch trình của một ngày mưa","Tin tức giao thông"],"answer":0,"explain":"Đoạn kết hợp dự đoán ～でしょう với lời khuyên ～たほうがいい/～ないほうがいい."}]},"8":{"ext":"校長先生（こうちょうせんせい）は「明日（あした） 早（はや）く 来（き）なさい」と 言（い）いました。図書館（としょかん）には「静（しず）かに」と 書（か）いて あります。","qs":[{"q":"Hiệu trưởng đã bảo học sinh điều gì?","options":["Ngày mai hãy đến sớm","Ngày mai được nghỉ","Hãy mang theo sách","Hãy về sớm"],"answer":0,"explain":"「明日早く来なさいと言いました」 — mệnh lệnh ～なさい."},{"q":"Ở thư viện có viết câu gì?","options":["「走るな」","「静かに」 (Hãy yên lặng)","「押すな」","「本を返しなさい」"],"answer":1,"explain":"「図書館には『静かに』と書いてあります」."},{"q":"「しなさい」 là dạng mệnh lệnh của động từ nào?","options":["する","くる","いく","みる"],"answer":0,"explain":"静かに しなさい — し là thân của する + なさい."},{"q":"Thể cấm đoán 「押（お）すな」 được tạo thành như thế nào?","options":["Thể ます + な","Thể từ điển + な","Thể て + な","Thể た + な"],"answer":1,"explain":"押す・走る + な = cấm đoán mạnh (Bài 33)."},{"q":"Ai đã nói câu 「静（しず）かに しなさい」?","options":["Hiệu trưởng","Thầy/cô giáo","Thủ thư","Học sinh"],"answer":1,"explain":"「先生は『静かにしなさい』と言いました」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Mệnh lệnh và cấm đoán được viết/truyền đạt lại","Nội quy thư viện đầy đủ","Một buổi họp phụ huynh","Lời chào buổi sáng"],"answer":0,"explain":"Đoạn tập hợp ～なさい, ～な và ～と書いてあります."}]},"9":{"ext":"彼女（かのじょ）は 私（わたし）の 言（い）った とおりに ケーキを 作（つく）りました。とても おいしかったです。","qs":[{"q":"Cô ấy đã làm bánh như thế nào?","options":["Theo công thức trên mạng","Đúng như người viết đã nói","Theo ý thích riêng","Nhờ người khác hướng dẫn"],"answer":1,"explain":"「私の言ったとおりにケーキを作りました」 — Vた + とおりに."},{"q":"Chiếc bánh làm ra thế nào?","options":["Quá ngọt","Rất ngon","Bị cháy","Chưa chín"],"answer":1,"explain":"「とてもおいしかったです」."},{"q":"Mẫu 「ないで」 trong 「眼鏡（めがね）を かけないで」 nghĩa là gì?","options":["Làm B mà không làm A","Sau khi làm A","Vì A nên B","Dù A nhưng B"],"answer":0,"explain":"かけないで本を読む = đọc sách mà không đeo kính."},{"q":"Người viết gặp bạn vào thời điểm nào?","options":["Trước khi làm bài tập","Sau khi làm bài tập","Trong lúc làm bài tập","Thay vì làm bài tập"],"answer":1,"explain":"「宿題をした後で、友達と会いました」 — Vた後で."},{"q":"Câu nào đúng với đoạn văn?","options":["Báo cáo được viết đúng như lời thầy đã nói","Người viết tự viết báo cáo theo ý mình","Người bạn đeo kính khi đọc sách","Bài tập được làm sau khi gặp bạn"],"answer":0,"explain":"「先生の言ったとおりにレポートを書きました」."},{"q":"Ba mẫu của Bài 34 trong đoạn đều liên quan đến điều gì?","options":["Cách thức và thứ tự thực hiện hành động","Nguyên nhân và kết quả","Điều kiện giả định","Suy đoán và truyền văn"],"answer":0,"explain":"～とおりに (đúng như), ～た後で (sau khi), ～ないで (mà không) đều mô tả cách/thứ tự làm việc."}]},"10":{"ext":"雨（あめ）が 降（ふ）らなければ、公園（こうえん）で 運動（うんどう）します。安（やす）い チケットが あれば、コンサートにも 行（い）きたいです。","qs":[{"q":"Nếu trời không mưa, người viết sẽ làm gì?","options":["Ở nhà ngủ","Tập thể thao ở công viên","Đi mua sắm","Học bài ở thư viện"],"answer":1,"explain":"「雨が降らなければ、公園で運動します」 — thể ば phủ định."},{"q":"Nếu có vé rẻ, người viết còn muốn đi đâu nữa?","options":["Xem phim","Buổi hòa nhạc (concert)","Du lịch","Xem bóng đá"],"answer":1,"explain":"「安いチケットがあれば、コンサートにも行きたいです」."},{"q":"Thể ば phủ định của 「降（ふ）る」 là gì?","options":["降らなかったら","降らなければ","降らないと","降れなければ"],"answer":1,"explain":"ない → なければ: 降らない → 降らなければ."},{"q":"Mệnh đề đứng trước thể ば diễn tả điều gì?","options":["Kết quả","Điều kiện","Nguyên nhân quá khứ","Mệnh lệnh"],"answer":1,"explain":"安ければ・あれば đều là vế điều kiện của câu."},{"q":"Câu nào đúng với đoạn văn?","options":["Rẻ thì mua, đắt thì không mua","Đắt rẻ gì cũng mua","Chỉ mua khi giảm giá 50%","Mua khi có lương"],"answer":0,"explain":"「安ければ買いますが、高ければ買いません」."},{"q":"Trong 「何（なに）か あれば」, 「か」 sau từ nghi vấn có tác dụng gì?","options":["Biến thành câu hỏi trực tiếp","Chỉ một điều gì đó không xác định (nếu có chuyện gì)","Nhấn mạnh phủ định","Chỉ thời gian"],"answer":1,"explain":"疑問詞 + か = đại từ bất định: 何か = điều gì đó."}]},"11":{"ext":"子供（こども）が 一人（ひとり）で 学校（がっこう）へ 行（い）けるように なりました。病気（びょうき）に ならないように、毎日（まいにち）運動（うんどう）するように して います。","qs":[{"q":"Đứa trẻ đã đạt được thay đổi gì?","options":["Tự đi học một mình được","Tự nấu ăn được","Tự dậy sớm được","Tự làm bài tập được"],"answer":0,"explain":"「一人で学校へ行けるようになりました」 — ～ようになりました."},{"q":"Để không bị ốm, người viết cố gắng duy trì việc gì mỗi ngày?","options":["Ngủ sớm","Vận động","Ăn nhiều rau","Uống thuốc bổ"],"answer":1,"explain":"「病気にならないように、毎日運動するようにしています」."},{"q":"Mẫu 「ように なりました」 chỉ sự thay đổi nào?","options":["Thay đổi thói quen cố ý","Trạng thái/khả năng đã thay đổi so với trước","Mục đích tương lai","Lời khuyên"],"answer":1,"explain":"聞き取れるようになりました = đã trở nên nghe hiểu được."},{"q":"Mẫu 「ように して います」 chỉ điều gì?","options":["Cố gắng duy trì một thói quen","Một thay đổi bất ngờ","Một khả năng bẩm sinh","Một quy định của công ty"],"answer":0,"explain":"単語はノートに書くようにしています = cố gắng luôn viết từ vào vở."},{"q":"Câu nào đúng với đoạn gốc?","options":["Người viết luyện tập mỗi ngày để nói tiếng Nhật giỏi được","Người viết đã bỏ luyện tập","Người viết không nghe được tin tức","Người viết không ghi chép từ vựng"],"answer":0,"explain":"「上手に話せるように、毎日練習しています」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Ba cách dùng của 「ように」: mục đích, thay đổi, cố gắng duy trì","Cách học từ vựng hiệu quả nhất","Lịch luyện tập của vận động viên","Bệnh tật và sức khỏe"],"answer":0,"explain":"Cả đoạn gốc và phần mở rộng đều xoay quanh ba mẫu ～ように của Bài 36."}]},"12":{"ext":"この 本（ほん）は 多（おお）くの 学生（がくせい）に 読（よ）まれて います。彼（かれ）は 昨日（きのう） 先生（せんせい）に 注意（ちゅうい）されました。","qs":[{"q":"Cuốn sách này được ai đọc?","options":["Chỉ giáo viên","Nhiều học sinh","Chỉ người viết","Học sinh nước ngoài"],"answer":1,"explain":"「多くの学生に読まれています」 — bị động với tác nhân 学生に."},{"q":"Hôm qua anh ấy bị thầy giáo làm gì?","options":["Được khen","Bị nhắc nhở","Được giao thêm bài","Bị đuổi học"],"answer":1,"explain":"「先生に注意されました」 = bị thầy nhắc nhở."},{"q":"Thể bị động của 「褒（ほ）める」 là gì?","options":["褒めさせる","褒められる","褒めれる","褒めさせることがある"],"answer":1,"explain":"Động từ nhóm 2: 褒める → 褒められる."},{"q":"Câu bị động nào trong đoạn gốc mang sắc thái bất lợi cho người viết?","options":["Được thầy khen","Bị mưa làm ướt giày","Trường được xây 50 năm trước","Được mời ăn"],"answer":1,"explain":"「雨に降られて、靴が濡れてしまいました」 — bị động thiệt hại kinh điển."},{"q":"Ngôi trường trong đoạn gốc được xây vào thời gian nào?","options":["10 năm trước","Năm ngoái","50 năm trước","100 năm trước"],"answer":2,"explain":"「５０年前に建てられました」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Thể bị động trong các tình huống khác nhau","Khen thưởng trong trường học","Thời tiết xấu","Lịch sử ngôi trường"],"answer":0,"explain":"褒められる・降られる・建てられる・読まれる・注意される đều là bị động."}]},"13":{"ext":"朝（あさ） 遅（おく）れるのは 困（こま）ります。彼（かれ）が 歌（うた）うのを 聞（き）くのが 好（す）きです。","qs":[{"q":"Việc gì vào buổi sáng khiến người viết phiền lòng?","options":["Thức dậy sớm","Bị muộn (đi trễ)","Quên ăn sáng","Tắc đường"],"answer":1,"explain":"「朝遅れるのは困ります」 — 遅れるの được danh từ hóa làm chủ ngữ."},{"q":"Người viết thích làm gì?","options":["Tự hát","Nghe anh ấy hát","Chơi đàn","Xem hòa nhạc"],"answer":1,"explain":"「彼が歌うのを聞くのが好きです」 — hai lớp danh từ hóa bằng の."},{"q":"Trong câu 「自転車（じてんしゃ）に 乗（の）るのは 楽（たの）しいです」, chủ ngữ của câu là gì?","options":["Chiếc xe đạp","Việc đi xe đạp","Người viết","Con đường"],"answer":1,"explain":"「乗るの」 biến hành động thành cụm danh từ 'việc đi (xe đạp)' làm chủ ngữ."},{"q":"Câu cuối của đoạn gốc hỏi về việc gì?","options":["Việc anh ấy quên khóa xe","Việc anh ấy đã đến","Việc anh ấy sẽ đến muộn","Việc anh ấy đi xe đạp"],"answer":1,"explain":"「彼が来たのを知っていましたか」."},{"q":"Cụm 「忘（わす）れることが あります」 nghĩa là gì?","options":["Không bao giờ quên","Thỉnh thoảng có lúc quên","Đã quên hẳn","Sợ bị quên"],"answer":1,"explain":"Vる + ことがあります (ở đây đi cùng のを忘れる) = đôi khi xảy ra."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Danh từ hóa mệnh đề bằng 「の」","Thể điều kiện","Thể bị động","Kính ngữ"],"answer":0,"explain":"乗るの・かけるの・来たの・遅れるの・歌うの đều là danh từ hóa bằng の (Bài 38)."}]},"14":{"ext":"彼（かれ）は 転（ころ）んで、足（あし）を 怪我（けが）して しまいました。私（わたし）は それを 聞（き）いて、心配（しんぱい）しました。","qs":[{"q":"Anh ấy bị thương ở đâu?","options":["Tay","Chân","Đầu","Lưng"],"answer":1,"explain":"「足を怪我してしまいました」."},{"q":"Vì sao anh ấy bị thương?","options":["Bị ngã (転んで)","Bị xe đâm","Tập thể thao quá sức","Bị rơi đồ vào chân"],"answer":0,"explain":"「転んで、足を怪我して」 — thể て chỉ nguyên nhân/trình tự."},{"q":"Nghe chuyện đó, người viết cảm thấy thế nào?","options":["Vui mừng","Lo lắng","Tức giận","Không quan tâm"],"answer":1,"explain":"「それを聞いて、心配しました」."},{"q":"Cụm 「頭（あたま）が 痛（いた）くて」 — 「くて」 là thể て của tính từ nào?","options":["あたま","いたい (đau)","やすむ","ごご"],"answer":1,"explain":"Tính từ い 痛い → 痛くて nối nguyên nhân (Bài 39)."},{"q":"Câu nào đúng với đoạn gốc?","options":["Tàu đến muộn nên người viết không kịp giờ họp","Người viết ngủ quên nên trễ họp","Cuộc họp bị hủy vì tuyết","Người viết nghỉ chiều vì đau bụng"],"answer":0,"explain":"「電車が遅れて、会議に間に合いませんでした」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Lý do nối bằng thể て","Lý do bằng ので trang trọng","Điều kiện bằng ば","Mục đích bằng ために"],"answer":0,"explain":"遅れて・痛くて・聞いて・転んで đều là thể て chỉ nguyên nhân (Bài 39)."}]},"15":{"ext":"この 店（みせ）が 何時（なんじ）に 開（あ）くか、知（し）って いますか。少（すこ）し 味（あじ）を 見（み）て みます。","qs":[{"q":"Câu đầu phần mở rộng hỏi về thông tin gì?","options":["Quán đóng cửa lúc mấy giờ","Quán mở cửa lúc mấy giờ","Quán có đông không","Quán ở đâu"],"answer":1,"explain":"「何時に開くか、知っていますか」 — câu hỏi lồng ～か."},{"q":"Người viết định làm gì với món ăn?","options":["Nếm thử một chút","Mua về nhà","Chụp ảnh","Hỏi công thức"],"answer":0,"explain":"「少し味を見てみます」 — Vて みます = thử làm."},{"q":"Mẫu 「て みます」 diễn tả điều gì?","options":["Làm xong hoàn toàn","Thử làm để xem kết quả thế nào","Làm thay người khác","Làm một cách bắt buộc"],"answer":1,"explain":"食べてみます = ăn thử một lần xem sao (Bài 40)."},{"q":"Trước 「か」 của câu hỏi lồng, động từ phải ở dạng nào?","options":["Thể ます lịch sự","Thể thường (thể từ điển/thể た…)","Thể て","Thể mệnh lệnh"],"answer":1,"explain":"来るか・飲めばいいか — câu hỏi con dùng thể thường + か."},{"q":"Câu nào đúng với đoạn gốc?","options":["Người viết không biết anh ấy đến lúc mấy giờ","Người viết biết rõ giờ anh ấy đến","Người viết đã uống thuốc rồi","Người viết không định ăn món này"],"answer":0,"explain":"「彼が何時に来るか、知りません」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Câu hỏi lồng ～か và thử làm ～てみます","Kính ngữ trong nhà thuốc","Cách nấu món ăn","Hẹn giờ gặp nhau"],"answer":0,"explain":"Cả hai mẫu đều là trọng tâm Bài 40."}]},"16":{"ext":"私（わたし）は 妹（いもうと）に 宿題（しゅくだい）を 手伝（てつだ）って やりました。先生（せんせい）は 私（わたし）の 作文（さくぶん）を 直（なお）して くださいました。","qs":[{"q":"Người viết đã giúp em gái việc gì?","options":["Nấu ăn","Làm bài tập","Dọn phòng","Học từ vựng"],"answer":1,"explain":"「妹に宿題を手伝ってやりました」 — Vて やる cho người dưới."},{"q":"Thầy giáo đã làm gì cho người viết?","options":["Sửa bài văn cho","Cho mượn sách","Khen trước lớp","Cho nghỉ một buổi"],"answer":0,"explain":"「作文を直してくださいました」 — người trên làm cho mình dùng くださいました."},{"q":"Động từ nào là khiêm nhường ngữ dùng khi nhận ân huệ từ người trên?","options":["やる","くれる","いただく","あげる"],"answer":2,"explain":"部長に見ていただきました — いただく là dạng khiêm nhường của もらう."},{"q":"Khi dùng 「て やりました」, quan hệ giữa người cho và người nhận thường là gì?","options":["Người nhận là cấp trên","Người nhận là người dưới hoặc thân thiết ngang hàng (em, trẻ con, vật nuôi…)","Người nhận là khách lạ","Không liên quan đến quan hệ"],"answer":1,"explain":"子供に本を読んでやりました — cho người dưới (Bài 41)."},{"q":"Câu nào đúng với đoạn gốc?","options":["Ở ga, một người lạ đã xách hành lý giúp người viết","Trưởng phòng từ chối xem báo cáo","Người viết đọc sách cho trưởng phòng","Người lạ nhờ người viết chỉ đường"],"answer":0,"explain":"「知らない人が荷物を持ってくださいました」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Ân huệ phân tầng theo quan hệ trên – dưới","Kính ngữ ở nhà ga","Cách viết báo cáo","Quan hệ gia đình"],"answer":0,"explain":"いただく・くださる・やる được chọn tùy vị thế người cho/nhận."}]},"17":{"ext":"彼（かれ）は 資格（しかく）を 取（と）る ために、仕事（しごと）を 辞（や）めました。この スタジアムは ５万人（まんにん）は 入（はい）れます。","qs":[{"q":"Anh ấy nghỉ việc với mục đích gì?","options":["Để đi du lịch","Để lấy chứng chỉ/bằng cấp","Để về quê","Để mở cửa hàng"],"answer":1,"explain":"「資格を取るために、仕事を辞めました」 — ～ために chỉ mục đích."},{"q":"Sân vận động này chứa được ít nhất bao nhiêu người?","options":["Ít nhất 5 vạn người","Đúng 3 vạn người","Nhiều nhất 5 vạn người","Khoảng 500 người"],"answer":0,"explain":"Số lượng + は = ít nhất chừng đó (５万人は入れる)."},{"q":"Cụm 「３日（か）も かかりました」 nhấn mạnh điều gì?","options":["Thời gian ít hơn tưởng","Thời gian nhiều tới mức bất ngờ (tới 3 ngày)","Đúng 3 ngày như kế hoạch","Khoảng 3 giờ"],"answer":1,"explain":"Số lượng + も = nhiều đến mức (Bài 42)."},{"q":"Người viết trong đoạn gốc học mỗi ngày với mục đích gì?","options":["Để xin việc","Để đỗ kỳ thi","Để dạy lại em","Để đọc báo"],"answer":1,"explain":"「試験に合格するために、毎日勉強しています」."},{"q":"Mẫu 「までに」 trong 「終（お）わるまでに」 nghĩa là gì?","options":["Bắt đầu từ lúc","Cho đến trước thời điểm (hoàn thành)","Trong lúc đang làm","Sau khi xong rất lâu"],"answer":1,"explain":"レポートを終わるまでに３日 = tính đến lúc viết xong thì mất 3 ngày."},{"q":"Chủ đề của đoạn văn là gì?","options":["Mục đích ～ために và số lượng nhấn mạnh は/も","Điều kiện giả định","Thể bị động","Truyền văn"],"answer":0,"explain":"Cả đoạn xoay quanh hai điểm ngữ pháp này của Bài 42."}]},"18":{"ext":"彼女（かのじょ）は 嬉（うれ）しそうに 笑（わら）って いました。空（そら）が 暗（くら）く なって、雨（あめ）が 降（ふ）りそうです。","qs":[{"q":"Cô ấy cười với vẻ thế nào?","options":["Trông buồn ngủ","Trông vui vẻ","Trông ngại ngùng","Trông giận dữ"],"answer":1,"explain":"「嬉しそうに笑っていました」 — ～そうに + động từ."},{"q":"Bầu trời cho thấy dấu hiệu gì?","options":["Sắp nắng to","Sắp mưa","Sắp có tuyết","Sắp tối hẳn vì hết ngày"],"answer":1,"explain":"「空が暗くなって、雨が降りそうです」 — dự đoán từ vẻ bề ngoài."},{"q":"「眠（ねむ）そう」 được tạo từ tính từ 「眠（ねむ）い」 bằng cách nào?","options":["Giữ nguyên い rồi thêm そう","Bỏ い rồi thêm そう","Thêm そう vào thể た","Đổi thành danh từ rồi thêm そう"],"answer":1,"explain":"Tính từ い: bỏ い + そうです (眠い→眠そう)."},{"q":"Mẫu 「て きました」 trong đoạn gốc diễn tả điều gì?","options":["Mưa đã tạnh hẳn","Mưa bắt đầu rơi và hướng về thời điểm hiện tại","Ai đó đã đến","Người viết sắp ra ngoài"],"answer":1,"explain":"「雨が降ってきました」 = trời bắt đầu đổ mưa."},{"q":"Câu nào đúng với đoạn gốc?","options":["Chiếc bánh trông rất ngon","Cô ấy trông tỉnh táo","Mưa đã ngừng","Họ quyết định ở lại trong nhà"],"answer":0,"explain":"「このケーキはおいしそうです」."},{"q":"「そうです」 của Bài 43 khác 「そうです」 truyền văn ở điểm nào?","options":["Bài 43 là nghe nói lại từ người khác","Bài 43 là đánh giá từ vẻ bề ngoài nhìn thấy được","Bài 43 dùng cho quá khứ","Hai mẫu hoàn toàn giống nhau"],"answer":1,"explain":"様態の そうです (vẻ ngoài) vs 伝聞の そうです (nghe nói) — cặp dễ nhầm nhất N4."}]},"19":{"ext":"この 部屋（へや）は 静（しず）かすぎて、少（すこ）し 怖（こわ）いです。ドアを 開（あ）けやすく して ください。","qs":[{"q":"Căn phòng này có đặc điểm gì quá mức?","options":["Sáng quá","Yên tĩnh quá (đến mức hơi sợ)","Chật quá","Nóng quá"],"answer":1,"explain":"「静かすぎて、少し怖いです」 — ～すぎる chỉ quá mức."},{"q":"Lời yêu cầu về cánh cửa là gì?","options":["Hãy đóng cửa lại","Hãy làm cho cửa dễ mở","Hãy khóa cửa","Hãy sơn lại cửa"],"answer":1,"explain":"「ドアを開けやすくしてください」 — thân Vます + やすくする."},{"q":"Mẫu 「すぎます」 gắn vào phần nào của động từ?","options":["Thể từ điển","Thân Vます (bỏ ます)","Thể て","Thể な い"],"answer":1,"explain":"飲みすぎる・読みやすい đều gắn vào thân Vます (Bài 44)."},{"q":"Vì sao hôm qua người viết không ngủ được trong đoạn gốc?","options":["Vì phòng quá ồn","Vì uống cà phê quá nhiều","Vì đọc sách khuya","Vì đau đầu"],"answer":1,"explain":"「コーヒーを飲みすぎて、眠れませんでした」."},{"q":"Câu nào đúng với đoạn gốc?","options":["Quyển sách đầu dễ đọc, quyển thứ hai chữ nhỏ nên khó đọc","Cả hai quyển đều khó đọc","Quyển thứ hai dễ đọc hơn","Hai quyển sách có chữ to như nhau"],"answer":0,"explain":"「この本は読みやすいです。でも、その本は字が小さくて読みにくいです」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Quá mức ～すぎ và dễ/khó làm ～やすい/～にくい","Thể khả năng","Điều kiện","Kính ngữ"],"answer":0,"explain":"Cả đoạn gốc và phần mở rộng đều xoay quanh hai nhóm mẫu này."}]},"20":{"ext":"忙（いそが）しい 場合（ばあい）は、無理（むり）を しないで ください。彼（かれ）は 病気（びょうき）なのに、仕事（しごと）に 行（い）きました。","qs":[{"q":"Trong trường hợp đang bận, mọi người được khuyên điều gì?","options":["Làm thêm giờ","Đừng cố quá sức","Nhờ người khác làm hết","Về nhà ngay"],"answer":1,"explain":"「忙しい場合は、無理をしないでください」."},{"q":"Anh ấy đã đi làm mặc dù đang trong tình trạng nào?","options":["Đang bận việc nhà","Đang bị ốm","Đang chờ kết quả thi","Đang chuẩn bị nghỉ việc"],"answer":1,"explain":"「病気なのに、仕事に行きました」 — ～のに trái kỳ vọng."},{"q":"「のに」 khác 「けど」 ở sắc thái nào?","options":["のに nhẹ nhàng hơn, không cảm xúc","のに mang cảm xúc bất ngờ/bất mãn vì kết quả trái với kỳ vọng","のに chỉ dùng trong văn viết cổ","Hai mẫu không khác gì"],"answer":1,"explain":"忙しいのに手伝ってくれた = bận vậy mà vẫn giúp — ngoài dự đoán."},{"q":"「場合（ばあい）は」 thường xuất hiện trong loại văn bản nào?","options":["Thơ tình","Thông báo, hướng dẫn trang trọng","Hội thoại thân mật","Truyện cổ tích"],"answer":1,"explain":"事故があった場合は… là cách nói của thông báo/hướng dẫn (Bài 45)."},{"q":"Khi xảy ra tai nạn, việc đầu tiên phải làm theo đoạn gốc là gì?","options":["Chụp ảnh hiện trường","Liên lạc ngay với cảnh sát","Gọi cho gia đình","Rời khỏi hiện trường"],"answer":1,"explain":"「事故があった場合は、すぐ警察に連絡してください」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Nhượng bộ ～のに và tình huống ～場合は","Nguyên nhân bằng から","Mục đích bằng ために","Suy đoán bằng だろう"],"answer":0,"explain":"Hai mẫu được đối chiếu xuyên suốt đoạn."}]},"21":{"ext":"彼女（かのじょ）は 今（いま） 食事（しょくじ）を した ところです。彼（かれ）は 仕事（しごと）が 終（お）わるまで 帰（かえ）らない はずです。","qs":[{"q":"Cô ấy vừa mới làm xong việc gì?","options":["Vừa ra ngoài","Vừa ăn xong","Vừa ngủ dậy","Vừa về nhà"],"answer":1,"explain":"「食事をしたところです」 — Vた ところ = vừa mới làm xong."},{"q":"Anh ấy chắc chắn sẽ không về nhà cho đến khi nào?","options":["Đến 9 giờ tối","Đến khi công việc kết thúc","Đến khi trời tạnh mưa","Đến cuối tuần"],"answer":1,"explain":"「仕事が終わるまで帰らないはずです」 — ～はずです."},{"q":"「Vた ところ」 khác 「Vる ところ」 ở điểm nào?","options":["た ところ = vừa làm xong; る ところ = sắp làm","Hai mẫu giống hệt nhau","た ところ = sắp làm; る ところ = vừa xong","た ところ dùng cho tương lai xa"],"answer":0,"explain":"帰ったところ (vừa về) vs 出かけようとしているところ (đang sắp đi) — trục giai đoạn hành động của Bài 46."},{"q":"Mẫu 「ば かり」 trong 「寝（ね）て ばかり います」 chỉ điều gì?","options":["Vừa mới ngủ","Chỉ toàn ngủ (không làm gì khác)","Ngủ rất ngon","Sắp đi ngủ"],"answer":1,"explain":"Vて ばかりいる = chỉ toàn làm một việc (thường mang ý chê)."},{"q":"Từ 「たった今（いま）」 củng cố cho mẫu nào trong đoạn gốc?","options":["～はずです","Vた ところです (vừa mới)","～ばかりいます","～ようとしているところです"],"answer":1,"explain":"「たった今帰ったところです」 = vừa mới về ngay lúc này."},{"q":"Chủ đề của đoạn văn là gì?","options":["Giai đoạn của hành động (ところ) và dự đoán chắc chắn (はず)","Thể sai khiến","Kính ngữ","Câu điều kiện"],"answer":0,"explain":"ところ ba giai đoạn + はずです + ばかり là toàn bộ trọng tâm Bài 46."}]},"22":{"ext":"母（はは）に よると、祖父（そふ）は 元気（げんき）だそうです。あの 学生（がくせい）は 勉強（べんきょう）が 好（す）きなようです。","qs":[{"q":"Theo lời mẹ, ông nội/ngoại có tình trạng thế nào?","options":["Đang nằm viện","Vẫn khỏe","Sắp chuyển nhà","Đang đi du lịch"],"answer":1,"explain":"「母によると、祖父は元気だそうです」 — truyền văn kèm nguồn tin."},{"q":"Từ dấu hiệu bên ngoài, học sinh kia là người thế nào?","options":["Có vẻ thích học","Có vẻ ghét học","Có vẻ mệt mỏi","Có vẻ bận rộn"],"answer":0,"explain":"「勉強が好きなようです」 — ～ようです suy đoán từ quan sát."},{"q":"Nguồn tin của câu truyền văn đầu tiên trong đoạn gốc là gì?","options":["Tivi","Tin tức (ニュース)","Bạn bè","Giáo viên"],"answer":1,"explain":"「ニュースによると、明日は雨だそうです」."},{"q":"「ようです」 dựa trên căn cứ nào?","options":["Nghe người khác kể lại nguyên văn","Dấu hiệu tự quan sát và cảm nhận được","Quy định của trường","Ước mơ của người nói"],"answer":1,"explain":"人気があるようです = nhìn vào tình hình thì có vẻ được ưa chuộng."},{"q":"Câu nào đúng với đoạn gốc?","options":["Nghe nói anh ấy nghỉ học vì bị ốm","Anh ấy xin nghỉ để đi du lịch","Nhà hàng kia có vẻ vắng khách","Ngày mai chắc chắn nắng theo tin tức"],"answer":0,"explain":"「彼は病気で休んだそうです」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Truyền văn ～そうです và suy đoán ～ようです","Dự báo thời tiết chuyên nghiệp","Sức khỏe người cao tuổi","Nhà hàng nổi tiếng"],"answer":0,"explain":"Phân biệt hai nguồn thông tin: nghe nói lại vs tự suy đoán."}]},"23":{"ext":"母（はは）は 私（わたし）に 野菜（やさい）を 食（た）べさせました。子供（こども）に 自分（じぶん）の 部屋（へや）を 掃除（そうじ）させます。","qs":[{"q":"Mẹ đã bắt người viết ăn gì?","options":["Cá","Rau","Thịt","Trứng"],"answer":1,"explain":"「母は私に野菜を食べさせました」 — sai khiến 食べさせる."},{"q":"Người viết cho/bắt con mình làm việc gì?","options":["Nấu cơm","Tự dọn phòng của mình","Đi mua đồ","Học bài thêm"],"answer":1,"explain":"「子供に自分の部屋を掃除させます」."},{"q":"Thể sai khiến của 「読（よ）む」 là gì?","options":["読まれる","読ませる","読める","読まされる"],"answer":1,"explain":"Động từ nhóm 1: 読む → 読ませる (Bài 48)."},{"q":"Trong câu 「写真（しゃしん）を 撮（と）らせて ください」, người sẽ chụp ảnh là ai?","options":["Người nghe","Chính người nói (xin phép cho mình làm)","Một người thứ ba","Không ai cả"],"answer":1,"explain":"V使役て ください = xin hãy cho tôi làm — người nói xin phép thực hiện hành động."},{"q":"Trong đoạn gốc, giám đốc đã sai khiến ai viết báo cáo?","options":["Thư ký","Người viết","Trưởng phòng","Học sinh"],"answer":1,"explain":"「社長は私にレポートを書かせました」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Thể sai khiến và xin phép bằng thể sai khiến","Thể bị động","Kính ngữ đặc biệt","Ân huệ cho nhận"],"answer":0,"explain":"書かせる・読ませる・食べさせる・掃除させる・撮らせてください đều là sai khiến."}]},"24":{"ext":"お客様（きゃくさま）は ３時（じ）に お見（み）えに なります。社長（しゃちょう）は 会議室（かいぎしつ）に いらっしゃいます。","qs":[{"q":"Khách sẽ đến vào lúc mấy giờ?","options":["２時","３時","４時","３時半"],"answer":1,"explain":"「お客様は３時にお見えになります」 — お見えになる là kính ngữ của 来る."},{"q":"Giám đốc đang ở đâu?","options":["Ở nhà","Ở phòng họp","Ở đằng kia","Đã về"],"answer":1,"explain":"「社長は会議室にいらっしゃいます」."},{"q":"Động từ kính ngữ đặc biệt tương ứng với 「いる」 là gì?","options":["おる","いらっしゃる","なさる","ご覧になる"],"answer":1,"explain":"いらっしゃいます = kính ngữ đặc biệt của います (cũng của 行く・来る)."},{"q":"Cấu trúc 「お～に なります」 được tạo từ dạng nào của động từ?","options":["Thể từ điển","Thân Vます (bỏ ます) kẹp giữa お và になる","Thể て","Thể た"],"answer":1,"explain":"お読みになる・お帰りになる = お + thân Vます + になる (Bài 49)."},{"q":"Trong câu kính ngữ tôn kính, hành động là của ai?","options":["Của người nói","Của người trên / người được tôn kính","Của người dưới","Của một vật"],"answer":1,"explain":"尊敬語 nâng hành động của người trên lên: 社長がお帰りになる."},{"q":"Chủ đề của đoạn văn là gì?","options":["Tôn kính ngữ （尊敬語）","Khiêm nhường ngữ （謙譲語）","Thể thường thân mật","Thể sai khiến"],"answer":0,"explain":"Toàn đoạn dùng kính ngữ nâng người trên: お～になる, いらっしゃる, お見えになる."}]},"25":{"ext":"駅（えき）まで 私（わたし）が お送（おく）りいたします。部長（ぶちょう）の 奥様（おくさま）にも プレゼントを さしあげました。","qs":[{"q":"Người viết sẽ tiễn khách đến đâu?","options":["Đến cửa công ty","Đến tận nhà ga","Đến sân bay","Đến khách sạn"],"answer":1,"explain":"「駅まで私がお送りいたします」 — khiêm nhường ngữ お～いたします."},{"q":"Ngoài trưởng phòng, quà còn được tặng cho ai nữa?","options":["Thư ký","Vợ của trưởng phòng","Khách hàng mới","Thầy giáo"],"answer":1,"explain":"「部長の奥様にもプレゼントをさしあげました」."},{"q":"Khiêm nhường ngữ của 「あげる」 (tặng người trên) là gì?","options":["くださる","いただく","さしあげる","なさる"],"answer":2,"explain":"さしあげました = đã tặng (khiêm nhường) cho người trên."},{"q":"Động từ 「うかがいます」 tương ứng với động từ thường nào?","options":["食べる","行く／訪ねる (và 聞く)","見る","会う trong mọi trường hợp"],"answer":1,"explain":"うかがう là khiêm nhường của 行く・訪ねる・聞く (đến thăm/hỏi người trên)."},{"q":"Khi tự giới thiệu tên trước người trên, mẫu đúng là gì?","options":["～と おっしゃいます","～と 申（もう）します","～で いらっしゃいます","～と ご覧になります"],"answer":1,"explain":"「田中と申します」 — 申す là khiêm nhường của 言う khi nói về bản thân."},{"q":"Chủ đề của đoạn văn là gì?","options":["Khiêm nhường ngữ （謙譲語） — hạ mình xuống","Tôn kính ngữ — nâng người trên lên","Thể bị động","Thể sai khiến"],"answer":0,"explain":"ご案内いたします・うかがいます・申します・さしあげます・お送りいたします đều là 謙譲語."}]}},"N3":{"1":{"ext":"夕方（ゆうがた）の 散歩（さんぽ）では、子供（こども）たちと 遊（あそ）ぶことも ある。早起（はやお）きの おかげで、一日（いちにち）が 長（なが）く 感（かん）じられる。","qs":[{"q":"Trong lúc đi dạo buổi chiều, người viết còn làm gì nữa?","options":["Chạy bộ một mình","Chơi với trẻ con","Mua đồ ăn tối","Đọc sách"],"answer":1,"explain":"「夕方の散歩では、子供たちと遊ぶこともある」."},{"q":"Nhờ dậy sớm, một ngày được cảm nhận thế nào?","options":["Ngắn hơn","Dài hơn","Bận rộn hơn hẳn","Không thay đổi"],"answer":1,"explain":"「早起きのおかげで、一日が長く感じられる」."},{"q":"Cụm 「最中（さいちゅう）に」 nghĩa là gì?","options":["Trước khi","Sau khi","Đúng lúc đang (làm gì)","Thỉnh thoảng"],"answer":2,"explain":"「散歩の最中に」 = đúng lúc đang đi dạo."},{"q":"Mẫu 「うちに」 trong 「若いうちに」 chỉ thời gian nào?","options":["Khi còn (trẻ) — tranh thủ trong lúc tình trạng còn tiếp diễn","Sau khi già","Vào một ngày nào đó","Trước đây rất lâu"],"answer":0,"explain":"～うちに = trong lúc/tranh thủ khi trạng thái vẫn còn."},{"q":"Câu nào đúng với đoạn văn?","options":["Người viết dậy lúc 5 giờ để tích lũy kinh nghiệm khi còn trẻ","Người viết dậy sớm vì công việc đổi ca","Người viết không nói chuyện với hàng xóm","Thói quen dậy sớm mới bắt đầu hôm qua"],"answer":0,"explain":"「若いうちに、いろいろな経験をしておきたいからだ」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Thói quen dậy sớm và những thay đổi tích cực","Cách nói chuyện với hàng xóm","Kinh nghiệm làm việc","Lợi ích của việc đi dạo buổi tối"],"answer":0,"explain":"Toàn đoạn xoay quanh thói quen dậy 5 giờ và các hệ quả tốt của nó."}]},"2":{"ext":"都市（とし）では 若（わか）い 人（ひと）が 増（ふ）えつつあるが、地方（ちほう）では 減（へ）る 一方（いっぽう）だ。専門家（せんもんか）は 警告（けいこく）して いる。","qs":[{"q":"Ở thành phố, số người trẻ đang thay đổi thế nào?","options":["Đang tăng dần","Đang giảm dần","Không đổi","Tăng giảm thất thường"],"answer":0,"explain":"「都市では若い人が増えつつある」."},{"q":"Ở địa phương, dân số trẻ thế nào?","options":["Tăng nhanh","Cứ giảm một chiều","Ổn định","Tăng nhẹ"],"answer":1,"explain":"「地方では減る一方だ」 = cứ giảm mãi một chiều."},{"q":"Ai đang đưa ra cảnh báo về vấn đề này?","options":["Chính phủ","Chuyên gia","Báo chí","Người dân"],"answer":1,"explain":"「専門家は警告している」."},{"q":"Mẫu 「つつある」 chỉ điều gì?","options":["Một biến đổi đang tiến triển dần","Một hành động vừa kết thúc","Một dự định tương lai","Một thói quen quá khứ"],"answer":0,"explain":"減りつつある・増えつつある đều là biến đổi đang diễn ra."},{"q":"Câu nào đúng với đoạn văn?","options":["Chính phủ đã tìm ra giải pháp quyết định","Chính phủ vẫn chưa tìm ra phương pháp quyết định","Dân số Nhật đang tăng nhanh","Số người già giảm rõ nhất"],"answer":1,"explain":"「まだ決定的な方法は見つかっていない」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Dân số Nhật Bản đang dần giảm","Chính sách nhập cư","Kinh tế địa phương","Giáo dục trẻ em"],"answer":0,"explain":"Đoạn nói về xu hướng giảm dân số và phản ứng của chính phủ/chuyên gia."}]},"3":{"ext":"駅（えき）から 会社（かいしゃ）まで タクシーも なかった。携帯（けいたい）の 電池（でんち）も 切（き）れて しまい、連絡（れんらく）も できなかった。","qs":[{"q":"Từ ga đến công ty còn thiếu phương tiện nào nữa?","options":["Xe buýt","Taxi cũng không có","Xe đạp thuê","Xe của đồng nghiệp"],"answer":1,"explain":"「駅から会社までタクシーもなかった」."},{"q":"Điện thoại của người viết thế nào?","options":["Bị mất","Bị vỡ màn hình","Hết pin","Không có sóng vì tuyết"],"answer":2,"explain":"「携帯の電池も切れてしまい」 = pin điện thoại cũng hết."},{"q":"Vì điện thoại hết pin nên người viết không làm được gì?","options":["Không xem được bản đồ","Không liên lạc được","Không trả tiền được","Không chụp ảnh được"],"answer":1,"explain":"「連絡もできなかった」."},{"q":"Mẫu gần nghĩa nhất với 「ざるを 得（え）ない」 là gì?","options":["～ても いい","～しかない／～ほかない (buộc phải)","～たい","～ことが できる"],"answer":1,"explain":"Cả hai đều diễn tả 'không còn cách nào khác ngoài...'."},{"q":"Câu nào đúng với đoạn văn?","options":["Dù mất 2 tiếng đi bộ nhưng vẫn kịp giờ hẹn","Người viết trễ hẹn 2 tiếng","Người viết quay về nhà","Tuyết làm công ty đóng cửa"],"answer":0,"explain":"「２時間もかかったが、約束の時間にはどうにか間に合った」."},{"q":"Từ 「どうにか」 nghĩa là gì?","options":["Dễ dàng","Cuối cùng cũng xoay xở được","Hoàn toàn không","Đúng giờ hoàn toàn"],"answer":1,"explain":"「どうにか間に合った」 = mãi rồi cũng kịp, vừa sát nút."}]},"4":{"ext":"先輩（せんぱい）は「慣（な）れれば 慣（な）れる ほど 楽（らく）に なる」と 言（い）った。私（わたし）も 少（すこ）しずつ 自信（じしん）が ついて きた。","qs":[{"q":"Tiền bối nói điều gì sẽ xảy ra khi quen việc?","options":["Càng quen càng dễ dàng/nhẹ nhàng hơn","Càng quen càng khó","Quen rồi sẽ chán","Quen rồi lương tăng ngay"],"answer":0,"explain":"「慣れれば慣れるほど楽になる」 — ～ば～ほど."},{"q":"Người viết thay đổi thế nào theo thời gian?","options":["Ngày càng mệt","Dần dần có thêm tự tin","Muốn bỏ việc","Ngày càng bận"],"answer":1,"explain":"「少しずつ自信がついてきた」."},{"q":"「死（し）ぬ ほど 眠（ねむ）い」 dùng 「ほど」 theo cách nào?","options":["So sánh với người khác","Ví von mức độ cực đoan","Phủ định 'không đến mức'","Câu hỏi"],"answer":1,"explain":"Buồn ngủ 'đến chết được' là ví von cường điệu mức độ."},{"q":"Cấu trúc 「～ば～ほど」 nghĩa là gì?","options":["Nếu... thì...","Càng... càng...","Dù... cũng...","Sau khi... thì..."],"answer":1,"explain":"練習すればするほど = càng luyện càng (tự tin)."},{"q":"Nhận định 'công việc không khó đến mức tưởng' dùng mẫu nào?","options":["～ほど～ない","～ば～ほど","～ほど (ví von)","～ざるを得ない"],"answer":0,"explain":"「思ったほど難しくはなかった」."},{"q":"Chủ đề về ngữ pháp của đoạn là gì?","options":["Các cách dùng của 「ほど」","Thể sai khiến","Kính ngữ","Câu điều kiện たら"],"answer":0,"explain":"Ba câu trong đoạn dùng ほど theo ba cách: phủ định mức độ, ～ば～ほど, ví von."}]},"5":{"ext":"弟（おとうと）は ケーキを 見（み）ると、つい 買（か）いがちだ。あの 先生（せんせい）は 怒（おこ）りっぽくて、学生（がくせい）に 怖（こわ）がられて いる。","qs":[{"q":"Em trai có xu hướng làm gì khi thấy bánh kem?","options":["Hay mua (không kiềm được)","Chụp ảnh","Né tránh","Mua cho người khác"],"answer":0,"explain":"「つい買いがちだ」 — ～がち = hay có xu hướng làm."},{"q":"Vì sao học sinh sợ thầy giáo kia?","options":["Thầy rất nghiêm khắc về điểm số","Thầy trông hay giận (怒りっぽい)","Thầy nói rất to","Thầy hay cho bài tập"],"answer":1,"explain":"「怒りっぽくて、学生に怖がられている」 — ～っぽい = trông có vẻ."},{"q":"Mẫu 「ぎみ」 dùng để chỉ trạng thái nào?","options":["Hơi có vẻ (thường là trạng thái không tốt như mệt, cảm)","Rất mạnh mẽ","Đã hoàn toàn","Sắp xảy ra"],"answer":0,"explain":"疲れぎみ = hơi mệt — mức độ nhẹ, sắc thái tiêu cực."},{"q":"「大人（おとな）っぽい」 nghĩa là gì?","options":["Ghét người lớn","Trông như người lớn / ra dáng người lớn","Là người lớn thật","Muốn thành người lớn"],"answer":1,"explain":"～っぽい gắn sau danh từ: có vẻ giống, trông như."},{"q":"Câu nào đúng với đoạn văn?","options":["Anh trai hay quên lời hứa","Người viết rất khỏe gần đây","Đứa trẻ nói chuyện như trẻ con bình thường","Anh trai không bao giờ quên hẹn"],"answer":0,"explain":"「兄は約束を忘れがちだ」."},{"q":"Điểm chung của 忘れがち・疲れぎみ・大人っぽい là gì?","options":["Đều chỉ xu hướng / vẻ ngoài / tính chất dễ nhận thấy","Đều chỉ thời gian","Đều là mệnh lệnh","Đều là kính ngữ"],"answer":0,"explain":"Nhóm mẫu diễn tả khuynh hướng và ấn tượng bề ngoài."}]},"6":{"ext":"私（わたし）は 地球（ちきゅう）に 対（たい）して 優（やさ）しい 生活（せいかつ）を 心（こころ）がけて いる。学校（がっこう）では 環境（かんきょう）に ついての 授業（じゅぎょう）も 始（はじ）まった。","qs":[{"q":"Người viết cố gắng sống như thế nào?","options":["Tiết kiệm tối đa","Thân thiện với Trái Đất","Đơn giản hóa mọi thứ","Gần gũi với hàng xóm"],"answer":1,"explain":"「地球に対して優しい生活を心がけている」."},{"q":"Ở trường đã bắt đầu có thêm điều gì?","options":["Tiết học về môi trường","Câu lạc bộ tái chế","Kỳ thi về tự nhiên","Chuyến dã ngoại"],"answer":0,"explain":"「環境についての授業も始まった」 — ～についての + danh từ."},{"q":"Mẫu 「について」 dùng để làm gì?","options":["Giới thiệu chủ đề (về...)","Chỉ đối tượng của trách nhiệm","Chỉ quan điểm cá nhân","Chỉ nguyên nhân"],"answer":0,"explain":"「環境問題についてレポートを書いた」 = viết báo cáo về vấn đề môi trường."},{"q":"Trách nhiệm 「に対して」 hướng tới ai trong đoạn gốc?","options":["Chính phủ","Thế hệ sau","Trẻ em hiện tại","Thiên nhiên"],"answer":1,"explain":"「次の世代に対して責任がある」."},{"q":"Câu nào đúng với đoạn văn?","options":["Với trẻ em, thiên nhiên là người thầy tốt nhất","Báo cáo viết về kinh tế","Chúng ta không có trách nhiệm gì","Trẻ em không cần thiên nhiên"],"answer":0,"explain":"「子供にとって、自然は一番の先生だ」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Trách nhiệm của chúng ta với môi trường và thế hệ sau","Cách viết báo cáo","Giáo dục trẻ em ở trường","Du lịch thiên nhiên"],"answer":0,"explain":"Cả đoạn xoay quanh môi trường và trách nhiệm với thế hệ tiếp theo."}]},"7":{"ext":"来年（らいねん）の イベントに ついては、来月（らいげつ）また 話（はな）し合（あ）う ことに なった。私（わたし）は 安全対策（あんぜんたいさく）の 担当（たんとう）に なる ことに した。","qs":[{"q":"Về sự kiện năm sau, mọi người đã quyết định thế nào?","options":["Hủy bỏ hẳn","Tháng sau sẽ bàn lại","Giao cho công ty ngoài","Giảm một nửa quy mô"],"answer":1,"explain":"「来月また話し合うことになった」 — quyết định chung."},{"q":"Người viết tự quyết định đảm nhận việc gì?","options":["Phụ trách an toàn","Phụ trách kinh phí","Phụ trách quảng cáo","Phụ trách khách mời"],"answer":0,"explain":"「安全対策の担当になることにした」 — tự mình quyết định."},{"q":"Quyết định hủy sự kiện trong đoạn gốc thuộc loại nào?","options":["ことにした (tự quyết)","ことになった (quyết định từ bên ngoài/tập thể)","ことになっている (quy định)","ことにしたい (mong muốn)"],"answer":1,"explain":"Kết quả buổi họp: 「中止にすることになった」."},{"q":"Từ 「尊重（そんちょう）」 nghĩa là gì?","options":["Phản đối","Tôn trọng","Bỏ qua","Ghi chép"],"answer":1,"explain":"「みんなの意見を尊重した」 = tôn trọng ý kiến mọi người."},{"q":"Câu nào đúng với đoạn văn?","options":["Người viết vốn muốn tiếp tục nhưng tôn trọng ý kiến số đông","Người viết muốn hủy ngay từ đầu","Không ai có ý kiến gì","Sự kiện bị hủy vì hết tiền"],"answer":0,"explain":"「私は続けることにしたかったが、みんなの意見を尊重した」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Phân biệt quyết định cá nhân và quyết định tập thể/bên ngoài","Thể bị động","Câu điều kiện","Truyền văn"],"answer":0,"explain":"Trọng tâm: ～ことにした (tự quyết) vs ～ことになった (quyết từ bên ngoài)."}]},"8":{"ext":"会員（かいいん）に なると、年齢（ねんれい）に かかわらず 同（おな）じ 料金（りょうきん）だ。この 講座（こうざ）は 全国（ぜんこく）に わたって 放送（ほうそう）される。","qs":[{"q":"Khi trở thành hội viên, giá tiền sẽ thế nào?","options":["Giảm một nửa","Giống nhau bất kể tuổi tác","Tăng theo tuổi","Miễn phí hoàn toàn"],"answer":1,"explain":"「年齢にかかわらず同じ料金だ」."},{"q":"Khóa học này được phát sóng trong phạm vi nào?","options":["Chỉ ở Tokyo","Trên toàn quốc","Chỉ trên internet","Ở 3 thành phố lớn"],"answer":1,"explain":"「全国にわたって放送される」 — ～にわたって dùng cho phạm vi không gian."},{"q":"Việc đăng ký dịch vụ được thực hiện thông qua đâu?","options":["Bưu điện","Điện thoại","Internet","Tại quầy"],"answer":2,"explain":"「インターネットを通じて行う」 — ～を通じて."},{"q":"「にわたって」 có dùng cho phạm vi không gian được không?","options":["Không, chỉ cho thời gian","Được — dùng cho cả khoảng thời gian dài và phạm vi rộng","Chỉ cho số người","Chỉ cho giá tiền"],"answer":1,"explain":"３か月にわたって (thời gian) và 全国にわたって (không gian) đều đúng."},{"q":"Giá của dịch vụ trong đoạn gốc thay đổi theo yếu tố nào?","options":["Thu nhập","Địa chỉ","Độ tuổi","Số người đăng ký"],"answer":2,"explain":"「年齢に応じて料金が変わる」 — ～に応じて."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Các mẫu chỉ phạm vi, phương thức và sự tương ứng","Thể khả năng","Kính ngữ","So sánh"],"answer":0,"explain":"に応じて・を通じて・にわたって đều nói về cách thức/phạm vi tương ứng."}]},"9":{"ext":"彼（かれ）は 約束（やくそく）を 破（やぶ）った ばかりに、みんなの 信頼（しんらい）を 失（うしな）った。私（わたし）こそ 今年（ことし）の 担当（たんとう）に なりたい。","qs":[{"q":"Anh ta mất niềm tin của mọi người vì lý do gì?","options":["Vì đến muộn nhiều lần","Chỉ vì phá vỡ lời hứa","Vì nói dối về tiền","Vì bỏ việc giữa chừng"],"answer":1,"explain":"「約束を破ったばかりに、信頼を失った」 — ～ばかりに."},{"q":"Người viết nhấn mạnh mong muốn gì bằng 「こそ」?","options":["Chính mình muốn làm phụ trách năm nay","Muốn nghỉ việc năm nay","Muốn người khác làm thay","Muốn hủy bỏ kế hoạch"],"answer":0,"explain":"「私こそ今年の担当になりたい」 — ～こそ nhấn mạnh 'chính tôi'."},{"q":"Hậu quả trong câu dùng 「ばかりに」 thường có sắc thái gì?","options":["Tích cực, may mắn","Tiêu cực, đáng tiếc","Trung tính, khách quan","Hài hước"],"answer":1,"explain":"～ばかりに luôn dẫn đến kết quả xấu không mong muốn."},{"q":"「寝（ね）てばかりいる」 chỉ thói quen nào?","options":["Ngủ rất ngon","Chỉ toàn ngủ (không làm gì khác)","Ngủ sớm mỗi ngày","Mất ngủ"],"answer":1,"explain":"～てばかりいる = chỉ toàn làm một việc."},{"q":"Câu nào đúng với đoạn văn?","options":["Chỉ vì một câu nói đùa mà cô ấy giận","Anh ta ngủ vì quá mệt sau ca làm","Năm nay người viết không có mục tiêu","Câu nói đùa được mọi người khen"],"answer":0,"explain":"「冗談を言ったばかりに、彼女に怒られてしまった」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Nhóm mẫu ばかり・ばかりに・こそ","Nhóm mẫu nguyên nhân","Nhóm mẫu điều kiện","Nhóm mẫu suy đoán"],"answer":0,"explain":"Ba mẫu nhấn mạnh/giới hạn của Unit 07."}]},"10":{"ext":"たとえ 奨学金（しょうがくきん）が もらえなくても、アルバイトを しながら 留学（りゅうがく）する つもりだ。家族（かぞく）の 応援（おうえん）の おかげで、ここまで 来（こ）られた。","qs":[{"q":"Dù không nhận được học bổng, người viết định du học bằng cách nào?","options":["Vay tiền ngân hàng","Vừa làm thêm vừa học","Chờ năm sau thi lại","Nhờ họ hàng nuôi"],"answer":1,"explain":"「アルバイトをしながら留学するつもりだ」."},{"q":"Nhờ đâu người viết đi được đến ngày hôm nay?","options":["Nhờ tiền bối","Nhờ sự ủng hộ của gia đình","Nhờ học bổng","Nhờ tự lực hoàn toàn"],"answer":1,"explain":"「家族の応援のおかげで」 — ～おかげで chỉ nguyên nhân tích cực."},{"q":"「たとえ～ても」 diễn tả điều gì?","options":["Điều kiện chắc chắn xảy ra","Giả định nhượng bộ: dù (giả sử) ... cũng","Nguyên nhân quá khứ","Mục đích"],"answer":1,"explain":"たとえ親に反対されても = dù cho cha mẹ có phản đối đi nữa."},{"q":"「せいで」 khác 「おかげで」 ở điểm nào?","options":["せいで dùng cho kết quả tốt","せいで chỉ nguyên nhân của kết quả xấu","せいで chỉ dùng cho thời tiết","Hai mẫu giống hệt nhau"],"answer":1,"explain":"おかげで = nhờ (tốt); せいで = tại vì (xấu)."},{"q":"Câu nào đúng với đoạn văn?","options":["Bỏ cuộc vì một lần thất bại thì thật đáng tiếc","Người viết sắp bỏ du học","Tiền bối không giúp gì","Cha mẹ đã đồng ý cho du học"],"answer":0,"explain":"「一度の失敗のせいであきらめるのはもったいない」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Quyết tâm du học và cách nói nguyên nhân tốt/xấu","Cách xin học bổng","Việc làm thêm ở nước ngoài","Quan hệ với tiền bối"],"answer":0,"explain":"Đoạn kết hợp たとえ～ても, おかげで, せいで quanh chủ đề du học."}]},"11":{"ext":"彼（かれ）は 約束（やくそく）の 時間（じかん）に 遅（おく）れる わけが ない。もう 家（いえ）を 出（で）た はずだ。出発（しゅっぱつ）した ところを 見（み）たからだ。","qs":[{"q":"Người viết chắc chắn anh ấy sẽ không làm gì?","options":["Không đến nữa","Đến muộn giờ hẹn","Quên lời hứa","Đi nhầm đường"],"answer":1,"explain":"「約束の時間に遅れるわけがない」 = không đời nào đến muộn."},{"q":"Người viết suy đoán chắc chắn anh ấy đã làm gì?","options":["Đã lên tàu","Đã ra khỏi nhà","Đã đến nơi","Đã gọi điện"],"answer":1,"explain":"「もう家を出たはずだ」 — ～はずだ."},{"q":"Căn cứ cho suy đoán 「はずだ」 là gì?","options":["Anh ấy đã nhắn tin","Người viết đã nhìn thấy lúc anh ấy xuất phát","Anh ấy luôn đúng giờ","Đồng hồ chỉ giờ sớm"],"answer":1,"explain":"「出発したところを見たからだ」 = vì đã tận mắt thấy."},{"q":"「わけには いかない」 trong đoạn gốc cấm nghỉ việc vì lý do thuộc loại nào?","options":["Không có khả năng thể chất","Tình huống/nghĩa vụ không cho phép","Sếp trực tiếp cấm","Luật pháp cấm"],"answer":1,"explain":"Có trận đấu quan trọng nên về mặt tình huống không thể nghỉ."},{"q":"Câu nào đúng với đoạn văn?","options":["Từ việc đèn tắt, đoán là anh ấy đã ngủ","Anh ấy thường phá lời hứa","Tối nay người viết sẽ nghỉ việc","Đèn sáng nên anh ấy còn thức"],"answer":0,"explain":"「電気が消えているところを見ると、もう寝たはずだ」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Ba mẫu suy luận: わけがない・はずだ・わけにはいかない","Thể sai khiến bị động","Câu điều kiện","Truyền văn và tin đồn"],"answer":0,"explain":"Cả đoạn luyện phân biệt ba mẫu suy luận/hạn chế của Unit 09."}]},"12":{"ext":"子供（こども）の ころ、弟（おとうと）も 母（はは）に 泳（およ）ぎを 習（なら）わされた。許可（きょか）を 取（と）って からでないと、この 会議室（かいぎしつ）も 使（つか）えない。","qs":[{"q":"Hồi nhỏ, em trai bị mẹ bắt học gì?","options":["Học vẽ","Học bơi","Học đàn piano","Học tiếng Anh"],"answer":1,"explain":"「弟も母に泳ぎを習わされた」 — sai khiến bị động."},{"q":"Muốn dùng phòng họp này cũng phải thỏa điều kiện gì trước?","options":["Phải có 2 người trở lên","Phải xin phép trước","Phải là quản lý","Phải đặt trước 1 tuần"],"answer":1,"explain":"「許可を取ってからでないと使えない」 — ～てからでないと."},{"q":"Thể sai khiến bị động của 「習（なら）う」 là gì?","options":["習わせる","習わされる","習える","習われる"],"answer":1,"explain":"習う → sai khiến 習わせる → bị động rút gọn 習わされる."},{"q":"Trong mẫu 「ないことには」, mệnh đề chính phía sau thường ở dạng nào?","options":["Khẳng định mạnh","Phủ định (không thể...)","Mệnh lệnh","Câu hỏi"],"answer":1,"explain":"「許可がないことには使えない」 — không có X thì không thể."},{"q":"Câu nào đúng với đoạn văn?","options":["Quán nổi tiếng phải đặt bàn trước mới vào được","Phòng này ai dùng cũng được","Người viết tự nguyện học piano","Mẹ không bắt học gì cả"],"answer":0,"explain":"「予約をしてからでないと、人気店には入れない」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Điều kiện tiên quyết và sự bắt buộc","So sánh hơn nhất","Kinh nghiệm tuổi thơ vui vẻ","Cách đặt bàn nhà hàng"],"answer":0,"explain":"Ba mẫu đều nói về điều kiện bắt buộc phải có trước."}]},"13":{"ext":"時代（じだい）が 変（か）わるに つれて、働（はたら）き方（かた）も 多様（たよう）に なって きた。技術（ぎじゅつ）の 進歩（しんぽ）に したがって、古（ふる）い 仕事（しごと）は 消（き）えつつある。","qs":[{"q":"Theo thời đại thay đổi, điều gì trở nên đa dạng hơn?","options":["Cách làm việc","Sở thích","Ẩm thực","Phương tiện đi lại"],"answer":0,"explain":"「時代が変わるにつれて、働き方も多様になってきた」."},{"q":"Theo tiến bộ kỹ thuật, điều gì đang dần biến mất?","options":["Công việc mới","Công việc cũ","Máy móc cũ","Văn phòng truyền thống"],"answer":1,"explain":"「技術の進歩にしたがって、古い仕事は消えつつある」."},{"q":"Mẫu 「につれて」 yêu cầu mệnh đề phía sau có nội dung gì?","options":["Một biến đổi song hành theo","Một mệnh lệnh","Một nguyên nhân quá khứ","Một giả định"],"answer":0,"explain":"～につれて = cùng với A thay đổi, B cũng thay đổi theo."},{"q":"Mặt trái của sự tiện lợi được nhắc trong đoạn gốc là gì?","options":["Chi phí tăng cao","Những vấn đề mới nảy sinh","Con người ít vận động","Thời gian rảnh biến mất"],"answer":1,"explain":"「便利さの裏には新しい問題も生まれている」."},{"q":"Câu nào đúng với đoạn văn?","options":["Thể lực giảm dần theo tuổi là điều tự nhiên","Kinh tế phát triển làm lối sống không đổi","Tuổi tác không ảnh hưởng thể lực","Tiện lợi không có mặt trái"],"answer":0,"explain":"「年を取るにつれて、体力が落ちてくるのは自然だ」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Biến đổi song hành theo thời gian: につれて・にしたがって","Điều kiện giả định","Sự cho phép","Nguyên nhân tiêu cực"],"answer":0,"explain":"Hai mẫu gần nghĩa 'cùng với... thì...' là trọng tâm."}]},"14":{"ext":"この ケーキの 甘（あま）さは ちょうど いい。旅行（りょこう）の 楽（たの）しさは、行（い）って みないと 分（わ）からない。健康（けんこう）の 上（じょう）でも、早寝早起（はやねはやお）きは 大切（たいせつ）だ。","qs":[{"q":"Độ ngọt của chiếc bánh thế nào?","options":["Quá ngọt","Vừa phải, vừa miệng","Quá nhạt","Không có vị"],"answer":1,"explain":"「甘さはちょうどいい」 = độ ngọt vừa đúng."},{"q":"Khi nào mới hiểu được niềm vui của chuyến du lịch?","options":["Khi đọc sách hướng dẫn","Khi nghe bạn kể","Phải tự đi thử mới biết","Khi xem ảnh"],"answer":2,"explain":"「行ってみないと分からない」."},{"q":"Xét về mặt sức khỏe, điều gì được cho là quan trọng?","options":["Ăn nhiều rau","Ngủ sớm dậy sớm","Tập thể thao nặng","Uống nhiều nước"],"answer":1,"explain":"「健康の上でも、早寝早起きは大切だ」 — ～上でも."},{"q":"Đuôi 「さ」 trong 甘さ・楽しさ biến tính từ thành loại từ gì?","options":["Động từ","Danh từ chỉ mức độ/tính chất","Trạng từ","Phó từ nghi vấn"],"answer":1,"explain":"Tính từ + さ = danh từ hóa chỉ mức độ (長さ・優しさ・甘さ)."},{"q":"Chiều rộng của cây cầu trong đoạn gốc là bao nhiêu?","options":["50 mét","5 mét","10 mét","100 mét"],"answer":2,"explain":"「幅は１０メートルだ」 (chiều dài mới là 50 mét)."},{"q":"Cụm 「上（じょう）では」 nghĩa là gì?","options":["Ở phía trên","Xét về mặt/phương diện","Sau khi hoàn thành","Trong trường hợp"],"answer":1,"explain":"「安全の上では」 = xét về mặt an toàn."}]},"15":{"ext":"彼（かれ）は 謝（あやま）った。それでも、みんなは 許（ゆる）さなかった。つまり、信頼（しんらい）は もう 戻（もど）らないのである。","qs":[{"q":"Dù anh ấy đã xin lỗi, mọi người phản ứng thế nào?","options":["Tha thứ ngay","Vẫn không tha thứ","Yêu cầu họp lại","Chưa nghe lời xin lỗi"],"answer":1,"explain":"「謝った。それでも、みんなは許さなかった」."},{"q":"Kết luận được rút ra bằng 「つまり」 là gì?","options":["Cuộc họp sẽ họp lại tuần sau","Niềm tin không thể quay lại nữa","Anh ấy sẽ bị đuổi việc","Chuẩn bị đã đầy đủ"],"answer":1,"explain":"「つまり、信頼はもう戻らないのである」 = nói cách khác, niềm tin đã mất hẳn."},{"q":"Liên từ 「それでも」 chỉ quan hệ gì?","options":["Kết quả","Nhượng bộ (vậy mà / dù vậy)","Bổ sung","Thời gian"],"answer":1,"explain":"それでも = vậy mà, mặc dù thế."},{"q":"Liên từ 「そのため」 chỉ quan hệ gì?","options":["Nhượng bộ","Kết quả (vì vậy nên)","Đối lập lựa chọn","Ví dụ"],"answer":1,"explain":"「そのため、会議は延期された」 = vì vậy cuộc họp bị hoãn."},{"q":"「要（よう）するに」 được dùng khi nào?","options":["Khi mở đầu câu chuyện","Khi tóm tắt, kết luận lại vấn đề","Khi xin lỗi","Khi đưa ví dụ"],"answer":1,"explain":"要するに = tóm lại, nói gọn lại là."},{"q":"Theo đoạn gốc, nguyên nhân sâu xa khiến cuộc họp bị hoãn là gì?","options":["Thiếu kinh phí","Chuẩn bị không đủ","Lỗi kỹ thuật","Thiếu người tham dự"],"answer":1,"explain":"「要するに、準備不足が原因だった」."}]}},"N2":{"1":{"ext":"この サービスは 住民（じゅうみん）に 限（かぎ）って 無料（むりょう）である。国籍（こくせき）を 問（と）わず、住民（じゅうみん）なら 申（もう）し込（こ）める。","qs":[{"q":"Ai được sử dụng dịch vụ này miễn phí?","options":["Tất cả mọi người","Chỉ cư dân","Chỉ hội viên lâu năm","Chỉ người cao tuổi"],"answer":1,"explain":"「住民に限って無料である」 — ～に限って."},{"q":"Ai có thể đăng ký sử dụng dịch vụ?","options":["Chỉ công dân Nhật","Cư dân, bất kể quốc tịch","Chỉ người có thu nhập cao","Chỉ học sinh"],"answer":1,"explain":"「国籍を問わず、住民なら申し込める」."},{"q":"Mẫu đồng nghĩa gần nhất với 「を問（と）わず」 là gì?","options":["～にかかわらず (bất kể)","～を除いて (ngoại trừ)","～に限って (chỉ giới hạn)","～に基づいて (dựa trên)"],"answer":0,"explain":"年齢を問わず = 年齢にかかわらず = bất kể tuổi tác."},{"q":"Trường hợp ngoại lệ cần đồng ý của người bảo hộ là ai?","options":["Người nước ngoài","Người chưa thành niên","Hội viên mới","Người cao tuổi"],"answer":1,"explain":"「未成年者を除いては、保護者の同意が必要である」."},{"q":"Câu nào đúng với đoạn văn?","options":["Hội viên không phải trả thêm phí","Ai cũng phải trả phí thêm","Người chưa thành niên không cần đồng ý của ai","Chế độ này giới hạn theo tuổi"],"answer":0,"explain":"「会員に限っては、追加料金がかからない」."},{"q":"Chủ đề của đoạn văn là gì?","options":["Phạm vi và điều kiện áp dụng của một chế độ","Cách đăng ký hội viên","Lịch sử của chế độ phúc lợi","Phí dịch vụ công"],"answer":0,"explain":"Đoạn là thông báo về đối tượng áp dụng, ngoại lệ và giới hạn."}]},"2":{"ext":"この 計画（けいかく）は、資金不足（しきんぶそく）で 中止（ちゅうし）に なりかねない。彼（かれ）の 努力（どりょく）は、他人（たにん）には 理解（りかい）しがたいものが ある。","qs":[{"q":"Kế hoạch này có nguy cơ gì?","options":["Có thể bị hủy vì thiếu vốn","Chắc chắn thành công","Có thể bị hoãn 1 ngày","Có thể tăng ngân sách"],"answer":0,"explain":"「中止になりかねない」 — ～かねない = có khả năng xảy ra điều xấu."},{"q":"Nỗ lực của anh ấy được đánh giá thế nào với người ngoài?","options":["Ai cũng hiểu ngay","Có phần khó mà hiểu được","Không đáng kể","Đáng nghi ngờ"],"answer":1,"explain":"「他人には理解しがたい」 — ～がたい = khó mà."},{"q":"「かねる」 trong từ chối lịch sự (申し上げかねる) nghĩa là gì?","options":["Có thể làm dễ dàng","Không thể làm (vì khó xử/lịch sự)","Rất muốn làm","Đã làm xong"],"answer":1,"explain":"申し上げかねる = xin phép không thể trình bày — cách từ chối mềm."},{"q":"Mẫu 「がたい」 gắn vào phần nào của động từ?","options":["Thể từ điển","Thân Vます (bỏ ます)","Thể て","Thể た"],"answer":1,"explain":"言い表しがたい・理解しがたい đều gắn vào thân Vます."},{"q":"Câu nào đúng với đoạn văn?","options":["Nếu không có biện pháp, tai nạn có thể xảy ra","Tai nạn đã xảy ra rồi","Người phụ trách đã nói hết chi tiết","Nỗi vất vả của anh ấy rất nhỏ"],"answer":0,"explain":"「対策を講じなければ、事故が起きかねない」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Nhóm mẫu khả năng: かねない・かねる・がたい","Nhóm mẫu nhượng bộ","Nhóm mẫu thời gian","Nhóm mẫu ân huệ"],"answer":0,"explain":"Ba mẫu đều liên quan đến 'có thể/không thể' với sắc thái riêng."}]},"3":{"ext":"彼女（かのじょ）は 若（わか）い ばかりか、経験（けいけん）も 豊富（ほうふ）だ。手伝（てつだ）う どころか、彼（かれ）は 文句（もんく）ばかり 言（い）って いた。子供（こども）でさえ 知（し）って いる 常識（じょうしき）だ。","qs":[{"q":"Cô ấy ngoài trẻ ra còn có ưu điểm gì?","options":["Rất giàu","Kinh nghiệm cũng phong phú","Nói được 3 thứ tiếng","Có bằng cấp cao"],"answer":1,"explain":"「若いばかりか、経験も豊富だ」 — ～ばかりか."},{"q":"Anh ta, thay vì giúp đỡ, đã làm gì?","options":["Đứng nhìn","Chỉ toàn phàn nàn","Bỏ đi","Làm thay một mình"],"answer":1,"explain":"「手伝うどころか、文句ばかり言っていた」."},{"q":"Điều được nói là 'ngay cả trẻ em cũng biết' là gì?","options":["Một bài toán khó","Một thường thức hiển nhiên","Một bí mật","Một quy định mới"],"answer":1,"explain":"「子供でさえ知っている常識だ」 — ～でさえ."},{"q":"「どころか」 thường mang sắc thái gì?","options":["Đồng tình","Trái ngược hẳn với kỳ vọng (đừng nói là... đến mức ngược lại)","Nguyên nhân","Thời gian"],"answer":1,"explain":"手伝うどころか邪魔をした = giúp đâu mà giúp, còn gây cản trở."},{"q":"Câu nào đúng với đoạn gốc?","options":["Bài toán khó đến mức chuyên gia cũng không giải được, anh ấy vẫn một mình suy nghĩ tiếp","Anh ấy giúp đỡ rất nhiều","Anh ấy không bận cũng không mệt","Bài toán ai cũng giải được"],"answer":0,"explain":"「専門家でさえ解けない問題を、彼は一人で考え続けた」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Nhấn mạnh mức độ vượt ngoài dự đoán","Chỉ thời gian đồng thời","Điều kiện tiên quyết","Nguyên nhân khách quan"],"answer":0,"explain":"ばかりか・どころか・でさえ đều nhấn mạnh mức độ bất ngờ."}]},"4":{"ext":"新（あたら）しい 規則（きそく）は、法律（ほうりつ）に 基（もと）づいて 作（つく）られた。留学（りゅうがく）するに あたって、彼（かれ）は 貯金（ちょきん）を 始（はじ）めた。先生（せんせい）の 指導（しどう）のもとで、研究（けんきゅう）は 進（すす）んだ。","qs":[{"q":"Quy tắc mới được lập dựa trên căn cứ gì?","options":["Ý kiến nhân viên","Luật pháp","Quy tắc cũ","Báo cáo tài chính"],"answer":1,"explain":"「法律に基づいて作られた」 — ～に基づいて."},{"q":"Nhân dịp chuẩn bị du học, anh ấy bắt đầu làm gì?","options":["Học nấu ăn","Tiết kiệm tiền","Bán xe","Tập thể thao"],"answer":1,"explain":"「留学するにあたって、貯金を始めた」 — ～にあたって."},{"q":"Nghiên cứu tiến triển dưới sự hướng dẫn của ai?","options":["Giám đốc","Chuyên gia nước ngoài","Thầy giáo","Đồng nghiệp"],"answer":2,"explain":"「先生の指導のもとで」 — ～のもとで."},{"q":"「のもとで」 nghĩa là gì?","options":["Dựa trên văn bản","Dưới sự (hướng dẫn/bảo trợ/điều kiện) của...","Nhân dịp bắt đầu","Bất kể điều gì"],"answer":1,"explain":"専門家の指導のもとで = dưới sự hướng dẫn của chuyên gia."},{"q":"Câu nào đúng với đoạn gốc?","options":["Phương án cải thiện được lập dựa trên kết quả điều tra","Buổi huấn luyện không có người hướng dẫn","Dự án mới bắt đầu mà không phân tích gì","Thị trường không được phân tích"],"answer":0,"explain":"「調査結果に基づいて、改善策が立てられた」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Căn cứ, dịp quan trọng và sự bảo trợ","Nhượng bộ văn viết","Cảm xúc mạnh","Trình tự thời gian"],"answer":0,"explain":"に基づいて・にあたって・のもとで là ba mẫu trang trọng chỉ căn cứ/bối cảnh."}]},"5":{"ext":"２人（ふたり）あたり １台（だい）の 車（くるま）が 割（わ）り当（あ）てられた。彼（かれ）とは 卒業（そつぎょう）以来（いらい）、１０年（ねん）ぶりに 会（あ）った。会場（かいじょう）から 出口（でぐち）に かけて、人（ひと）が 並（なら）んで いた。","qs":[{"q":"Xe được phân bổ theo tỉ lệ nào?","options":["Mỗi người 1 chiếc","Mỗi 2 người 1 chiếc","Mỗi 5 người 1 chiếc","Mỗi nhóm 10 người 1 chiếc"],"answer":1,"explain":"「２人あたり１台」 — ～あたり = tính trên mỗi đơn vị."},{"q":"Cuộc gặp lại này diễn ra sau bao lâu kể từ khi tốt nghiệp?","options":["Sau 5 năm","Sau 10 năm","Sau 2 năm","Lần đầu sau 1 năm"],"answer":1,"explain":"「１０年ぶりに会った」 — ～ぶりに = sau khoảng thời gian."},{"q":"Mọi người xếp hàng trong phạm vi nào?","options":["Từ ga đến bờ biển","Từ hội trường đến lối ra","Từ cổng vào đến sân khấu","Quanh hội trường"],"answer":1,"explain":"「会場から出口にかけて」 — ～にかけて chỉ phạm vi."},{"q":"「ごとに」 trong đoạn gốc chỉ điều gì?","options":["Khoảng thời gian đã trôi qua","Tần suất đều đặn (mỗi...)","Phạm vi không gian","Giá tiền"],"answer":1,"explain":"「１０分ごとに１本来る」 = cứ 10 phút có 1 chuyến."},{"q":"Giá sử dụng cơ sở trong đoạn gốc tính thế nào?","options":["500 yên mỗi lần","500 yên mỗi giờ","500 yên mỗi người","500 yên mỗi ngày"],"answer":1,"explain":"「１時間あたり５００円で利用できる」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Đơn vị phân bổ và phạm vi: あたり・ごとに・ぶりに・にかけて","Nhượng bộ","Suy đoán","Ân huệ"],"answer":0,"explain":"Bốn mẫu đều liên quan đến cách chia/phạm vi của thời gian, không gian, số lượng."}]},"6":{"ext":"彼（かれ）は 忙（いそが）しいと 言（い）い つつも、引（ひ）き受（う）けて くれた。準備（じゅんぱい）した ものの、当日（とうじつ）は 雨（あめ）で 中止（ちゅうし）に なった。ベテランとはいえ、彼（かれ）も 緊張（きんちょう）したそうだ。","qs":[{"q":"Anh ấy đã nhận việc trong tình trạng nào?","options":["Dù nói là bận, vẫn nhận giúp","Nhận ngay không do dự","Từ chối thẳng","Nhận vì được trả thêm tiền"],"answer":0,"explain":"「忙しいと言いつつも、引き受けてくれた」 — ～つつも nhượng bộ."},{"q":"Sự kiện bị hủy vì lý do gì dù đã chuẩn bị?","options":["Thiếu người","Mưa vào đúng ngày diễn ra","Hết kinh phí","Trùng lịch khác"],"answer":1,"explain":"「準備したものの、当日は雨で中止になった」 — ～ものの."},{"q":"Ngay cả người kỳ cựu cũng có cảm xúc gì?","options":["Buồn ngủ","Căng thẳng","Tức giận","Chán nản"],"answer":1,"explain":"「ベテランとはいえ、彼も緊張したそうだ」."},{"q":"Mệnh đề sau 「ものの」 thường có nội dung gì?","options":["Kết quả đúng như kỳ vọng","Kết quả trái với kỳ vọng (nhượng bộ)","Nguyên nhân chi tiết","Mệnh lệnh"],"answer":1,"explain":"努力したものの結果が出なかった = đã nỗ lực vậy mà kết quả không như ý."},{"q":"Câu nào đúng với đoạn gốc?","options":["Biết thuốc lá hại sức khỏe mà anh ấy không bỏ được","Anh ấy bỏ thuốc thành công","Người kỳ cựu không bao giờ mắc lỗi vì quá giỏi","Nỗ lực cho kết quả tốt ngoài mong đợi"],"answer":0,"explain":"「体に悪いと知りつつ、タバコをやめられない」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Nhượng bộ văn viết: ものの・つつ・とはいえ","Nguyên nhân tích cực","Điều kiện cần thiết","Thời gian đồng thời"],"answer":0,"explain":"Cả ba mẫu đều diễn tả 'mặc dù... nhưng' ở sắc thái trang trọng."}]},"7":{"ext":"結婚（けっこん）を きっかけに、彼女（かのじょ）は 仕事（しごと）を 辞（や）めた。定年（ていねん）を 境（さかい）に、彼（かれ）の 生活（せいかつ）は 一変（いっぺん）した。地球温暖化（ちきゅうおんだんか）を めぐる 議論（ぎろん）は 続（つづ）いて いる。","qs":[{"q":"Cô ấy nghỉ việc nhân cơ duyên nào?","options":["Chuyển nhà","Kết hôn","Sinh con","Du học"],"answer":1,"explain":"「結婚をきっかけに、仕事を辞めた」 — ～をきっかけに."},{"q":"Cuộc sống của anh ấy thay đổi hẳn kể từ mốc nào?","options":["Khi đổi việc","Khi nghỉ hưu (đến tuổi định niên)","Khi chuyển thành phố","Khi kết hôn"],"answer":1,"explain":"「定年を境に、生活は一変した」 — ～を境に."},{"q":"Cuộc tranh luận vẫn đang tiếp diễn xoay quanh vấn đề gì?","options":["Năng lượng tái tạo","Nóng lên toàn cầu","Thương mại quốc tế","Giáo dục"],"answer":1,"explain":"「地球温暖化をめぐる議論」 — ～をめぐって/～をめぐる."},{"q":"「を境（さかい）に」 chỉ điều gì?","options":["Một cơ duyên ngẫu nhiên","Một mốc thời gian phân chia rõ trước và sau","Một nguyên nhân tiêu cực","Một điều kiện bắt buộc"],"answer":1,"explain":"その日を境に連絡が取れなくなった = lấy ngày đó làm ranh giới, mọi thứ đổi khác."},{"q":"Câu nào đúng với đoạn gốc?","options":["Du học là cơ duyên khiến cuộc đời anh ấy thay đổi lớn","Hội nghị tránh nói về môi trường","Hai người liên lạc nhiều hơn sau ngày đó","Cuộc đời anh ấy đổi vì đổi việc"],"answer":0,"explain":"「留学をきっかけに、彼の人生は大きく変わった」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Cơ duyên và mốc thay đổi: をめぐって・をきっかけに・を境に","Khả năng và suy đoán","Nhượng bộ","Số lượng nhấn mạnh"],"answer":0,"explain":"Ba mẫu đều gắn một sự kiện với sự thay đổi/tranh luận xung quanh nó."}]},"8":{"ext":"物価（ぶっか）は 上（あ）がる 一方（いっぽう）で、給料（きゅうりょう）は 変（か）わらない。何度（なんど）も 考（かんが）えた 末（すえ）に、彼（かれ）は 留学（りゅうがく）を 決（き）めた。昼食（ちゅうしょく）ぬきで 会議（かいぎ）は ３時間（じかん） 続（つづ）いた。","qs":[{"q":"Giá cả và tiền lương thay đổi thế nào?","options":["Cả hai cùng tăng","Giá cứ tăng một chiều, lương không đổi","Giá giảm, lương tăng","Cả hai cùng giảm"],"answer":1,"explain":"「物価は上がる一方で、給料は変わらない」 — ～一方だ."},{"q":"Anh ấy quyết định đi du học sau quá trình nào?","options":["Sau khi hỏi ý kiến một lần","Sau nhiều lần suy nghĩ","Sau khi trúng thưởng","Sau khi bị ép buộc"],"answer":1,"explain":"「何度も考えた末に」 — ～た末に."},{"q":"Cuộc họp kéo dài 3 tiếng trong tình trạng nào?","options":["Không nghỉ giữa giờ uống nước","Không có bữa trưa","Không có tài liệu","Không có trưởng phòng"],"answer":1,"explain":"「昼食ぬきで会議は３時間続いた」 — ～ぬきで = mà không có."},{"q":"「一方（いっぽう）だ」 chỉ xu hướng gì?","options":["Lên xuống thất thường","Một chiều — cứ tiếp tục tăng hoặc giảm mãi","Dừng lại hẳn","Thay đổi đột ngột một lần"],"answer":1,"explain":"増える一方だ = cứ tăng mãi không có dấu hiệu ngược lại."},{"q":"Câu nào đúng với đoạn gốc?","options":["Anh ấy vô địch sau nhiều lần luyện tập","Anh ấy vô địch nhờ may mắn","Số công ty phá sản đang giảm","Anh ấy đói vì ăn sáng quá ít"],"answer":0,"explain":"「何度も練習した末に、彼はついに優勝した」."},{"q":"「あげく」 khác 「末（すえ）に」 ở sắc thái nào?","options":["あげく thường dẫn đến kết quả tiêu cực/đáng tiếc; 末に trung tính hoặc tích cực sau nỗ lực dài","末に luôn tiêu cực","あげく luôn tích cực","Hai mẫu hoàn toàn giống nhau"],"answer":0,"explain":"Đây là cặp mẫu 'cuối cùng' kinh điển cần phân biệt ở N2."}]},"9":{"ext":"会議（かいぎ）に 先立（さきだ）って、資料（しりょう）が 配（くば）られた。長（なが）い 沈黙（ちんもく）を 経（へ）て、彼（かれ）は ようやく 口（くち）を 開（ひら）いた。第一部（だいいちぶ）に 続（つづ）いて、質疑応答（しつぎおうとう）が 行（おこな）われた。","qs":[{"q":"Trước khi cuộc họp bắt đầu, tài liệu được làm gì?","options":["Được thu lại","Được phát trước cho mọi người","Được đăng lên mạng","Được dịch sang tiếng Anh"],"answer":1,"explain":"「会議に先立って、資料が配られた」 — ～に先立って."},{"q":"Sau khoảng im lặng dài, anh ấy cuối cùng đã làm gì?","options":["Rời khỏi phòng","Lên tiếng (mở miệng nói)","Xin lỗi","Cười lớn"],"answer":1,"explain":"「長い沈黙を経て、彼はようやく口を開いた」 — ～を経て."},{"q":"Tiếp nối sau phần một là hoạt động gì?","options":["Giải lao","Phần hỏi – đáp","Phần hai thuyết trình","Bế mạc"],"answer":1,"explain":"「第一部に続いて、質疑応答が行われた」 — ～に続いて."},{"q":"「を経（へ）て」 chỉ điều gì?","options":["Trải qua một quá trình/thời gian rồi mới đến kết quả","Làm trước một sự kiện","Tiếp nối ngay lập tức","Bỏ qua một giai đoạn"],"answer":0,"explain":"長い討論を経て = trải qua cuộc thảo luận dài rồi mới phê duyệt."},{"q":"Câu nào đúng với đoạn gốc?","options":["Khảo sát ý kiến được thực hiện trước khi công bố sản phẩm mới","Kế hoạch được duyệt ngay không cần thảo luận","Phần hai bắt đầu trước phần một","Sản phẩm công bố trước khảo sát"],"answer":0,"explain":"「発表に先立って、アンケート調査が行われた」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Trình tự trang trọng: trước – trải qua – tiếp nối","Nhượng bộ văn viết","Cảm xúc mạnh","Phạm vi áp dụng"],"answer":0,"explain":"に先立って・を経て・に続いて đều sắp xếp thứ tự sự kiện một cách trang trọng."}]},"10":{"ext":"彼（かれ）は 眠（ねむ）げな 目（め）で パソコンを 見（み）て いた。新入社員（しんにゅうしゃいん）の 質問（しつもん）は、子供（こども）じみて いて 場（ば）が 白（しら）けた。彼女（かのじょ）は 細（こま）かい ミスを 気（き）にする きらいが ある。","qs":[{"q":"Anh ấy nhìn máy tính với đôi mắt thế nào?","options":["Trông vui vẻ","Trông buồn ngủ","Trông giận dữ","Trông ngạc nhiên"],"answer":1,"explain":"「眠げな目で」 — ～げ = vẻ bề ngoài."},{"q":"Câu hỏi của nhân viên mới bị đánh giá thế nào?","options":["Rất sắc sảo","Trẻ con/nghiệp dư, khiến không khí chùng xuống","Quá khó","Rất lịch sự"],"answer":1,"explain":"「子供じみていて場が白けた」 — ～じみた = có vẻ giống (tiêu cực)."},{"q":"Theo phần mở rộng, cô ấy hay bận tâm đến điều gì?","options":["Hay bận tâm đến cả những lỗi nhỏ","Hay khoe khoang","Hay đến muộn","Hay quên đồ"],"answer":0,"explain":"「細かいミスを気にするきらいがある」 — ～きらいがある."},{"q":"「げ」 trong 眠げ・疲れげ dùng để chỉ điều gì?","options":["Nguyên nhân khách quan","Vẻ bề ngoài cho thấy trạng thái/cảm xúc","Hành động đã hoàn thành","Sự cho phép"],"answer":1,"explain":"～げ diễn tả ấn tượng nhìn thấy được từ bên ngoài."},{"q":"「じみた」 thường mang sắc thái nào?","options":["Tích cực, khen ngợi","Tiêu cực — trông giống nhưng chưa đạt, không tự nhiên","Trung tính hoàn toàn","Trang trọng khen cấp trên"],"answer":1,"explain":"素人じみた・子供じみた đều là đánh giá chê bai nhẹ."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Đánh giá vẻ ngoài, tính chất và khuynh hướng","Chỉ thời gian và địa điểm","Ra mệnh lệnh lịch sự","Chỉ nguyên nhân khách quan"],"answer":0,"explain":"げ・じみた・きらいがある đều là mẫu đánh giá tính chất của Unit 10."}]},"11":{"ext":"健康（けんこう）に 関（かん）する 相談（そうだん）が 増（ふ）えて いる。予想（よそう）に 反（はん）して、彼（かれ）は 冷静（れいせい）だった。兄（あに）は 仕事熱心（しごとねっしん）だ。それに ひきかえ、弟（おとうと）は のんびりして いる。","qs":[{"q":"Loại tư vấn nào đang tăng lên?","options":["Tư vấn về thuế","Tư vấn liên quan đến sức khỏe","Tư vấn du học","Tư vấn việc làm"],"answer":1,"explain":"「健康に関する相談が増えている」 — ～に関する."},{"q":"Trái với dự đoán, anh ấy tỏ ra thế nào?","options":["Hoảng loạn","Bình tĩnh","Tức giận","Im lặng bỏ đi"],"answer":1,"explain":"「予想に反して、彼は冷静だった」 — ～に反して."},{"q":"Em trai khác anh trai ở điểm nào trong phần mở rộng?","options":["Em chăm học hơn","Em thong thả, trong khi anh nhiệt huyết với công việc","Em làm việc nhiều hơn","Cả hai giống hệt nhau"],"answer":1,"explain":"「それにひきかえ、弟はのんびりしている」 — đối lập hai đối tượng."},{"q":"「ひきかえ」 dùng để làm gì?","options":["Nêu ví dụ","Đối lập hai đối tượng/sự việc với nhau","Chỉ nguyên nhân","Kết luận bài văn"],"answer":1,"explain":"兄は勉強家だ。それにひきかえ弟は… = ngược lại hẳn."},{"q":"Câu nào đúng với đoạn gốc?","options":["Luật liên quan đến môi trường đã được sửa đổi","Kết quả đúng như dự đoán","Em trai chăm học hơn anh","Không có luật nào thay đổi"],"answer":0,"explain":"「環境に関する法律が改正された」."},{"q":"Chức năng chính của 「に関する」 là gì?","options":["Chỉ sự trái ngược","Nêu chủ đề liên quan (liên quan đến...)","Chỉ mốc thời gian","Chỉ cơ duyên"],"answer":1,"explain":"～に関する + danh từ = (cái gì) liên quan đến..."}]},"12":{"ext":"子供（こども）の 成長（せいちょう）を 見（み）ると、嬉（うれ）しくて ならない。この 景色（けしき）は 美（うつく）しくて たまらない。彼（かれ）の 努力（どりょく）は 今（いま）も なお 続（つづ）いて、やむ ことは ない。","qs":[{"q":"Nhìn con cái trưởng thành, người viết cảm thấy thế nào?","options":["Lo lắng vô cùng","Vui mừng không kìm nén được","Không cảm xúc","Hơi buồn"],"answer":1,"explain":"「嬉しくてならない」 — ～てならない."},{"q":"Phong cảnh được cảm nhận thế nào?","options":["Đẹp đến mức không chịu nổi","Bình thường","Hoang vắng đáng sợ","Đẹp thoáng qua"],"answer":0,"explain":"「美しくてたまらない」 — ～てたまらない."},{"q":"Nỗ lực của anh ấy được mô tả thế nào?","options":["Đã dừng lại","Vẫn tiếp tục không ngừng cho đến nay","Mới bắt đầu lại","Chỉ còn trong lời kể"],"answer":1,"explain":"「今もなお続いて、やむことはない」 — ～やまない."},{"q":"Chủ thể cảm xúc của 「てならない」 thường là ai?","options":["Người thứ ba xa lạ","Chính người nói (ngôi thứ nhất)","Một vật vô tri","Người nghe"],"answer":1,"explain":"Cảm xúc tự nhiên của bản thân: 懐かしくてならない = tôi nhớ nhung vô cùng."},{"q":"Câu nào đúng với đoạn gốc?","options":["Nghe giọng mẹ ở quê thì nhớ nhung vô cùng","Nụ cười em bé không gây ấn tượng","Lời cầu nguyện hòa bình đã kết thúc","Người viết ghét quê hương"],"answer":0,"explain":"「母の声を聞くと、懐かしくてならない」."},{"q":"Chủ đề ngữ pháp của đoạn là gì?","options":["Cảm xúc mạnh không kìm nén được / không ngừng","Khả năng khách quan","Sự cho phép","Sự bắt buộc từ bên ngoài"],"answer":0,"explain":"てならない・てたまらない・やまない đều là nhóm cảm xúc cao trào."}]},"13":{"ext":"彼（かれ）は あくまでも 自分（じぶん）の 意見（いけん）を 通（とお）した。この 仕事（しごと）は せいぜい ２日（か）で 終（お）わる。まさか 試験（しけん）に 落（お）ちるとは 思（おも）わなかった。せっかくの 休（やす）みだから、家族（かぞく）と ゆっくり 過（す）ごしたい。","qs":[{"q":"Anh ấy đã kiên quyết làm gì đến cùng?","options":["Bỏ cuộc giữa chừng","Giữ vững và thông qua ý kiến của mình","Nghe theo số đông","Xin lỗi mọi người"],"answer":1,"explain":"「あくまでも自分の意見を通した」 — ～あくまでも."},{"q":"Công việc ở phần mở rộng được ước lượng tối đa bao lâu?","options":["Đúng 1 tuần","Tối đa 2 ngày","Ít nhất 2 ngày","Không xác định"],"answer":1,"explain":"「せいぜい２日で終わる」 — ～せいぜい = tối đa là."},{"q":"Điều gì là hoàn toàn không ngờ tới?","options":["Việc được tăng lương","Việc trượt kỳ thi","Việc đổi chỗ làm","Việc gặp lại bạn cũ"],"answer":1,"explain":"「まさか試験に落ちるとは思わなかった」 — ～まさか."},{"q":"Vì là kỳ nghỉ cất công mới có, người viết muốn làm gì?","options":["Làm thêm kiếm tiền","Thong thả ở bên gia đình","Đi du lịch xa một mình","Học thi chứng chỉ"],"answer":1,"explain":"「せっかくの休みだから、家族とゆっくり過ごしたい」 — ～せっかく."},{"q":"「せいぜい」 nghĩa là gì?","options":["Ít nhất","Tối đa là (ước lượng khiêm tốn)","Đúng bằng","Khoảng chừng không rõ"],"answer":1,"explain":"せいぜい３日 = giỏi lắm thì 3 ngày là cùng."},{"q":"「あくまでも」 nhấn mạnh điều gì?","options":["Sự tình cờ","Sự kiên quyết đến cùng / tuyệt đối","Sự ước lượng","Sự bất ngờ"],"answer":1,"explain":"あくまでも最後まであきらめない = kiên quyết đến cùng, không bỏ cuộc."}]}}};

const GRAMMAR_LECTURES = {"N5": {"1": {"title": "Bài 1 — Minna no Nihongo", "intro": "Bài đầu tiên dạy cách giới thiệu bản thân: nói mình là ai, làm nghề gì, đến từ đâu — và cách phủ định, đặt câu hỏi lịch sự trong tiếng Nhật.", "points": [{"pattern": "N1 は N2 です", "meaning": "N1 là N2", "form": "Danh từ 1 + は (đọc là “wa”) + Danh từ 2 + です", "explain": "Đây là mẫu câu nền tảng nhất của tiếng Nhật. Trợ từ は đánh dấu chủ đề của câu — phần đứng trước は là điều ta muốn nói tới, phần sau は là thông tin về chủ đề đó. です là dạng lịch sự của “là”, đứng cuối câu khẳng định ở thì hiện tại.", "examples": [{"jp": "わたしは ベトナム人（じん）です。", "vi": "Tôi là người Việt Nam."}, {"jp": "田中（たなか）さんは 先生（せんせい）です。", "vi": "Anh Tanaka là giáo viên."}], "note": "は viết là は nhưng đọc là “wa”. です không thay đổi theo chủ ngữ như is/are trong tiếng Anh."}, {"pattern": "N1 は N2 じゃ ありません", "meaning": "N1 không phải là N2", "form": "Danh từ 1 + は + Danh từ 2 + じゃ ありません", "explain": "Để phủ định câu N1 は N2 です, ta thay です bằng じゃ ありません. Đây là cách nói “không phải” lịch sự, dùng rất nhiều khi đính chính thông tin về quốc tịch, nghề nghiệp, tên tuổi.", "examples": [{"jp": "わたしは 学生（がくせい）じゃ ありません。", "vi": "Tôi không phải là học sinh."}, {"jp": "あの 人（ひと）は 日本人（にほんじん）じゃ ありません。", "vi": "Người kia không phải là người Nhật."}], "note": "Dạng trang trọng hơn là ではありません (dewa arimasen); じゃ là dạng rút gọn dùng trong văn nói lịch sự thông thường."}, {"pattern": "～か (câu hỏi lịch sự)", "meaning": "Câu hỏi: …phải không? / …là… à?", "form": "Câu khẳng định/phủ định + か ; trả lời bằng はい / いいえ", "explain": "Muốn biến một câu trần thuật thành câu hỏi, chỉ cần thêm か vào cuối câu — không cần đảo trật tự từ như tiếng Anh. Khi trả lời, dùng はい (vâng) hoặc いいえ (không), rồi lặp lại phần thông tin chính.", "examples": [{"jp": "ミラーさんは アメリカ人（じん）ですか。— はい、アメリカ人（じん）です。", "vi": "Anh Miller là người Mỹ phải không? — Vâng, (anh ấy) là người Mỹ."}, {"jp": "田中（たなか）さんは 先生（せんせい）ですか。— いいえ、先生（せんせい）じゃ ありません。", "vi": "Anh Tanaka là giáo viên phải không? — Không, anh ấy không phải giáo viên."}]}, {"pattern": "N も", "meaning": "N cũng…", "form": "Danh từ + も (thay cho は khi ý nghĩa tương đồng)", "explain": "Trợ từ も có nghĩa là “cũng”. Khi sự việc về chủ đề mới giống hệt sự việc vừa nói trước đó, ta dùng も thay cho は để tránh lặp lại và nhấn mạnh sự tương đồng.", "examples": [{"jp": "わたしは 学生（がくせい）です。山田（やまだ）さんも 学生（がくせい）です。", "vi": "Tôi là học sinh. Anh Yamada cũng là học sinh."}, {"jp": "わたしも ベトナム人（じん）です。", "vi": "Tôi cũng là người Việt Nam."}]}, {"pattern": "N1 の N2", "meaning": "N2 của / thuộc về N1", "form": "Danh từ 1 + の + Danh từ 2", "explain": "Trợ từ の nối hai danh từ: danh từ đứng trước bổ nghĩa cho danh từ đứng sau. Mẫu này diễn tả sở hữu (của ai), nguồn gốc, nơi làm việc, hoặc nội dung/thể loại.", "examples": [{"jp": "これは わたしの 本（ほん）です。", "vi": "Đây là cuốn sách của tôi."}, {"jp": "わたしは 大学（だいがく）の 先生（せんせい）です。", "vi": "Tôi là giáo viên của trường đại học."}]}]}, "2": {"title": "Bài 2 — Minna no Nihongo", "intro": "Bài 2 dạy cách chỉ đồ vật ở gần/xa, hỏi đồ vật là gì, của ai, và xác nhận thông tin đúng – sai.", "points": [{"pattern": "これ / それ / あれ", "meaning": "cái này / cái đó / cái kia", "form": "これ・それ・あれ đứng độc lập, thay cho đồ vật (không đi kèm danh từ)", "explain": "Ba đại từ chỉ định phân theo khoảng cách so với người nói và người nghe: これ = vật ở gần người nói; それ = vật ở gần người nghe (xa người nói); あれ = vật ở xa cả hai người. Chúng đứng một mình, không kèm danh từ phía sau.", "examples": [{"jp": "これは 辞書（じしょ）です。", "vi": "Đây là cuốn từ điển."}, {"jp": "あれは わたしの かばんです。", "vi": "Kia là cặp của tôi."}], "note": "Đừng nhầm với この/その/あの: nhóm これ không đi kèm danh từ, nhóm この bắt buộc có danh từ theo sau."}, {"pattern": "この / その / あの + N", "meaning": "N này / N đó / N kia", "form": "この・その・あの + Danh từ", "explain": "Khi muốn chỉ đích danh đồ vật nào, ta dùng この/その/あの đứng ngay trước danh từ. Cách phân chia khoảng cách giống hệt これ/それ/あれ: この gần người nói, その gần người nghe, あの xa cả hai.", "examples": [{"jp": "この 本（ほん）は わたしのです。", "vi": "Cuốn sách này là của tôi."}, {"jp": "あの 人（ひと）は だれですか。", "vi": "Người kia là ai vậy?"}]}, {"pattern": "～、そうです / ちがいます", "meaning": "Đúng như vậy / Không phải, sai rồi", "form": "Trả lời câu hỏi xác nhận: はい、そうです。/ いいえ、ちがいます。", "explain": "そうです nghĩa là “đúng là như vậy”, dùng để xác nhận toàn bộ nội dung câu hỏi mà không cần lặp lại. Ngược lại, ちがいます nghĩa là “sai rồi, không phải thế”, lịch sự và tự nhiên hơn いいえ trần trụi khi đính chính đồ vật/thông tin.", "examples": [{"jp": "それは テレカですか。— はい、そうです。", "vi": "Đó là thẻ điện thoại phải không? — Vâng, đúng vậy."}, {"jp": "これは 9（きゅう）ですか。— いいえ、ちがいます。7（なな）です。", "vi": "Đây là số 9 phải không? — Không, sai rồi. Là số 7."}]}, {"pattern": "N1 の N2 (nội dung, xuất xứ)", "meaning": "N2 về… / của…", "form": "Danh từ 1 + の + Danh từ 2 (mở rộng của Bài 1)", "explain": "Ngoài sở hữu, の còn chỉ nội dung (sách về tiếng Nhật), xuất xứ/công ty sản xuất, và khi đứng cuối câu, N の có thể thay thế cho danh từ đã nhắc tới (わたしのです = cái của tôi).", "examples": [{"jp": "これは 日本語（にほんご）の 本（ほん）です。", "vi": "Đây là sách tiếng Nhật."}, {"jp": "その かばんは わたしのです。", "vi": "Cái cặp đó là của tôi."}]}]}, "3": {"title": "Bài 3 — Minna no Nihongo", "intro": "Bài 3 dạy cách hỏi và chỉ địa điểm: đây/đó/kia là đâu, một nơi nằm ở đâu, và cách chỉ hướng lịch sự.", "points": [{"pattern": "ここ / そこ / あそこ", "meaning": "ở đây / ở đó / ở kia", "form": "ここ・そこ・あそこ + です / に あります", "explain": "Nhóm từ chỉ nơi chốn tương ứng với これ/それ/あれ nhưng dùng cho địa điểm: ここ gần người nói, そこ gần người nghe, あそこ xa cả hai. Dùng khi giới thiệu một địa điểm đang ở trước mắt.", "examples": [{"jp": "ここは 教室（きょうしつ）です。", "vi": "Đây là phòng học."}, {"jp": "あそこは 図書館（としょかん）です。", "vi": "Kia là thư viện."}]}, {"pattern": "N (nơi chốn) は どこですか", "meaning": "N ở đâu?", "form": "Danh từ chỉ nơi chốn/người + は + どこ + ですか", "explain": "Để hỏi vị trí của một địa điểm hoặc nơi ở của một người, dùng mẫu N は どこですか. Câu trả lời thường là ここ/そこ/あそこ hoặc một địa điểm cụ thể kèm です.", "examples": [{"jp": "トイレは どこですか。— あそこです。", "vi": "Nhà vệ sinh ở đâu ạ? — Ở đằng kia ạ."}, {"jp": "事務所（じむしょ）は どこですか。", "vi": "Văn phòng ở đâu ạ?"}]}, {"pattern": "こっち / そっち / あっち", "meaning": "phía này / phía đó / phía kia (lịch sự)", "form": "こっち・そっち・あっち + です", "explain": "こっち/そっち/あっち là dạng lịch sự của ここ/そこ/あそこ khi chỉ hướng hoặc địa điểm một cách mềm mỏng, hay dùng trong nhà hàng, công ty khi hướng dẫn khách: “mời quý khách đi lối này”.", "examples": [{"jp": "エレベーターは あっちです。", "vi": "Thang máy ở phía đằng kia ạ."}, {"jp": "受付（うけつけ）は そっちです。", "vi": "Quầy lễ tân ở phía đó ạ."}], "note": "Khi nói chuyện thân mật, người Nhật cũng dùng こっち với nghĩa “phía tôi/bên tôi” (こっちに来て = lại đây)."}, {"pattern": "どこの N ですか", "meaning": "N của nước/công ty nào?", "form": "どこの + Danh từ + ですか ; trả lời: Quốc gia・Công ty + の + N + です", "explain": "どこの dùng để hỏi xuất xứ của sản phẩm: sản xuất ở nước nào, của công ty nào. Câu trả lời giữ nguyên cấu trúc N1 の N2 đã học.", "examples": [{"jp": "この ワインは どこの ワインですか。— イタリアの ワインです。", "vi": "Rượu vang này là rượu của nước nào? — Là rượu của Ý."}, {"jp": "その カメラは どこのですか。— 日本（にほん）のです。", "vi": "Cái máy ảnh đó là của nước nào? — Của Nhật."}]}]}, "4": {"title": "Bài 4 — Minna no Nihongo", "intro": "Bài 4 mở đầu về động từ: nói giờ giấc, việc làm hằng ngày, thời điểm làm việc và khoảng thời gian từ… đến…", "points": [{"pattern": "いま ～時（じ） ～分（ふん）です", "meaning": "Bây giờ là … giờ … phút", "form": "いま + số + 時（じ）+ số + 分（ふん/ぷん）+ です", "explain": "Cách nói giờ trong tiếng Nhật: giờ đọc kèm 時 (じ), phút đọc kèm 分 — chú ý các biến âm: 1分 いっぷん, 3分 さんぷん, 4分 よんぷん, 6分 ろっぷん, 8分 はっぷん, 10分 じゅっぷん. 半（はん） nghĩa là “rưỡi” (nửa giờ).", "examples": [{"jp": "いま 9（きゅう）時（じ） 10（じゅっ）分（ぷん）です。", "vi": "Bây giờ là 9 giờ 10 phút."}, {"jp": "会議（かいぎ）は 10（じゅう）時（じ）半（はん）からです。", "vi": "Cuộc họp bắt đầu từ 10 giờ rưỡi."}], "note": "4 giờ là よじ (không phải しじ), 9 giờ là くじ, 7 giờ là しちじ."}, {"pattern": "Động từ thể ます (hiện tại – tương lai)", "meaning": "làm / sẽ làm…", "form": "Vます (khẳng định) / Vません (phủ định) / Vました (quá khứ) / Vませんでした (phủ định quá khứ)", "explain": "Thể ます là thể lịch sự của động từ. Vます diễn tả hành động hiện tại thường xuyên hoặc sẽ làm trong tương lai; phủ định là Vません; quá khứ là Vました, phủ định quá khứ là Vませんでした. Đây là “khung xương” để nói mọi hoạt động hằng ngày.", "examples": [{"jp": "わたしは 毎朝（まいあさ） 6（ろく）時（じ）に 起（お）きます。", "vi": "Sáng nào tôi cũng dậy lúc 6 giờ."}, {"jp": "きのうは 働（はたら）きませんでした。", "vi": "Hôm qua tôi đã không làm việc."}]}, {"pattern": "N (thời gian) に V", "meaning": "làm V vào lúc…", "form": "Danh từ chỉ thời điểm cụ thể + に + Động từ", "explain": "Trợ từ に đánh dấu thời điểm cụ thể mà hành động xảy ra: giờ giấc, ngày tháng, thứ trong tuần. Nhưng các từ chỉ thời gian tương đối như 今日・明日・毎日・いつ thì KHÔNG dùng に.", "examples": [{"jp": "銀行（ぎんこう）は 午前（ごぜん） 9（きゅう）時（じ）に 開（あ）きます。", "vi": "Ngân hàng mở cửa lúc 9 giờ sáng."}, {"jp": "わたしは 金曜日（きんようび）に 日本（にほん）へ 行（い）きます。", "vi": "Tôi sẽ đi Nhật vào thứ Sáu."}], "note": "Sai thường gặp: ×明日に 行きます → đúng là 明日 行きます (không có に)."}, {"pattern": "～から ～まで", "meaning": "từ… đến…", "form": "Thời gian/địa điểm 1 + から + Thời gian/địa điểm 2 + まで", "explain": "から chỉ điểm bắt đầu, まで chỉ điểm kết thúc — dùng cho cả thời gian và quãng đường. Hai từ có thể dùng riêng lẻ: から = từ…, まで = đến…", "examples": [{"jp": "仕事（しごと）は 9（きゅう）時（じ）から 5（ご）時（じ）までです。", "vi": "Công việc từ 9 giờ đến 5 giờ."}, {"jp": "家（いえ）から 駅（えき）まで 歩（ある）いて 10（じゅっ）分（ぷん）です。", "vi": "Từ nhà đến ga đi bộ mất 10 phút."}]}, {"pattern": "N と N", "meaning": "N và N", "form": "Danh từ 1 + と + Danh từ 2", "explain": "Trợ từ と liệt kê danh từ với nghĩa “và” — liệt kê đầy đủ, dứt khoát. Hay gặp trong câu giờ làm việc: 銀行の 休みは 土曜日と 日曜日です.", "examples": [{"jp": "この 店（みせ）の 休（やす）みは 水曜日（すいようび）と 木曜日（もくようび）です。", "vi": "Ngày nghỉ của cửa hàng này là thứ Tư và thứ Năm."}, {"jp": "朝（あさ）ごはんは パンと コーヒーです。", "vi": "Bữa sáng là bánh mì và cà phê."}]}]}, "5": {"title": "Bài 5 — Minna no Nihongo", "intro": "Bài 5 dạy cách nói di chuyển: đi đâu, đi bằng phương tiện gì, đi cùng ai và đi khi nào.", "points": [{"pattern": "場所（ばしょ） へ 行（い）きます / 来（き）ます / 帰（かえ）ります", "meaning": "đi / đến / trở về (nơi chốn)", "form": "Danh từ chỉ nơi chốn + へ + 行きます・来ます・帰ります", "explain": "Ba động từ di chuyển cơ bản luôn đi với trợ từ へ (đọc là “e”) chỉ hướng/đích đến: 行きます = đi (ra xa người nói), 来ます = đến (về phía người nói), 帰ります = trở về (nhà/quê hương/nơi thuộc về mình).", "examples": [{"jp": "あした 京都（きょうと）へ 行（い）きます。", "vi": "Ngày mai tôi đi Kyoto."}, {"jp": "先月（せんげつ） ベトナムへ 帰（かえ）りました。", "vi": "Tháng trước tôi đã về Việt Nam."}], "note": "へ viết là へ nhưng đọc là “e”. Có thể thay bằng に trong nhiều trường hợp, nhưng へ nhấn mạnh hướng đi."}, {"pattern": "乗り物（のりもの） で 場所 へ 行きます", "meaning": "đi đến… bằng (phương tiện)", "form": "Phương tiện + で + Nơi chốn + へ + Động từ di chuyển", "explain": "Trợ từ で sau phương tiện giao thông chỉ “bằng cách nào”. Nếu đi bộ, không dùng で mà dùng động từ riêng: 歩いて 行きます.", "examples": [{"jp": "電車（でんしゃ）で 大学（だいがく）へ 行（い）きます。", "vi": "Tôi đi đến trường đại học bằng tàu điện."}, {"jp": "何（なに）で 東京（とうきょう）へ 行（い）きますか。— 飛行機（ひこうき）です。", "vi": "Bạn đi Tokyo bằng gì? — Bằng máy bay."}]}, {"pattern": "人（ひと） と 場所 へ 行きます", "meaning": "đi đến… cùng (ai)", "form": "Người + と + Nơi chốn + へ + Động từ di chuyển", "explain": "と ở đây nghĩa là “cùng với”. Nếu đi một mình, dùng 一人で (một mình). Lưu ý phân biệt と “cùng” với と “và” ở Bài 4 dựa vào động từ phía sau.", "examples": [{"jp": "友達（ともだち）と 北海道（ほっかいどう）へ 行（い）きます。", "vi": "Tôi đi Hokkaido cùng bạn."}, {"jp": "一人（ひとり）で 日本（にほん）へ 来（き）ました。", "vi": "Tôi đã đến Nhật một mình."}]}, {"pattern": "いつ Vますか", "meaning": "khi nào thì…?", "form": "いつ + câu có động từ ; thời gian tương đối không dùng に", "explain": "いつ là từ để hỏi “khi nào”, dùng khi không biết thời điểm. Khi trả lời bằng các từ như 今日・明日・来週・いつも, tuyệt đối không thêm に — đây là lỗi rất hay gặp ở người mới học.", "examples": [{"jp": "いつ 日本（にほん）へ 来（き）ましたか。— 去年（きょねん）の 3月（さんがつ）に 来（き）ました。", "vi": "Bạn đến Nhật khi nào? — Tôi đến vào tháng 3 năm ngoái."}, {"jp": "誕生日（たんじょうび）は いつですか。", "vi": "Sinh nhật của bạn là khi nào?"}], "note": "Ngày tháng cụ thể (3月, 15日, 金曜日) thì CÓ dùng に; từ tương đối (明日, 昨日, 毎日) thì KHÔNG."}]}, "6": {"title": "Bài 6 — Minna no Nihongo", "intro": "Bài 6 dạy cách nói về hành động với đồ vật: ăn gì, uống gì, làm gì ở đâu — và cách mời mọc, rủ rê lịch sự.", "points": [{"pattern": "N を Vます", "meaning": "làm V với N (tân ngữ)", "form": "Danh từ + を + Động từ tha động từ", "explain": "Trợ từ を (đọc là “o”) đánh dấu tân ngữ trực tiếp — đối tượng chịu tác động của hành động: ăn cơm, uống nước, xem TV, nghe nhạc. を luôn đứng ngay trước động từ (qua danh từ tân ngữ).", "examples": [{"jp": "わたしは 毎朝（まいあさ） パンを 食（た）べます。", "vi": "Sáng nào tôi cũng ăn bánh mì."}, {"jp": "日本語（にほんご）の 新聞（しんぶん）を 読（よ）みます。", "vi": "Tôi đọc báo tiếng Nhật."}], "note": "を viết là を nhưng đọc là “o”. Đừng nhầm với trợ từ に (điểm đến/thời gian)."}, {"pattern": "場所（ばしょ） で Vます", "meaning": "làm V tại (nơi chốn)", "form": "Nơi chốn + で + Động từ hành động", "explain": "Khi で đứng sau địa điểm, nó chỉ nơi diễn ra hành động (khác với で chỉ phương tiện ở Bài 5). Câu trả lời cho “làm việc đó ở đâu” luôn là [nơi] で.", "examples": [{"jp": "駅（えき）で 新聞（しんぶん）を 買（か）います。", "vi": "Tôi mua báo ở ga."}, {"jp": "図書館（としょかん）で 本（ほん）を 読（よ）みます。", "vi": "Tôi đọc sách ở thư viện."}]}, {"pattern": "Vませんか", "meaning": "…có muốn cùng làm… không? (lời mời)", "form": "Động từ thể ません + か", "explain": "Dùng thể phủ định + か để mời mọc một cách lịch sự, mềm mỏng hơn câu hỏi thẳng: người nghe dễ từ chối hơn nên rất được ưa dùng khi rủ đồng nghiệp, bạn bè đi ăn, xem phim, chơi thể thao.", "examples": [{"jp": "いっしょに 映画（えいが）を 見（み）ませんか。", "vi": "Bạn có muốn cùng đi xem phim không?"}, {"jp": "あした テニスを しませんか。", "vi": "Ngày mai bạn có muốn chơi tennis không?"}]}, {"pattern": "Vましょう", "meaning": "Chúng ta hãy cùng… nhé! (đề xuất)", "form": "Động từ thể ましょう (Vます bỏ ます thêm ましょう)", "explain": "ましょう là lời đề xuất “hãy cùng làm” đầy thiện chí, dùng khi người nói cũng tham gia hành động đó. Đây là cặp đôi kinh điển với Vませんか: một người mời bằng ませんか, người kia đồng ý bằng ましょう.", "examples": [{"jp": "休（やす）みましょう。", "vi": "Chúng ta nghỉ một chút đi."}, {"jp": "いっしょに 帰（かえ）りましょう。", "vi": "Chúng ta cùng về thôi."}]}]}, "7": {"title": "Bài 7 — Minna no Nihongo", "intro": "Bài 7 dạy cách dùng công cụ để làm việc, và đặc biệt quan trọng: các mẫu cho – nhận đồ vật giữa người với người.", "points": [{"pattern": "道具（どうぐ）/言葉（ことば） で Vます", "meaning": "làm V bằng (công cụ/ngôn ngữ)", "form": "Công cụ・ngôn ngữ + で + Động từ", "explain": "で còn chỉ công cụ, phương tiện, chất liệu hoặc ngôn ngữ dùng để thực hiện hành động: viết bằng bút, cắt bằng kéo, nói bằng tiếng Nhật. Đây là cách dùng thứ ba của で (sau địa điểm và phương tiện giao thông).", "examples": [{"jp": "はしで ごはんを 食（た）べます。", "vi": "Tôi ăn cơm bằng đũa."}, {"jp": "日本語（にほんご）で 手紙（てがみ）を 書（か）きます。", "vi": "Tôi viết thư bằng tiếng Nhật."}]}, {"pattern": "人（ひと） に 物（もの） を あげます", "meaning": "cho/tặng (ai) (cái gì)", "form": "Người nhận + に + Vật + を + あげます (và nhóm かします・教えます・送ります)", "explain": "Khi cho/tặng, người nhận được đánh dấu bằng に, vật được cho đánh dấu bằng を. Cùng cấu trúc này dùng với 貸します (cho mượn), 教えます (dạy/cho biết), 送ります (gửi cho). Chủ ngữ (người cho) thường là わたし, đánh dấu bằng は.", "examples": [{"jp": "わたしは 友達（ともだち）に 花（はな）を あげます。", "vi": "Tôi tặng hoa cho bạn."}, {"jp": "先生（せんせい）は 学生（がくせい）に 日本語（にほんご）を 教（おし）えます。", "vi": "Thầy giáo dạy tiếng Nhật cho học sinh."}], "note": "Không dùng あげます khi người nhận là chính mình hoặc người nhà mình nhận từ người ngoài — trường hợp đó dùng もらいます."}, {"pattern": "人（ひと） に 物（もの） を もらいます", "meaning": "(tôi) nhận (cái gì) từ (ai)", "form": "Người cho + に + Vật + を + もらいます (và nhóm 借ります・習います)", "explain": "もらいます diễn tả việc nhận từ góc nhìn của người nhận — luôn hàm ý biết ơn. Người cho đánh dấu bằng に (hoặc から), vật nhận được đánh dấu bằng を. Cùng họ: 借ります (mượn), 習います (học từ ai).", "examples": [{"jp": "わたしは 母（はは）に セーターを もらいました。", "vi": "Tôi nhận được chiếc áo len từ mẹ."}, {"jp": "田中（たなか）さんに 日本語（にほんご）を 習（なら）います。", "vi": "Tôi học tiếng Nhật từ anh Tanaka."}]}, {"pattern": "もう Vました / まだです", "meaning": "đã làm V rồi / chưa (làm)", "form": "もう + Động từ quá khứ ; trả lời phủ định: いいえ、まだです", "explain": "もう đi với thể quá khứ khẳng định nghĩa là “đã… rồi”. Khi được hỏi もう Vましたか mà chưa làm, câu trả lời chuẩn là まだです (chưa ạ) — không trả lời bằng thể phủ định quá khứ trần trụi.", "examples": [{"jp": "もう 昼（ひる）ごはんを 食（た）べましたか。— はい、もう 食（た）べました。", "vi": "Bạn ăn trưa rồi à? — Vâng, tôi ăn rồi."}, {"jp": "もう レポートを 書（か）きましたか。— いいえ、まだです。", "vi": "Bạn viết báo cáo rồi à? — Chưa, tôi chưa viết."}]}]}, "8": {"title": "Bài 8 — Minna no Nihongo", "intro": "Bài 8 mở đầu về tính từ: miêu tả đồ vật, con người, nơi chốn là “như thế nào”, kèm cách chia tính từ theo thì.", "points": [{"pattern": "い形容詞 (tính từ -i)", "meaning": "tính từ tận cùng bằng い: to, rẻ, ngon…", "form": "…い + です / quá khứ …かったです / phủ định …くないです", "explain": "Tính từ -i là nhóm tính từ gốc Nhật, tận cùng bằng い và TỰ MÌNH biến đổi: quá khứ bỏ い thêm かった (大きかった), phủ định bỏ い thêm くない (大きくない). Đứng trước danh từ thì giữ nguyên dạng …い + N.", "examples": [{"jp": "この 本（ほん）は おもしろいです。", "vi": "Cuốn sách này hay."}, {"jp": "きのうは 寒（さむ）かったです。", "vi": "Hôm qua trời lạnh."}], "note": "Ngoại lệ nổi tiếng: いい (tốt) chia theo gốc よ — よかった, よくない. Không bao giờ nói いかった."}, {"pattern": "な形容詞 (tính từ -na)", "meaning": "tính từ -na: yên tĩnh, tiện lợi, nổi tiếng…", "form": "…な + Danh từ / …です / quá khứ …でした / phủ định …じゃ ありません", "explain": "Tính từ -na mượn nhiều từ Hán, bản thân nó chia GIỐNG HỆT danh từ: khẳng định …です, phủ định …じゃありません, quá khứ …でした. Khi đứng trước danh từ để bổ nghĩa, bắt buộc thêm な: 静（しず）かな 部屋.", "examples": [{"jp": "ここは 静（しず）かな 町（まち）です。", "vi": "Đây là một thành phố yên tĩnh."}, {"jp": "あの 人（ひと）は 親切（しんせつ）じゃ ありません。", "vi": "Người kia không thân thiện."}]}, {"pattern": "とても / あまり", "meaning": "rất… / không… lắm", "form": "とても + khẳng định ; あまり + phủ định", "explain": "とても tăng mức độ cho câu khẳng định (“rất”). あまり chỉ đi với câu PHỦ ĐỊNH, nghĩa là “không… lắm”. Ghép sai cặp (あまり + khẳng định) là lỗi kinh điển của người học.", "examples": [{"jp": "この ケーキは とても おいしいです。", "vi": "Cái bánh này rất ngon."}, {"jp": "きょうは あまり 寒（さむ）くないです。", "vi": "Hôm nay trời không lạnh lắm."}]}, {"pattern": "N は どうですか / ～が、～", "meaning": "N thế nào? / …, nhưng…", "form": "Hỏi cảm nhận: N は どうですか ; nối hai vế tương phản nhẹ: ～が、～", "explain": "どうですか dùng để hỏi cảm nhận/đánh giá về một thứ. Trợ từ が ở giữa câu nối hai vế có ý tương phản hoặc mở đầu câu chuyện một cách nhẹ nhàng, không gay gắt như “nhưng” trong tiếng Việt.", "examples": [{"jp": "日本（にほん）の 生活（せいかつ）は どうですか。", "vi": "Cuộc sống ở Nhật thế nào?"}, {"jp": "この 店（みせ）は おいしいですが、ちょっと 高（たか）いです。", "vi": "Quán này ngon, nhưng hơi đắt."}]}]}, "9": {"title": "Bài 9 — Minna no Nihongo", "intro": "Bài 9 dạy cách nói về khả năng, sở thích và lý do: làm được gì, thích/ghét gì, giỏi/kém gì — và vì sao.", "points": [{"pattern": "N が あります / わかります", "meaning": "có (khả năng/thời gian) / hiểu (ngôn ngữ, vấn đề)", "form": "Đối tượng + が + あります・わかります", "explain": "Một số động từ đặc biệt dùng trợ từ が thay cho を để chỉ đối tượng: わかります (hiểu), あります (có — về thời gian, khả năng, điều kiện). Đây là tiền đề cho mẫu sở thích ở ngay dưới.", "examples": [{"jp": "わたしは 日本語（にほんご）が 少し（すこし） わかります。", "vi": "Tôi hiểu tiếng Nhật một chút."}, {"jp": "明日（あした） 時間（じかん）が ありますか。", "vi": "Ngày mai bạn có thời gian không?"}]}, {"pattern": "好（す）き / 嫌（きら）い / 上手（じょうず）/ 下手（へた） + が", "meaning": "thích / ghét / giỏi / kém (về…)", "form": "Danh từ + が + 好きです・嫌いです・上手です・下手です", "explain": "Bốn tính từ -na này luôn đi với trợ từ が chỉ đối tượng: thích cái gì, giỏi môn gì. Mức độ thích tăng dần: 好き → とても好き → 大好き (rất thích). 下手 khi nói về bản thân thì lịch sự, nói về người khác thì hơi mất lịch sự — nên cẩn thận.", "examples": [{"jp": "わたしは サッカーが 大好（だいす）きです。", "vi": "Tôi rất thích bóng đá."}, {"jp": "彼女（かのじょ）は 歌（うた）が 上手（じょうず）です。", "vi": "Cô ấy hát giỏi (giỏi về hát)."}], "note": "Người Nhật khiêm tốn: được khen 上手ですね họ thường đáp いいえ、まだまだです (chưa đâu ạ) thay vì cảm ơn ngay."}, {"pattern": "よく / だいたい / たくさん / 少（すこ）し / 全然（ぜんぜん）/ あまり", "meaning": "các phó từ chỉ mức độ – tần suất", "form": "Phó từ đứng trước động từ ; 全然・あまり đi với phủ định", "explain": "Nhóm phó từ lượng: よく (kỹ/thường xuyên), だいたい (hầu như, đại khái), たくさん (nhiều), 少し (một ít). 全然 và あまり bắt buộc đi với câu phủ định: 全然 わかりません = hoàn toàn không hiểu.", "examples": [{"jp": "わたしは 日本語（にほんご）が だいたい わかります。", "vi": "Tôi hiểu tiếng Nhật đại khái."}, {"jp": "漢字（かんじ）は 全然（ぜんぜん） わかりません。", "vi": "Chữ Hán thì tôi hoàn toàn không hiểu."}]}, {"pattern": "～から、～", "meaning": "vì…, nên… (nêu lý do ở vế sau)", "form": "Câu kết quả + 。+ Lý do + から。", "explain": "から là liên từ chỉ lý do, nhưng cấu trúc tiếng Nhật ở mẫu này đặt KẾT QUẢ trước, LÝ DO sau — ngược với tiếng Việt. Thường dùng khi người nghe hỏi どうして (tại sao) và ta trả lời ngắn gọn chỉ bằng vế lý do + から.", "examples": [{"jp": "忙（いそが）しいです。時間（じかん）が ありませんから。", "vi": "Tôi bận. Vì không có thời gian."}, {"jp": "どうして 遅（おく）れたんですか。— 電車（でんしゃ）が 止（と）まったからです。", "vi": "Sao bạn đến muộn thế? — Vì tàu điện bị dừng."}]}]}, "10": {"title": "Bài 10 — Minna no Nihongo", "intro": "Bài 10 dạy cách nói sự tồn tại và vị trí: ở đâu có cái gì, một vật/một người đang ở vị trí nào.", "points": [{"pattern": "場所（ばしょ） に N が あります / います", "meaning": "Ở (nơi) có (vật/người)…", "form": "Nơi chốn + に + Vật/Người + が + あります (vật) / います (người, con vật)", "explain": "あります dùng cho vật vô tri (và cây cối), います dùng cho người và động vật. Trợ từ に chỉ nơi tồn tại, が chỉ vật/người tồn tại. Đây là mẫu trả lời cho câu hỏi “ở đó có gì”.", "examples": [{"jp": "机（つくえ）の 上（うえ）に 本（ほん）が あります。", "vi": "Trên bàn có cuốn sách."}, {"jp": "教室（きょうしつ）に 学生（がくせい）が います。", "vi": "Trong lớp học có học sinh."}], "note": "Phân biệt: cây cối dùng あります (木があります), cá đang bơi trong bể dùng います."}, {"pattern": "N は 場所（ばしょ） に あります / います", "meaning": "N thì ở (nơi)…", "form": "Vật/Người + は + Nơi chốn + に + あります / います", "explain": "Khi vật/người đã được biết đến (là chủ đề), ta đảo vị trí câu: chủ đề + は đứng đầu, địa điểm thành thông tin mới. Dùng để trả lời câu hỏi “cái đó ở đâu, anh ấy ở đâu”.", "examples": [{"jp": "東京（とうきょう）ディズニーランドは 千葉県（ちばけん）に あります。", "vi": "Tokyo Disneyland thì ở tỉnh Chiba."}, {"jp": "佐藤（さとう）さんは 会議室（かいぎしつ）に います。", "vi": "Anh Sato đang ở phòng họp."}]}, {"pattern": "Từ chỉ vị trí: 上・下・前・後（うし）ろ・右・左・中・外・隣（となり）・近く・間（あいだ）", "meaning": "trên / dưới / trước / sau / phải / trái / trong / ngoài / bên cạnh / gần / giữa", "form": "N1 + の + từ vị trí + に", "explain": "Nhóm danh từ vị trí luôn đi sau の của vật mốc: 机の上 = trên (cái) bàn. 間 luôn cần hai mốc hai bên (A と B の 間). Thuộc lòng nhóm này là chìa khóa để miêu tả mọi sơ đồ, bản đồ.", "examples": [{"jp": "猫（ねこ）は 箱（はこ）の 中（なか）に います。", "vi": "Con mèo ở trong hộp."}, {"jp": "銀行（ぎんこう）は 駅（えき）と 郵便局（ゆうびんきょく）の 間（あいだ）に あります。", "vi": "Ngân hàng nằm giữa ga và bưu điện."}]}]}, "11": {"title": "Bài 11 — Minna no Nihongo", "intro": "Bài 11 dạy đếm số lượng đồ vật bằng các lượng từ khác nhau, xin/nhờ ai cho một số lượng, và hỏi mất bao lâu.", "points": [{"pattern": "Số + lượng từ (助数詞)", "meaning": "đếm vật theo đơn vị: cái, tờ, quyển, chiếc…", "form": "Số đếm + lượng từ phù hợp với loại vật: 個（こ）・枚（まい）・本（ほん）・台（だい）・杯（はい）・匹（ひき）・人（にん）…", "explain": "Tiếng Nhật đếm vật bằng lượng từ riêng cho từng loại: đồ nhỏ dùng 個, vật mỏng phẳng dùng 枚, vật dài dùng 本, máy móc/xe dùng 台, người dùng 人 (1 người ひとり, 2 người ふたり là ngoại lệ). Đồ vật nói chung đếm bằng ひとつ・ふたつ… (tối đa đến とお).", "examples": [{"jp": "りんごを 5（いつ）つ 買（か）いました。", "vi": "Tôi đã mua 5 quả táo."}, {"jp": "切手（きって）を 3（さん）枚（まい） ください。", "vi": "Cho tôi 3 con tem."}], "note": "Số 4 đọc よん/し tùy lượng từ (4人 よにん nhưng 4つ よっつ); số 9 là きゅう, số 7 là なな — nên nghe kỹ khi người bản xứ đếm."}, {"pattern": "N を Số lượng ください", "meaning": "Cho tôi (số lượng) N", "form": "Danh từ + を + Số + lượng từ + ください", "explain": "ください sau số lượng là cách xin/mua lịch sự trong nhà hàng, cửa hàng. Bỏ を vẫn hiểu nhưng có を thì chuẩn ngữ pháp và lịch sự hơn.", "examples": [{"jp": "ビールを 2（ふた）つ ください。", "vi": "Cho tôi 2 (chai/cốc) bia."}, {"jp": "この 荷物（にもつ）を 航空便（こうくうびん）で お願（ねが）いします。", "vi": "Gói hành lý này xin gửi bằng đường hàng không."}]}, {"pattern": "時間（じかん） かかります", "meaning": "mất (bao lâu)", "form": "Khoảng thời gian + かかります ; hỏi: どのくらい / 何時間 かかりますか", "explain": "かかります diễn tả thời gian (hoặc tiền) cần tiêu tốn để hoàn thành một việc/di chuyển. Từ hỏi thời lượng là どのくらい hoặc 何時間・何分. Khác với に chỉ thời điểm: かかります đi với khoảng thời gian thuần túy, không có に.", "examples": [{"jp": "大阪（おおさか）から 東京（とうきょう）まで 飛行機（ひこうき）で 1（いち）時間（じかん） かかります。", "vi": "Từ Osaka đến Tokyo đi máy bay mất 1 tiếng."}, {"jp": "家（いえ）から 会社（かいしゃ）まで どのくらい かかりますか。", "vi": "Từ nhà đến công ty mất bao lâu?"}]}, {"pattern": "～だけ", "meaning": "chỉ…", "form": "Danh từ/Số lượng + だけ + khẳng định", "explain": "だけ giới hạn phạm vi: “chỉ chừng đó thôi”, hàm ý số lượng ít hoặc phạm vi hẹp. Đứng sau danh từ, số lượng, hoặc động từ thể từ điển đều được.", "examples": [{"jp": "休（やす）みは 日曜日（にちようび）だけです。", "vi": "Ngày nghỉ chỉ có chủ nhật thôi."}, {"jp": "わたしは 日本語（にほんご）が 少し（すこし）だけ わかります。", "vi": "Tôi chỉ hiểu tiếng Nhật một chút thôi."}]}]}, "12": {"title": "Bài 12 — Minna no Nihongo", "intro": "Bài 12 dạy thì quá khứ của danh từ/tính từ và nghệ thuật so sánh: hơn – nhất – cái nào hơn.", "points": [{"pattern": "Quá khứ của N / な形容詞: ～でした", "meaning": "đã là… / đã (yên tĩnh, tiện lợi…)", "form": "N・な形 + でした ; phủ định quá khứ: じゃ ありませんでした", "explain": "Danh từ và tính từ -na không tự biến đổi nên mượn です chia quá khứ: でした = đã là/đã…, phủ định quá khứ là じゃ ありませんでした. Đây là mảnh ghép cuối để nói mọi câu miêu tả ở thì quá khứ.", "examples": [{"jp": "きのうは 雨（あめ）でした。", "vi": "Hôm qua trời mưa (là một ngày mưa)."}, {"jp": "先週（せんしゅう）の 試験（しけん）は 難（むずか）しかったです。", "vi": "Kỳ thi tuần trước khó."}]}, {"pattern": "Quá khứ của い形容詞: ～かったです", "meaning": "đã (to, rẻ, ngon…)", "form": "Tính từ -i bỏ い + かったです ; phủ định quá khứ: くなかったです", "explain": "Tính từ -i tự chia quá khứ bằng đuôi かった: 大きかった, 高かった. Nhớ ngoại lệ いい → よかった (không nói いかった). Kết hợp với Bài 8 là ta đã chia đủ 4 ô cho cả hai nhóm tính từ.", "examples": [{"jp": "旅行（りょこう）は 楽（たの）しかったです。", "vi": "Chuyến du lịch rất vui."}, {"jp": "あの 映画（えいが）は あまり おもしろくなかったです。", "vi": "Bộ phim đó không hay lắm."}]}, {"pattern": "N1 は N2 より 形容詞です", "meaning": "N1 (tính từ) hơn N2", "form": "N1 + は + N2 + より + Tính từ + です", "explain": "より là mốc so sánh “hơn”: vật đứng trước より là vật làm mốc (kém hơn), vật được khẳng định thắng thế đứng ở đầu câu với は.", "examples": [{"jp": "飛行機（ひこうき）は 電車（でんしゃ）より 速（はや）いです。", "vi": "Máy bay nhanh hơn tàu điện."}, {"jp": "今日（きょう）は 昨日（きのう）より 暑（あつ）いです。", "vi": "Hôm nay nóng hơn hôm qua."}]}, {"pattern": "N1 と N2 と どちらが 形容詞ですか", "meaning": "(giữa N1 và N2) cái nào (tính từ) hơn?", "form": "N1 と N2 と どちらが + Tính từ + ですか ; trả lời: ～の ほうが + Tính từ + です", "explain": "どちらが dùng để hỏi so sánh giữa đúng hai đối tượng. Câu trả lời bắt buộc dùng cấu trúc ～の ほうが (phía… thì hơn).", "examples": [{"jp": "サッカーと 野球（やきゅう）と どちらが おもしろいですか。— サッカーの ほうが おもしろいです。", "vi": "Bóng đá và bóng chày, môn nào hay hơn? — Bóng đá hay hơn."}, {"jp": "日本語（にほんご）と 英語（えいご）と どちらが 難（むずか）しいですか。", "vi": "Tiếng Nhật và tiếng Anh, tiếng nào khó hơn?"}]}, {"pattern": "N の 中（なか）で 何（なに）が いちばん 形容詞ですか", "meaning": "Trong (nhóm N), cái gì (tính từ) nhất?", "form": "Phạm vi + の中で + Từ hỏi + が + いちばん + Tính từ + ですか", "explain": "いちばん (nhất) luôn đi kèm một phạm vi so sánh giới thiệu bằng の中で. Từ hỏi thay đổi theo đối tượng: vật là 何, người là だれ, nơi chốn là どこ, thời điểm là いつ.", "examples": [{"jp": "スポーツの 中（なか）で 何（なに）が いちばん 好（す）きですか。", "vi": "Trong các môn thể thao, bạn thích môn nào nhất?"}, {"jp": "日本（にほん）で どこが いちばん 有名（ゆうめい）ですか。", "vi": "Ở Nhật, nơi nào nổi tiếng nhất?"}]}]}, "13": {"title": "Bài 13 — Minna no Nihongo", "intro": "Bài 13 dạy bộc lộ mong muốn: muốn có cái gì, muốn làm gì — và nói mục đích của việc di chuyển.", "points": [{"pattern": "N が ほしいです", "meaning": "(tôi) muốn (có) N", "form": "Danh từ + が + ほしいです (tính từ -i)", "explain": "ほしい là tính từ -i diễn tả mong muốn sở hữu của CHÍNH NGƯỜI NÓI. Đối tượng muốn có đánh dấu bằng が. Chia như tính từ -i: phủ định ほしくない, quá khứ ほしかった. Người Nhật không dùng ほしい để hỏi thẳng mong muốn của cấp trên vì hơi thiếu tế nhị.", "examples": [{"jp": "わたしは 新（あたら）しい 車（くるま）が ほしいです。", "vi": "Tôi muốn có một chiếc xe mới."}, {"jp": "今（いま） 何（なに）が いちばん ほしいですか。", "vi": "Bây giờ bạn muốn (có) cái gì nhất?"}]}, {"pattern": "V(ます stem) たいです", "meaning": "(tôi) muốn làm V", "form": "Động từ bỏ ます + たいです ; tân ngữ dùng を hoặc が", "explain": "たい diễn tả mong muốn thực hiện hành động của người nói, chia đúng như tính từ -i (たくない, たかった). Tân ngữ của động từ đi với たい có thể dùng を hoặc が đều đúng. Giống ほしい, たい chủ yếu dùng cho ngôi thứ nhất (và câu hỏi với ngôi thứ hai).", "examples": [{"jp": "沖縄（おきなわ）へ 行（い）きたいです。", "vi": "Tôi muốn đi Okinawa."}, {"jp": "おいしい すしを 食（た）べたいです。", "vi": "Tôi muốn ăn sushi ngon."}], "note": "Muốn rủ người khác thì không dùng たい mà quay lại Vませんか của Bài 6."}, {"pattern": "場所（ばしょ） へ V(ます stem) に 行（い）きます", "meaning": "đi đến (nơi) để làm V", "form": "Nơi chốn + へ + Động từ bỏ ます + に + 行きます・来ます・帰ります", "explain": "Mẫu mục đích kinh điển: phần [V stem + に] nêu lý do/mục đích của việc di chuyển. Thứ tự luôn là: đích đến → mục đích → động từ di chuyển.", "examples": [{"jp": "図書館（としょかん）へ 本（ほん）を 借（か）りに 行（い）きます。", "vi": "Tôi đi đến thư viện để mượn sách."}, {"jp": "デパートへ 買（か）い物（もの）に 行（い）きます。", "vi": "Tôi đi đến trung tâm thương mại để mua sắm."}]}, {"pattern": "どこか / 何（なに）か", "meaning": "đâu đó / cái gì đó (không xác định)", "form": "どこか・何か + Động từ", "explain": "どこか = một nơi nào đó, 何か = một cái gì đó — dùng khi người nói không xác định rõ hoặc không cần nói rõ đối tượng. Trong câu hỏi lịch sự 何か ほしいですか nghĩa là “bạn muốn dùng gì không ạ”.", "examples": [{"jp": "夏休（なつやす）みは どこかへ 行（い）きたいです。", "vi": "Kỳ nghỉ hè tôi muốn đi đâu đó."}, {"jp": "のどが かわきました。何（なに）か 飲（の）みたいです。", "vi": "Tôi khát nước. Tôi muốn uống cái gì đó."}]}]}, "14": {"title": "Bài 14 — Minna no Nihongo", "intro": "Bài 14 giới thiệu thể て của động từ — chiếc chìa khóa vạn năng mở ra hàng loạt mẫu câu quan trọng nhất của tiếng Nhật sơ cấp.", "points": [{"pattern": "Động từ thể て (て形)", "meaning": "thể て — dạng nối câu của động từ", "form": "Nhóm 1: い・ち・り→って / み・び・に→んで / き→いて / ぎ→いで / し→して ; Nhóm 2: bỏ る + て ; Nhóm 3: して・きて", "explain": "Thể て là dạng động từ dùng để nối câu và tạo vô số mẫu ngữ pháp phía sau. Cách chia theo 3 nhóm động từ là phần PHẢI thuộc lòng ở giai đoạn này: nhóm 1 biến âm theo hàng cuối, nhóm 2 đơn giản bỏ る thêm て, nhóm 3 chỉ có する→して và 来る→来て.", "examples": [{"jp": "窓（まど）を 開（あ）けて ください。", "vi": "Hãy mở cửa sổ giúp tôi."}, {"jp": "本（ほん）を 読（よ）んで います。", "vi": "Tôi đang đọc sách."}], "note": "Mẹo nhớ nhóm 1: 書く→書いて, 泳ぐ→泳いで là hai động từ dễ nhầm nhất (hàng く là いて, hàng ぐ là いで)."}, {"pattern": "Vて ください", "meaning": "Hãy làm V / Xin hãy…", "form": "Động từ thể て + ください", "explain": "ください sau thể て tạo lời yêu cầu, nhờ vả lịch sự — mẫu câu dùng nhiều nhất nơi công sở, lớp học. Thêm ちょっと vào đầu câu sẽ làm lời nhờ vả mềm hơn hẳn.", "examples": [{"jp": "ちょっと 待（ま）って ください。", "vi": "Xin chờ một chút."}, {"jp": "ここに 名前（なまえ）を 書（か）いて ください。", "vi": "Hãy viết tên vào đây."}]}, {"pattern": "Vて います", "meaning": "đang làm V (hành động đang diễn tiến)", "form": "Động từ thể て + います", "explain": "ています diễn tả hành động đang xảy ra ngay lúc nói — tương đương thì hiện tại tiếp diễn. Với động từ khoảnh khắc (開ける, 乗る) thì ています lại mang nghĩa trạng thái, sẽ học kỹ ở Bài 15.", "examples": [{"jp": "田中（たなか）さんは 今（いま） 電話（でんわ）を かけて います。", "vi": "Anh Tanaka đang gọi điện thoại bây giờ."}, {"jp": "雨（あめ）が 降（ふ）って います。", "vi": "Trời đang mưa."}]}, {"pattern": "Vて から", "meaning": "sau khi làm V xong thì…", "form": "Động từ thể て + から + hành động tiếp theo", "explain": "てから nhấn mạnh trình tự: việc thứ nhất PHẢI hoàn thành rồi mới sang việc thứ hai. Khác với nối câu bằng て thường, てから mang sắc thái “xong xuôi hẳn rồi mới…”.", "examples": [{"jp": "手（て）を 洗（あら）ってから、ごはんを 食（た）べます。", "vi": "Sau khi rửa tay xong, tôi ăn cơm."}, {"jp": "シャワーを 浴（あ）びてから、寝（ね）ます。", "vi": "Sau khi tắm xong, tôi đi ngủ."}]}]}, "15": {"title": "Bài 15 — Minna no Nihongo", "intro": "Bài 15 dạy xin phép và cấm đoán bằng thể て, cộng thêm nghĩa “trạng thái/nghề nghiệp” rất quan trọng của ています.", "points": [{"pattern": "Vて も いいです", "meaning": "được phép làm V / làm V cũng được", "form": "Động từ thể て + も + いいです ; hỏi: Vて も いいですか", "explain": "Muốn xin phép, dùng thể て + も いいですか. Người cho phép trả lời いいですよ / どうぞ. Đây là cách hỏi xin phép chuẩn mực trong lớp học, công ty, nơi công cộng.", "examples": [{"jp": "写真（しゃしん）を 撮（と）っても いいですか。— はい、いいですよ。", "vi": "Tôi chụp ảnh có được không? — Vâng, được ạ."}, {"jp": "ここで たばこを 吸（す）っても いいですか。", "vi": "Tôi hút thuốc ở đây có được không?"}]}, {"pattern": "Vて は いけません", "meaning": "không được làm V (cấm)", "form": "Động từ thể て + は (wa) + いけません", "explain": "Đây là mẫu cấm đoán chính thức, hay thấy trên biển báo và nội quy. Trong văn nói thân mật, người Nhật rút gọn thành ちゃ ダメ (với ては→ちゃ, では→じゃ).", "examples": [{"jp": "ここで 写真（しゃしん）を 撮（と）っては いけません。", "vi": "Ở đây không được chụp ảnh."}, {"jp": "病院（びょういん）で 大（おお）きい 声（こえ）で 話（はな）しては いけません。", "vi": "Trong bệnh viện không được nói to."}], "note": "Khi muốn từ chối lời xin phép một cách khéo léo, người Nhật nói: すみません、ちょっと… (xin lỗi, hơi…) thay vì nói thẳng “không được”."}, {"pattern": "Vて います (trạng thái – nghề nghiệp)", "meaning": "đang ở trạng thái… / làm nghề… / sống ở…", "form": "Động từ thể て + います với các động từ 住む・知る・働く・結婚する…", "explain": "Với các động từ chỉ trạng thái kéo dài, ています KHÔNG có nghĩa “đang” mà chỉ tình trạng hiện tại: 住んでいます = đang sống ở, 知っています = biết, 結婚しています = đã kết hôn (đang có gia đình), 持っています = đang có/mang theo.", "examples": [{"jp": "わたしは 大阪（おおさか）に 住（す）んで います。", "vi": "Tôi sống ở Osaka."}, {"jp": "山田（やまだ）さんは 結婚（けっこん）して います。", "vi": "Anh Yamada đã kết hôn rồi."}], "note": "知る là ngoại lệ đặc biệt: “không biết” nói 知りません, không nói 知っていません."}]}, "16": {"title": "Bài 16 — Minna no Nihongo", "intro": "Bài 16 dạy nối nhiều hành động và nhiều tính từ trong một câu, cộng mẫu miêu tả “ai đó có bộ phận/lĩnh vực nào đó như thế nào”.", "points": [{"pattern": "Vて、Vて、～", "meaning": "làm V1, rồi V2, rồi… (liệt kê trình tự)", "form": "Động từ thể て + 、+ Động từ thể て + 、+ Động từ cuối chia thì", "explain": "Chỉ động từ CUỐI CÙNG của chuỗi mới mang thì (quá khứ/hiện tại) — thì của nó áp dụng cho toàn bộ chuỗi hành động. Đây là cách kể lại một ngày, một quy trình làm việc một cách gọn gàng.", "examples": [{"jp": "朝（あさ） 起（お）きて、顔（かお）を 洗（あら）って、ごはんを 食（た）べます。", "vi": "Buổi sáng tôi thức dậy, rửa mặt, rồi ăn cơm."}, {"jp": "きのう デパートへ 行（い）って、買（か）い物（もの）を して、映画（えいが）を 見（み）ました。", "vi": "Hôm qua tôi đi trung tâm thương mại, mua sắm, rồi xem phim."}]}, {"pattern": "い形 ～くて / な形・N ～で", "meaning": "…và… (nối tính từ, danh từ)", "form": "い形 bỏ い + くて ; な形・Danh từ + で", "explain": "Để nối hai tính từ miêu tả cùng một chủ thể: tính từ -i dùng くて, tính từ -na và danh từ dùng で. Vế cuối cùng mới là tính từ/danh từ hoàn chỉnh kết thúc câu.", "examples": [{"jp": "この 部屋（へや）は 広（ひろ）くて、明（あか）るいです。", "vi": "Căn phòng này rộng và sáng."}, {"jp": "あの 人（ひと）は 親切（しんせつ）で、元気（げんき）です。", "vi": "Người kia thân thiện và khỏe mạnh."}]}, {"pattern": "N1 は N2 が 形容詞です", "meaning": "N1 thì (phần) N2 (như thế nào)", "form": "Chủ thể lớn + は + Bộ phận/Lĩnh vực + が + Tính từ", "explain": "Mẫu miêu tả đặc trưng của tiếng Nhật: nêu chủ thể tổng thể bằng は, rồi nêu bộ phận hoặc khía cạnh cụ thể bằng が kèm tính từ — tóc dài, giọng hay, chữ đẹp…", "examples": [{"jp": "彼女（かのじょ）は 髪（かみ）が 長（なが）いです。", "vi": "Cô ấy có mái tóc dài."}, {"jp": "この 町（まち）は 食（た）べ物（もの）が おいしいです。", "vi": "Thành phố này có đồ ăn ngon."}]}, {"pattern": "どう やって", "meaning": "bằng cách nào / đi như thế nào (hỏi trình tự, phương tiện chi tiết)", "form": "どう やって + Vますか", "explain": "どう やって hỏi về trình tự các bước hoặc cách thức cụ thể, chi tiết hơn 何で (bằng phương tiện gì) của Bài 5. Câu trả lời thường là một chuỗi thể て liệt kê các bước.", "examples": [{"jp": "大学（だいがく）まで どう やって 行（い）きますか。", "vi": "Bạn đi đến trường đại học bằng cách nào?"}, {"jp": "この 機械（きかい）の 使（つか）い方（かた）を 教（おし）えて ください。", "vi": "Hãy dạy tôi cách dùng cái máy này."}]}]}, "17": {"title": "Bài 17 — Minna no Nihongo", "intro": "Bài 17 giới thiệu thể ない — thể phủ định gốc của động từ, làm nền cho ba mẫu cực kỳ thực dụng: xin đừng làm, bắt buộc phải làm, và không cần làm.", "points": [{"pattern": "Động từ thể ない (ない形)", "meaning": "thể phủ định gốc của động từ", "form": "Nhóm 1: hàng あ + ない (書く→書かない) ; Nhóm 2: bỏ る + ない ; Nhóm 3: しない・こない ; đặc biệt ある→ない", "explain": "Thể ない là gốc phủ định dùng để tạo nhiều mẫu câu khác, bản thân nó là cách nói phủ định thân mật. Chú ý nhóm 1 tận cùng bằng う thì thành わない (買う→買わない), và ある phủ định là ない chứ không phải あらない.", "examples": [{"jp": "今日（きょう）は 学校（がっこう）へ 行（い）かない。", "vi": "Hôm nay tôi không đi học."}, {"jp": "お金（かね）が ない。", "vi": "Tôi không có tiền."}]}, {"pattern": "Vないで ください", "meaning": "Xin đừng làm V", "form": "Động từ thể ない + で + ください", "explain": "Đây là lời yêu cầu phủ định lịch sự, cặp đối ngược với Vて ください. Dùng khi nhắc nhở nhẹ nhàng: đừng hút thuốc, đừng quên, đừng lo lắng…", "examples": [{"jp": "ここで たばこを 吸（す）わないで ください。", "vi": "Xin đừng hút thuốc ở đây."}, {"jp": "心配（しんぱい）しないで ください。", "vi": "Xin đừng lo lắng."}]}, {"pattern": "Vなければ なりません", "meaning": "phải làm V (bắt buộc)", "form": "Động từ thể ない bỏ い + ければ なりません", "explain": "なければ なりません diễn tả nghĩa vụ bắt buộc khách quan: luật lệ, công việc, sức khỏe yêu cầu. Trong văn nói hằng ngày người Nhật rút gọn thành なきゃ / ないと.", "examples": [{"jp": "明日（あした） 早（はや）く 起（お）きなければ なりません。", "vi": "Ngày mai tôi phải dậy sớm."}, {"jp": "薬（くすり）を 飲（の）まなければ なりません。", "vi": "Tôi phải uống thuốc."}]}, {"pattern": "Vなくても いいです", "meaning": "không làm V cũng được / không cần làm V", "form": "Động từ thể ない bỏ い + くても いいです", "explain": "Mẫu này gỡ bỏ nghĩa vụ: việc đó không bắt buộc. Là câu trả lời chuẩn khi ai đó hỏi “…しなければ なりませんか” (có phải làm… không ạ?).", "examples": [{"jp": "明日（あした） 来（こ）なくても いいです。", "vi": "Ngày mai bạn không đến cũng được."}, {"jp": "靴（くつ）を 脱（ぬ）がなくても いいです。", "vi": "Bạn không cần cởi giày đâu."}]}, {"pattern": "N (thời hạn) までに", "meaning": "trước (thời hạn)…", "form": "Thời điểm + までに + Động từ", "explain": "までに chỉ mốc chót: hành động phải hoàn thành TRƯỚC thời điểm đó. Phân biệt với まで (đến tận — hành động kéo dài liên tục tới mốc): レポートは 金曜日までに 出します (nộp trước thứ Sáu) khác hẳn 金曜日まで 働きます (làm việc đến tận thứ Sáu).", "examples": [{"jp": "宿題（しゅくだい）は 月曜日（げつようび）までに 出（だ）して ください。", "vi": "Hãy nộp bài tập trước thứ Hai."}, {"jp": "10（じゅう）時（じ）までに 帰（かえ）ります。", "vi": "Tôi sẽ về trước 10 giờ."}]}]}, "18": {"title": "Bài 18 — Minna no Nihongo", "intro": "Bài 18 giới thiệu thể từ điển (辞書形) — dạng gốc tra từ điển của động từ, dùng để nói về khả năng, sở thích và việc “trước khi làm…”.", "points": [{"pattern": "Động từ thể từ điển (辞書形)", "meaning": "dạng gốc của động từ", "form": "Nhóm 1: dạng nguyên mẫu hàng う ; Nhóm 2: bỏ ます thêm る ; Nhóm 3: する・くる", "explain": "Thể từ điển là hình dạng của động từ khi tra từ điển, cũng là nền của thể thường sẽ học ở Bài 20. Nhận biết nhóm động từ qua thể từ điển là kỹ năng nền của mọi biến đổi sau này.", "examples": [{"jp": "辞書（じしょ）で 言葉（ことば）を 調（しら）べます。", "vi": "Tôi tra từ bằng từ điển."}, {"jp": "彼（かれ）は 速（はや）く 走（はし）ることが できます。", "vi": "Anh ấy có thể chạy nhanh."}]}, {"pattern": "Vる ことが できます", "meaning": "có thể làm V (năng lực / điều kiện cho phép)", "form": "Động từ thể từ điển + こと が できます", "explain": "ことができます diễn tả khả năng khách quan: biết làm (có kỹ năng) hoặc điều kiện cho phép làm. Đối tượng của động từ vẫn giữ nguyên trợ từ を. Mẫu này lịch sự và rõ ràng, rất hợp văn viết và công sở.", "examples": [{"jp": "彼女（かのじょ）は ピアノを 弾（ひ）くことが できます。", "vi": "Cô ấy có thể chơi đàn piano."}, {"jp": "ここで 写真（しゃしん）を 撮（と）ることが できます。", "vi": "Ở đây có thể chụp ảnh."}], "note": "Ở cấp N4 sẽ học thể khả năng ngắn gọn (話せます) mang sắc thái tương tự — Bài 27."}, {"pattern": "趣味（しゅみ）は Vる ことです", "meaning": "sở thích là (việc) làm V", "form": "Động từ thể từ điển + こと + です", "explain": "こと biến một động từ thành một “việc/danh từ” — gọi là danh từ hóa. Nhờ đó ta nói được sở thích, kế hoạch, quyết định… như một danh từ bình thường.", "examples": [{"jp": "わたしの 趣味（しゅみ）は 映画（えいが）を 見（み）ることです。", "vi": "Sở thích của tôi là xem phim."}, {"jp": "趣味（しゅみ）は 音楽（おんがく）を 聞（き）くことです。", "vi": "Sở thích của tôi là nghe nhạc."}]}, {"pattern": "Vる / N の 前（まえ）に", "meaning": "trước khi làm V / trước N", "form": "Động từ thể từ điển + 前に ; Danh từ + の + 前に", "explain": "前に chỉ mốc “trước”: động từ đi trước 前に LUÔN ở thể từ điển (dạng chưa xảy ra) dù cả câu ở thì quá khứ — vì tại thời điểm đó hành động chưa diễn ra. Đây là điểm ngữ pháp rất hay bị sai.", "examples": [{"jp": "寝（ね）る 前（まえ）に、歯（は）を 磨（みが）きます。", "vi": "Trước khi ngủ, tôi đánh răng."}, {"jp": "ごはんの 前（まえ）に、手（て）を 洗（あら）います。", "vi": "Trước bữa ăn, tôi rửa tay."}], "note": "×寝た前に là sai. Dù câu chính ở quá khứ, phần trước 前に vẫn giữ 寝る."}]}, "19": {"title": "Bài 19 — Minna no Nihongo", "intro": "Bài 19 giới thiệu thể た (quá khứ gốc) để kể trải nghiệm “đã từng”, và mẫu ～たり～たり liệt kê hành động tiêu biểu.", "points": [{"pattern": "Động từ thể た (た形)", "meaning": "thể quá khứ gốc của động từ", "form": "Chia giống hệ thể て nhưng thay て→た, で→だ (書いて→書いた, 読んで→読んだ)", "explain": "Tin vui: thể た chia Y HỆT thể て, chỉ đổi âm cuối. Ai đã thuộc thể て ở Bài 14 thì coi như đã thuộc thể た. Thể た là gốc của các mẫu: đã từng, nếu…, và văn phong thân mật quá khứ.", "examples": [{"jp": "映画（えいが）を 見（み）たことが あります。", "vi": "Tôi đã từng xem bộ phim (đó)."}, {"jp": "日本（にほん）へ 行（い）ったことが あります。", "vi": "Tôi đã từng đi Nhật."}]}, {"pattern": "Vた ことが あります", "meaning": "đã từng làm V", "form": "Động từ thể た + こと が あります ; phủ định: ～た ことが ありません", "explain": "ことが あります sau thể た diễn tả KINH NGHIỆM trong quá khứ — việc đã xảy ra ít nhất một lần tính đến hiện tại. Khác với quá khứ thường (～ました chỉ kể một sự kiện cụ thể có thời điểm).", "examples": [{"jp": "馬（うま）に 乗（の）ったことが あります。", "vi": "Tôi đã từng cưỡi ngựa."}, {"jp": "すしを 食（た）べたことが ありません。", "vi": "Tôi chưa từng ăn sushi."}], "note": "Hỏi kinh nghiệm lịch sự: ～たことが ありますか → trả lời はい、あります hoặc いいえ、一度も ありません (chưa lần nào)."}, {"pattern": "Vたり、Vたり します", "meaning": "làm V này, làm V kia… (liệt kê tiêu biểu)", "form": "Động từ thể た + り 、 Động từ thể た + り + します", "explain": "たり liệt kê một VÀI hành động tiêu biểu trong số nhiều hành động — hàm ý “vân vân, các thứ”. Động từ kết thúc chuỗi luôn là します và mang thì cho cả câu. たり cũng dùng được cho tính từ (高かったり 安かったり).", "examples": [{"jp": "日曜日（にちようび）は 掃除（そうじ）したり、洗濯（せんたく）したり します。", "vi": "Chủ nhật tôi (làm các việc như) dọn dẹp, giặt giũ."}, {"jp": "休（やす）みの 日（ひ）は 本（ほん）を 読（よ）んだり、映画（えいが）を 見（み）たり します。", "vi": "Ngày nghỉ tôi đọc sách, xem phim (vân vân)."}]}]}, "20": {"title": "Bài 20 — Minna no Nihongo", "intro": "Bài 20 tập hợp mọi dạng đã học thành thể thường (普通形) — văn phong thân mật dùng với bạn bè, người nhà, và là nền cho ngữ pháp trung cấp.", "points": [{"pattern": "Thể thường (普通形) — Động từ", "meaning": "dạng thân mật của động từ: る / ない / た / なかった", "form": "Khẳng định hiện tại = thể từ điển ; phủ định = thể ない ; quá khứ = thể た ; phủ định quá khứ = thể ない bỏ い + かった", "explain": "Thể thường là hệ thống song song với thể lịch sự: 行く (đi), 行かない (không đi), 行った (đã đi), 行かなかった (đã không đi). Bốn ô này phải thuộc nằm lòng vì từ Bài 21 trở đi, mọi mẫu câu mới đều gắn vào thể thường.", "examples": [{"jp": "明日（あした）も 仕事（しごと）が ある。", "vi": "Ngày mai tôi cũng có việc."}, {"jp": "きのうは 早（はや）く 寝（ね）なかった。", "vi": "Hôm qua tôi đã không ngủ sớm."}]}, {"pattern": "Thể thường — Tính từ & Danh từ", "meaning": "dạng thân mật của tính từ, danh từ: だ / じゃない / だった", "form": "い形: giữ nguyên ; な形 & N: + だ / じゃない / だった / じゃなかった (bỏ な khi + だ)", "explain": "Tính từ -i giữ nguyên các dạng đã học, chỉ bỏ です. Tính từ -na và danh từ dùng だ thay です ở khẳng định hiện tại. Trong văn nói, だ thường bị lược bỏ sau tính từ -na khi đứng cuối câu.", "examples": [{"jp": "この 本（ほん）、高（たか）い？ — うん、とても 高（たか）い。", "vi": "Cuốn sách này đắt à? — Ừ, rất đắt."}, {"jp": "明日（あした）は 休（やす）みだ。", "vi": "Ngày mai là ngày nghỉ."}], "note": "Câu hỏi thân mật thường bỏ か và lên giọng ở cuối câu: 行く？ 元気？"}, {"pattern": "Văn phong thân mật trong hội thoại", "meaning": "nói chuyện suồng sã với bạn bè, người thân", "form": "Dùng thể thường + trợ từ cuối câu ね・よ・な", "explain": "Khi đã thân thiết, người Nhật chuyển hẳn sang thể thường: bỏ です/ます, hay thêm ね (nhỉ), よ (đấy/nhé). Dùng nhầm thể thường với cấp trên/người mới quen là lỗi xã giao nghiêm trọng — ranh giới này rất quan trọng.", "examples": [{"jp": "もう ごはん 食（た）べた？ — うん、食（た）べた。", "vi": "Cậu ăn cơm chưa? — Ừ, ăn rồi."}, {"jp": "明日（あした） 会（あ）おうよ。", "vi": "Ngày mai gặp nhau nhé."}]}, {"pattern": "～けど", "meaning": "…nhưng… (thân mật của ～が、～)", "form": "Thể thường + けど", "explain": "けど là dạng thân mật của が nối tương phản/mở đầu, dùng trong văn nói thường ngày. Nó cũng hay đứng cuối câu bỏ lửng để nói giảm nói tránh: 行きたいけど… (tôi muốn đi nhưng mà…).", "examples": [{"jp": "この 店（みせ）、安（やす）いけど あまり おいしくない。", "vi": "Quán này rẻ nhưng không ngon lắm."}, {"jp": "日本語（にほんご）は 難（むずか）しいけど、おもしろい。", "vi": "Tiếng Nhật khó nhưng thú vị."}]}]}, "21": {"title": "Bài 21 — Minna no Nihongo", "intro": "Bài 21 dạy trích dẫn suy nghĩ và lời nói bằng thể thường + と, cùng mẫu dự đoán ～でしょう.", "points": [{"pattern": "普通形（ふつうけい） + と 思（おも）います", "meaning": "tôi nghĩ rằng…", "form": "Câu thể thường + と + 思います ; phủ định ý kiến: ～ないと 思います", "explain": "と ở đây là trợ từ TRÍCH DẪN: toàn bộ câu thể thường đứng trước と được đóng gói thành nội dung suy nghĩ. Khi muốn nói “tôi nghĩ là KHÔNG…”, phủ định nằm BÊN TRONG phần trích dẫn: 明日は 雨が 降らないと 思います.", "examples": [{"jp": "明日（あした）は 雨（あめ）が 降（ふ）ると 思（おも）います。", "vi": "Tôi nghĩ ngày mai trời sẽ mưa."}, {"jp": "この 仕事（しごと）は 大変（たいへん）だと 思（おも）います。", "vi": "Tôi nghĩ công việc này vất vả."}], "note": "Danh từ và tính từ -na trước と思います phải có だ: 元気だと 思います. Tính từ -i thì giữ nguyên: 高いと 思います."}, {"pattern": "普通形 + と 言（い）います", "meaning": "(ai đó) nói rằng…", "form": "Câu thể thường + と + 言います / 言いました", "explain": "Cùng cơ chế trích dẫn với と思います nhưng dùng để thuật lại lời nói của người khác. Có thể kèm người nói + は hoặc người nghe + に: 先生は 明日 試験が あると 言いました.", "examples": [{"jp": "田中（たなか）さんは 来週（らいしゅう） 出張（しゅっちょう）すると 言（い）いました。", "vi": "Anh Tanaka nói rằng tuần sau anh ấy đi công tác."}, {"jp": "彼女（かのじょ）は 元気（げんき）だと 言（い）いました。", "vi": "Cô ấy nói rằng cô ấy khỏe."}]}, {"pattern": "～でしょう", "meaning": "chắc là… / có lẽ… (dự đoán chắc chắn khá cao)", "form": "Thể thường (bỏ だ với N・な形) + でしょう", "explain": "でしょう diễn tả dự đoán với độ tin cậy khá cao dựa trên căn cứ, lịch sự hơn だろう (thể thường của nó). Thêm か thành でしょうか là câu hỏi thăm dò rất lịch sự, hay dùng khi hỏi điều chưa chắc chắn.", "examples": [{"jp": "明日（あした）は 晴（は）れるでしょう。", "vi": "Ngày mai chắc trời sẽ nắng."}, {"jp": "あの 人（ひと）は だれでしょうか。", "vi": "Người kia là ai nhỉ (không biết là ai)?"}]}]}, "22": {"title": "Bài 22 — Minna no Nihongo", "intro": "Bài 22 dạy mệnh đề quan hệ: dùng thể thường đứng trước danh từ để miêu tả “cái/người mà…”, khả năng cực kỳ quan trọng trong tiếng Nhật.", "points": [{"pattern": "普通形 + 名詞 (mệnh đề định ngữ)", "meaning": "danh từ được bổ nghĩa bởi cả một mệnh đề: “cái … mà …”", "form": "Câu thể thường + Danh từ (mệnh đề luôn đứng TRƯỚC danh từ)", "explain": "Tiếng Nhật đặt mệnh đề miêu tả TRƯỚC danh từ — ngược hẳn tiếng Việt: 昨日買った本 = cuốn sách (mà) hôm qua tôi đã mua. Trong mệnh đề, chủ ngữ dùng が chứ không dùng は. Đây là mẫu câu xuất hiện trong mọi văn bản từ đây về sau.", "examples": [{"jp": "これは 昨日（きのう） 買（か）った 本（ほん）です。", "vi": "Đây là cuốn sách tôi mua hôm qua."}, {"jp": "あそこで 話（はな）している 人（ひと）は 山田（やまだ）さんです。", "vi": "Người đang nói chuyện ở đằng kia là anh Yamada."}], "note": "Trợ từ của danh từ chính nằm SAU danh từ: [友達が 作った] ケーキを 食べました — を thuộc về ケーキ, không thuộc về mệnh đề."}, {"pattern": "Vる 時間（じかん）/ 約束（やくそく）/ 用事（ようじ）", "meaning": "thời gian để làm V / lời hứa làm V / việc cần làm V", "form": "Động từ thể từ điển + 時間・約束・用事…", "explain": "Khi danh từ đứng sau là 時間, 約束, 用事, mệnh đề định ngữ mang nghĩa mục đích/nội dung cụ thể của danh từ đó. Mẫu này là ứng dụng trực tiếp của mệnh đề quan hệ vào đời sống.", "examples": [{"jp": "わたしは 本（ほん）を 読（よ）む 時間（じかん）が ありません。", "vi": "Tôi không có thời gian để đọc sách."}, {"jp": "友達（ともだち）と 映画（えいが）を 見（み）る 約束（やくそく）が あります。", "vi": "Tôi có hẹn (lời hứa) xem phim với bạn."}]}]}, "23": {"title": "Bài 23 — Minna no Nihongo", "intro": "Bài 23 dạy hai mẫu “khi” quan trọng: ～とき (thời điểm) và ～と (khi làm thì sẽ xảy ra kết quả tất yếu).", "points": [{"pattern": "Vる とき / Vた とき", "meaning": "khi làm V / khi đã làm V xong", "form": "Động từ thể từ điển + とき (hành động chưa xong tại thời điểm đó) ; Động từ thể た + とき (hành động đã hoàn thành)", "explain": "とき biến cả cụm động từ thành mốc thời gian. Khác biệt tinh tế nhưng thi JLPT rất hay hỏi: Vる とき = khi (đang/trước lúc) làm — việc chưa hoàn thành; Vた とき = khi đã làm xong — việc đã hoàn thành. Tính từ và danh từ cũng dùng được: 忙しいとき, 学生のとき.", "examples": [{"jp": "辞書（じしょ）は 言葉（ことば）の 意味（いみ）が わからないとき 使（つか）います。", "vi": "Từ điển thì dùng khi không hiểu nghĩa của từ."}, {"jp": "日本（にほん）へ 行（い）ったとき、カメラを 買（か）いました。", "vi": "Khi (đã) đến Nhật, tôi đã mua máy ảnh."}], "note": "Đi đến nơi dùng 行ったとき (đã tới), lúc đang trên đường đi dùng 行くとき. Phân biệt bằng câu hỏi: việc chính xảy ra trước hay sau khi V hoàn tất?"}, {"pattern": "Vる と、～", "meaning": "cứ làm V thì (tất yếu) sẽ…", "form": "Động từ thể từ điển + と + kết quả tất yếu/quy luật", "explain": "と ở đây là điều kiện TỰ NHIÊN: vế sau là kết quả luôn luôn xảy ra, thường là chỉ đường, hướng dẫn máy móc, quy luật. Vế sau KHÔNG được là ý chí, mệnh lệnh, mong muốn của người nói.", "examples": [{"jp": "この ボタンを 押（お）すと、ドアが 開（あ）きます。", "vi": "Ấn nút này thì cửa sẽ mở."}, {"jp": "まっすぐ 行（い）くと、右（みぎ）に 駅（えき）が あります。", "vi": "Đi thẳng thì ga ở phía bên phải."}], "note": "Không dùng と cho việc một lần cụ thể trong quá khứ — trường hợp đó dùng たら (Bài 25)."}, {"pattern": "N を 移動（いどう）する 動詞", "meaning": "đi qua/vượt qua N (đường, cầu, ngã tư…)", "form": "Danh từ chỉ tuyến đường/nơi đi qua + を + 渡ります・曲がります・通ります…", "explain": "Với các động từ di chuyển qua một không gian, nơi đi qua được đánh dấu bằng を chứ không phải に/へ: 道を 渡る (qua đường), 橋を 渡る (qua cầu), 角を 曲がる (rẽ ở góc đường).", "examples": [{"jp": "信号（しんごう）を 右（みぎ）へ 曲（ま）がって ください。", "vi": "Hãy rẽ phải ở đèn tín hiệu."}, {"jp": "この 道（みち）を まっすぐ 行（い）くと、橋（はし）を 渡（わた）ります。", "vi": "Đi thẳng đường này thì sẽ qua cầu."}]}]}, "24": {"title": "Bài 24 — Minna no Nihongo", "intro": "Bài 24 mở rộng cho – nhận từ đồ vật (Bài 7) sang cho – nhận HÀNH ĐỘNG: ai làm việc gì cho ai, ai được ai làm giúp việc gì.", "points": [{"pattern": "Vて あげます", "meaning": "(tôi/người khác) làm V cho (người kia)", "form": "Động từ thể て + あげます ; người nhận + に", "explain": "てあげます gắn hành động vào nghĩa “làm hộ, làm cho” — chủ ngữ là người làm giúp. Với cấp trên hoặc người mới quen, あげます dễ bị nghe thành “ban ơn” nên người Nhật thường tránh dùng trực tiếp.", "examples": [{"jp": "わたしは 友達（ともだち）に 日本語（にほんご）を 教（おし）えて あげました。", "vi": "Tôi đã dạy tiếng Nhật cho bạn."}, {"jp": "母（はは）は 子どもに 本（ほん）を 読（よ）んで あげます。", "vi": "Mẹ đọc sách cho con nghe."}]}, {"pattern": "Vて もらいます", "meaning": "(tôi) được (ai) làm V cho", "form": "Người làm giúp + に + Động từ thể て + もらいます", "explain": "てもらいます nhìn từ phía người ĐƯỢC giúp — luôn hàm ý biết ơn, là mẫu nhờ vả trang trọng hơn てください. Người làm giúp đánh dấu bằng に. Mẫu này cực kỳ quan trọng trong công việc.", "examples": [{"jp": "わたしは 先生（せんせい）に 手紙（てがみ）を 直（なお）して もらいました。", "vi": "Tôi được thầy sửa thư cho."}, {"jp": "友達（ともだち）に 引（ひ）っ越（こ）しを 手伝（てつだ）って もらいました。", "vi": "Tôi được bạn giúp chuyển nhà."}]}, {"pattern": "Vて くれます", "meaning": "(ai đó) làm V cho (tôi/người nhà tôi)", "form": "Người làm giúp + は/が + Động từ thể て + くれます", "explain": "てくれます dùng khi người khác chủ động làm điều tốt cho mình — người nói là bên hưởng lợi. Đây là mẫu diễn tả lòng biết ơn tự nhiên nhất: 友達が 来てくれた = bạn đã (tốt bụng) đến với tôi.", "examples": [{"jp": "彼女（かのじょ）は 駅（えき）まで 送（おく）って くれました。", "vi": "Cô ấy đã tiễn tôi ra ga."}, {"jp": "先生（せんせい）が 説明（せつめい）して くれました。", "vi": "Thầy đã giải thích cho tôi."}], "note": "Ba mẫu あげる・もらう・くれる khác nhau ở GÓC NHÌN: ai là trung tâm của câu. Nắm chắc ai cho – ai nhận là nắm chắc cả bài."}]}, "25": {"title": "Bài 25 — Minna no Nihongo", "intro": "Bài cuối của N5 dạy điều kiện: nếu… thì… (～たら) và dù… cũng… (～ても) — hai mẫu kết nối mọi kiến thức đã học.", "points": [{"pattern": "Vた ら / 普通形 + ら", "meaning": "nếu… thì… / sau khi… thì…", "form": "Động từ thể た + ら ; い形 ～かったら ; な形・N + だったら", "explain": "たら là mẫu điều kiện linh hoạt nhất: dùng cho giả định tương lai (nếu trời mưa), trình tự chắc chắn (về đến nhà thì…), và cả lời khuyên, đề xuất ở vế sau. Vế sau たら ĐƯỢC PHÉP là ý chí/mệnh lệnh — điểm khác biệt lớn với と ở Bài 23.", "examples": [{"jp": "雨（あめ）が 降（ふ）ったら、出（で）かけません。", "vi": "Nếu trời mưa thì tôi không ra ngoài."}, {"jp": "家（いえ）へ 帰（かえ）ったら、すぐ シャワーを 浴（あ）びます。", "vi": "Về đến nhà thì tôi tắm ngay."}], "note": "たら hình thành từ thể た + ら nên dù nói về tương lai vẫn dùng dạng “quá khứ” này — đừng dịch máy móc thành thì quá khứ."}, {"pattern": "Vて も", "meaning": "dù có làm V cũng… / cho dù…", "form": "Động từ thể て + も ; い形 ～くても ; な形・N + でも", "explain": "ても diễn tả nhượng bộ: điều kiện ở vế trước dù xảy ra cũng không thay đổi kết quả ở vế sau. Cặp với ても thường là kết quả phủ định hoặc trái kỳ vọng.", "examples": [{"jp": "雨（あめ）が 降（ふ）っても、行（い）きます。", "vi": "Dù trời mưa, tôi vẫn đi."}, {"jp": "安（やす）くても、買（か）いません。", "vi": "Dù rẻ, tôi cũng không mua."}]}, {"pattern": "もし", "meaning": "giả sử / nếu như (nhấn mạnh điều kiện)", "form": "もし + câu điều kiện (～たら、～ても…)", "explain": "もし đặt ở đầu câu để báo hiệu đây là tình huống giả định, giúp người nghe định hướng ngay. もし hầu như luôn đi cặp với たら ở giữa câu.", "examples": [{"jp": "もし 100万（ひゃくまん）円（えん）が あったら、何（なに）を しますか。", "vi": "Nếu có 1 triệu yên, bạn sẽ làm gì?"}, {"jp": "もし 時間（じかん）が なかったら、来（こ）なくても いいです。", "vi": "Nếu không có thời gian thì bạn không cần đến cũng được."}]}, {"pattern": "いくら ～ても", "meaning": "dù … đến mức nào cũng…", "form": "いくら + thể て + も (thường đi với kết quả phủ định)", "explain": "いくら tăng cấp cho ても: nhấn mạnh mức độ cực đoan của điều kiện mà kết quả vẫn không đổi. Mẫu này hay xuất hiện trong than phiền và quyết tâm.", "examples": [{"jp": "いくら 考（かんが）えても、わかりません。", "vi": "Dù suy nghĩ thế nào tôi cũng không hiểu."}, {"jp": "いくら 高（たか）くても、この 車（くるま）を 買（か）いたいです。", "vi": "Dù đắt thế nào tôi cũng muốn mua chiếc xe này."}]}]}}, "N4": {"1": {"title": "Bài 26 — Minna no Nihongo", "intro": "Bài mở đầu N4 với ～んです — mẫu câu giải thích tình huống, hỏi lý do và mở đầu lời nhờ vả, xuất hiện trong hầu hết hội thoại thực tế.", "points": [{"pattern": "普通形 + んです", "meaning": "thật ra là… / là vì… (giải thích, nhấn mạnh tình huống)", "form": "Động từ・い形 + んです ; な形・N + なんです", "explain": "んです gắn sau thể thường để biến câu thành lời GIẢI THÍCH: người nói cảm thấy cần nói rõ hoàn cảnh, lý do ẩn sau sự việc. Câu hỏi ～んですか dùng khi ta đã thấy một dấu hiệu gì đó và muốn hỏi rõ nguyên do — sắc thái quan tâm, khác hẳn câu hỏi trần trụi.", "examples": [{"jp": "頭（あたま）が 痛（いた）いんです。", "vi": "Thật ra tôi bị đau đầu (nên xin nghỉ sớm)."}, {"jp": "どうして 遅（おく）れたんですか。— バスが 来（こ）なかったんです。", "vi": "Sao bạn đến muộn vậy? — Là vì xe buýt không đến."}], "note": "な形 và danh từ phải chèn な: 静か + なんです (không phải 静かんです). Dạng thân mật là んだ, câu hỏi thân mật là の？."}, {"pattern": "～んですが、～", "meaning": "…là thế này ạ, (nên tôi muốn nhờ…) — mở đầu mềm mỏng", "form": "Câu giải thích + んですが、+ lời nhờ vả / câu hỏi", "explain": "Khi cần nhờ vả hoặc hỏi đường, người Nhật luôn “đệm” một câu んですが để giới thiệu hoàn cảnh trước khi vào việc chính. Thiếu câu đệm này, lời nhờ vả nghe sẽ đường đột.", "examples": [{"jp": "すみません、駅（えき）へ 行（い）きたいんですが、どう 行（い）ったら いいですか。", "vi": "Xin lỗi, tôi muốn đi ra ga, vậy phải đi thế nào ạ?"}, {"jp": "頭（あたま）が 痛（いた）いんですが、早（はや）く 帰（かえ）っても いいですか。", "vi": "Tôi bị đau đầu, tôi về sớm có được không ạ?"}]}, {"pattern": "Vて くださいませんか", "meaning": "Anh/chị có thể làm V giúp tôi được không? (nhờ vả rất lịch sự)", "form": "Động từ thể て + くださいませんか", "explain": "くださいませんか là phiên bản lịch sự hơn hẳn của てください, dùng với cấp trên, khách hàng, người lạ. Nguyên tắc chung: càng “vòng vo phủ định” thì càng lịch sự trong tiếng Nhật.", "examples": [{"jp": "この 書類（しょるい）を コピーして くださいませんか。", "vi": "Anh có thể photo tài liệu này giúp tôi được không?"}, {"jp": "すみません、ちょっと 手伝（てつだ）って くださいませんか。", "vi": "Xin lỗi, anh có thể giúp tôi một chút được không?"}]}, {"pattern": "Vたら いいですか", "meaning": "tôi nên làm V thế nào / làm thế nào thì tốt?", "form": "Động từ thể た + ら + いいですか", "explain": "Khi bí cách làm một việc, hỏi ～たら いいですか để xin chỉ dẫn: “tôi phải làm sao thì được”. Người trả lời thường đáp bằng ～ば いいです hoặc ～たら いいですよ.", "examples": [{"jp": "パスワードを 忘（わす）れたんですが、どうしたら いいですか。", "vi": "Tôi quên mật khẩu, vậy phải làm thế nào ạ?"}, {"jp": "この 機械（きかい）は どう 使（つか）ったら いいですか。", "vi": "Cái máy này dùng như thế nào vậy ạ?"}]}]}, "2": {"title": "Bài 27 — Minna no Nihongo", "intro": "Bài 27 dạy thể khả năng: nói “làm được / không làm được” gọn trong một động từ, cùng mẫu giới hạn ～しか～ません.", "points": [{"pattern": "Động từ thể khả năng (可能形)", "meaning": "có thể làm V", "form": "Nhóm 1: hàng え + る (書く→書ける) ; Nhóm 2: bỏ る + られる ; Nhóm 3: できる・こられる ; tân ngữ を → が", "explain": "Thể khả năng biến động từ thành dạng “làm được”. Sau khi chuyển sang khả năng, tân ngữ thường đổi trợ từ を thành が. Nhóm 2 rút gọn られる thành れる trong văn nói (食べれる) nhưng văn chuẩn và thi cử vẫn yêu cầu られる.", "examples": [{"jp": "わたしは 日本語（にほんご）が 少（すこ）し 話（はな）せます。", "vi": "Tôi có thể nói tiếng Nhật một chút."}, {"jp": "彼女（かのじょ）は 一人（ひとり）で 着物（きもの）が 着（き）られます。", "vi": "Cô ấy có thể tự mặc kimono một mình."}], "note": "漢字 (かんじ) が 読めます chứ không dùng を trong văn chuẩn. Động từ できる là thể khả năng của する."}, {"pattern": "見（み）えます / 聞（き）こえます", "meaning": "nhìn thấy được / nghe thấy được (tự nhiên đến tai, mắt)", "form": "N + が + 見えます・聞こえます", "explain": "見えます・聞こえます chỉ khả năng CẢM NHẬN TỰ NHIÊN: cảnh vật tự đập vào mắt, âm thanh tự lọt vào tai — khác với 見られます (có thể xem = có điều kiện/cơ hội để xem).", "examples": [{"jp": "この 部屋（へや）から 海（うみ）が 見（み）えます。", "vi": "Từ phòng này nhìn thấy biển."}, {"jp": "隣（となり）の 部屋（へや）から 音楽（おんがく）が 聞（き）こえます。", "vi": "Từ phòng bên nghe thấy tiếng nhạc."}]}, {"pattern": "～しか ～ません", "meaning": "chỉ… (thôi) — nhấn mạnh sự ít ỏi, giới hạn", "form": "Danh từ/Số lượng + しか + Động từ phủ định", "explain": "しか bắt buộc đi với động từ PHỦ ĐỊNH và mang sắc thái “chỉ có chừng đó, ít hơn mong đợi”. Khác だけ (trung tính), しか luôn hàm ý thiếu thốn, tiếc nuối.", "examples": [{"jp": "日本語（にほんご）が 少（すこ）ししか 話（はな）せません。", "vi": "Tôi chỉ nói được một chút tiếng Nhật (thôi)."}, {"jp": "財布（さいふ）には 1000（せん）円（えん）しか ありません。", "vi": "Trong ví chỉ còn có 1.000 yên."}]}, {"pattern": "N が できます", "meaning": "làm được / biết (kỹ năng, môn học)", "form": "Danh từ (kỹ năng) + が + できます", "explain": "Khi đối tượng khả năng là DANH TỪ (một kỹ năng, môn thể thao, ngôn ngữ nói chung), dùng ができます thay cho thể khả năng. Đây cũng là cách nói “xong/hoàn thành” với 仕事ができました (việc đã xong).", "examples": [{"jp": "わたしは 車（くるま）の 運転（うんてん）が できます。", "vi": "Tôi biết lái xe (lái được xe)."}, {"jp": "息子（むすこ）は まだ 泳（およ）ぐことが できません。", "vi": "Con trai tôi vẫn chưa bơi được."}]}]}, "3": {"title": "Bài 28 — Minna no Nihongo", "intro": "Bài 28 dạy làm hai việc cùng lúc (～ながら), thói quen lặp lại bằng ています, và cách nói “cả… lẫn…”.", "points": [{"pattern": "V(ます stem) ながら", "meaning": "vừa làm V1 vừa làm V2 (cùng lúc)", "form": "Động từ bỏ ます + ながら + hành động chính", "explain": "ながら nối hai hành động của CÙNG một chủ ngữ diễn ra đồng thời: hành động sau ながら là hành động CHÍNH, hành động trước là phụ (nền). Không dùng ながら cho hai hành động không thể cùng lúc về mặt vật lý.", "examples": [{"jp": "音楽（おんがく）を 聞（き）きながら 勉強（べんきょう）します。", "vi": "Tôi vừa nghe nhạc vừa học."}, {"jp": "働（はたら）きながら 日本語（にほんご）を 習（なら）いました。", "vi": "Tôi vừa làm việc vừa học tiếng Nhật."}], "note": "Chủ ngữ hai vế phải giống nhau. Muốn nói “A vừa làm… trong khi B làm…” phải dùng cấu trúc khác (～あいだ)."}, {"pattern": "Vて います (thói quen, công việc thường ngày)", "meaning": "thường xuyên làm V / làm nghề…", "form": "Động từ thể て + います với ngữ cảnh thói quen, nghề nghiệp", "explain": "Ngoài nghĩa “đang” (Bài 14) và “trạng thái” (Bài 15), ています còn chỉ hành động LẶP LẠI thành thói quen hoặc công việc đang đảm nhiệm: 毎日 バスで 通っています = hằng ngày đi lại bằng xe buýt.", "examples": [{"jp": "わたしは 学校（がっこう）で 英語（えいご）を 教（おし）えて います。", "vi": "Tôi dạy tiếng Anh ở trường."}, {"jp": "毎朝（まいあさ） 近（ちか）くの 公園（こうえん）を 走（はし）って います。", "vi": "Sáng nào tôi cũng chạy bộ ở công viên gần nhà (thói quen)."}]}, {"pattern": "N1 も N2 も", "meaning": "cả N1 lẫn N2 đều…", "form": "Danh từ + も … Danh từ + も + khẳng định (hoặc phủ định: cả hai đều không)", "explain": "も…も… ôm trọn hai đối tượng vào cùng một phán đoán: khẳng định = cả hai đều đúng; phủ định = cả hai đều không. Dùng rất nhiều khi giới thiệu khả năng, sở thích của một người đa tài.", "examples": [{"jp": "彼女（かのじょ）は 英語（えいご）も フランス語（ご）も 話（はな）せます。", "vi": "Cô ấy nói được cả tiếng Anh lẫn tiếng Pháp."}, {"jp": "土曜日（どようび）も 日曜日（にちようび）も 働（はたら）きます。", "vi": "Cả thứ Bảy lẫn Chủ nhật tôi đều làm việc."}]}, {"pattern": "それに", "meaning": "hơn nữa / vả lại (thêm một lý do cùng chiều)", "form": "Câu 1。それに、Câu 2。", "explain": "それに nối thêm một thông tin CÙNG CHIỀU để tăng sức thuyết phục: thêm lý do khen, thêm lý do chê. Khác それで (vì thế — quan hệ nhân quả) và それから (sau đó — trình tự thời gian).", "examples": [{"jp": "この 部屋（へや）は 広（ひろ）いです。それに、明（あか）るいです。", "vi": "Phòng này rộng. Hơn nữa lại sáng."}, {"jp": "あの 店（みせ）は 高（たか）いです。それに、あまり おいしくありません。", "vi": "Quán đó đắt. Vả lại cũng không ngon lắm."}]}]}, "4": {"title": "Bài 29 — Minna no Nihongo", "intro": "Bài 29 phân biệt cặp tự động từ – tha động từ và hai sắc thái trạng thái: ています (kết quả tự nhiên) với てあります (có người sắp đặt sẵn).", "points": [{"pattern": "自動詞（じどうし）と 他動詞（たどうし）", "meaning": "tự động từ (vật tự…) và tha động từ (ai làm cho vật…)", "form": "Cặp ví dụ: 開く/開ける, 閉まる/閉める, つく/つける, 消える/消す, 止まる/止める…", "explain": "Nhiều động từ tiếng Nhật đi thành cặp: tự động từ chỉ sự việc tự xảy ra (chủ ngữ là vật, dùng が), tha động từ chỉ người tác động vào vật (tân ngữ dùng を). Thuộc các cặp hay gặp là nền tảng cho Bài 29 và thể bị động Bài 37.", "examples": [{"jp": "ドアが 開（あ）きました。", "vi": "Cửa (tự) mở ra."}, {"jp": "わたしが ドアを 開（あ）けました。", "vi": "Tôi đã mở cửa."}], "note": "Mẹo: động từ tận cùng る trước nó là え (開ける, つける) đa số là THA động từ; tận cùng る với âm あ (開く, つく) đa số là TỰ động từ."}, {"pattern": "自動詞 + て います", "meaning": "đang ở trạng thái (kết quả của sự thay đổi)", "form": "Tự động từ thể て + います", "explain": "Tự động từ + ています miêu tả trạng thái HIỆN TẠI là kết quả của một thay đổi đã xảy ra: cửa đang mở (đã mở và còn mở), đèn đang tắt, xe đang dừng. Đây là cách miêu tả hiện trường chuẩn xác nhất.", "examples": [{"jp": "窓（まど）が 開（あ）いて います。", "vi": "Cửa sổ đang mở."}, {"jp": "電気（でんき）が 消（き）えて います。", "vi": "Đèn đang tắt."}]}, {"pattern": "他動詞 + て あります", "meaning": "(vật) đã được (ai đó) làm sẵn / đang trong tình trạng được sắp đặt", "form": "Tha động từ thể て + あります ; tân ngữ dùng が", "explain": "てあります ngầm nói: có NGƯỜI đã chủ ý làm việc đó và kết quả còn nguyên — thường là sự chuẩn bị chu đáo. Tân ngữ chuyển từ を thành が. Đối lập với tự động từ + ています chỉ nêu sự thật, không nhắc tới bàn tay con người.", "examples": [{"jp": "壁（かべ）に カレンダーが かけて あります。", "vi": "Trên tường đã được treo sẵn lịch."}, {"jp": "机（つくえ）の 上（うえ）に 花（はな）が 飾（かざ）って あります。", "vi": "Trên bàn đã được cắm sẵn hoa."}], "note": "×ドアが 開けてあります sai khi muốn nói cửa đang mở — phải là ドアが 開いています. Chỉ dùng てあります khi thật sự có ý đồ chuẩn bị của con người."}, {"pattern": "Vて しまいます", "meaning": "làm xong hết / lỡ làm mất rồi (tiếc nuối)", "form": "Động từ thể て + しまいます ; thân mật rút gọn: ～ちゃいます・～じゃいます", "explain": "てしまいます có hai mặt: (1) hoàn thành triệt để một việc; (2) việc đã xảy ra ngoài ý muốn và gây tiếc nuối — quên mất, làm mất, ngủ quên. Ngữ cảnh và giọng điệu quyết định nghĩa nào.", "examples": [{"jp": "宿題（しゅくだい）は もう やって しまいました。", "vi": "Bài tập tôi đã làm xong hết rồi."}, {"jp": "パスポートを なくして しまいました。", "vi": "Tôi đã lỡ làm mất hộ chiếu mất rồi."}]}]}, "5": {"title": "Bài 30 — Minna no Nihongo", "intro": "Bài 30 dạy ておきます — chuẩn bị trước cho tương lai, và cách diễn đạt “vẫn chưa làm xong”.", "points": [{"pattern": "Vて おきます", "meaning": "làm V sẵn / làm V trước (để chuẩn bị cho sau này)", "form": "Động từ thể て + おきます ; văn nói rút gọn: ～ときます・～どきます", "explain": "ておきます chỉ hành động làm trước vì một mục đích trong tương lai: đặt vé trước chuyến đi, mua sẵn đồ trước khi khách tới. Rút gọn といて trong văn nói: 買っておいて → 買っといて.", "examples": [{"jp": "旅行（りょこう）の 前（まえ）に、切符（きっぷ）を 買（か）って おきます。", "vi": "Trước chuyến du lịch, tôi mua sẵn vé."}, {"jp": "お客（きゃく）さんが 来（く）る 前（まえ）に、部屋（へや）を 掃除（そうじ）して おきました。", "vi": "Trước khi khách đến, tôi đã dọn sẵn phòng."}]}, {"pattern": "Vて おきます (giữ nguyên trạng thái)", "meaning": "để nguyên như vậy / cứ để…", "form": "Động từ thể て + おきます với nghĩa duy trì trạng thái", "explain": "Với các động từ như 開ける, つける, 置く, ておきます nghĩa là cố ý GIỮ NGUYÊN một trạng thái vì lý do nào đó: mở cửa để đó cho thoáng, để đồ ở đó chờ dùng.", "examples": [{"jp": "暑（あつ）いですから、窓（まど）を 開（あ）けて おきます。", "vi": "Vì nóng nên tôi để cửa sổ mở nguyên như vậy."}, {"jp": "その 書類（しょるい）は 机（つくえ）の 上（うえ）に 置（お）いて おいて ください。", "vi": "Tài liệu đó cứ để trên bàn giúp tôi."}]}, {"pattern": "まだ Vて いません", "meaning": "vẫn chưa làm V", "form": "まだ + Động từ thể て + いません", "explain": "まだ + phủ định của ています diễn tả việc CHƯA xảy ra tính đến hiện tại nhưng dự kiến sẽ xảy ra. Đây là câu trả lời đầy đủ, chuẩn mực hơn cho câu hỏi もう Vましたか thay vì chỉ nói まだです.", "examples": [{"jp": "レポートは まだ 書（か）いて いません。", "vi": "Báo cáo tôi vẫn chưa viết."}, {"jp": "昼（ひる）ごはんは まだ 食（た）べて いません。", "vi": "Cơm trưa tôi vẫn chưa ăn."}], "note": "Phân biệt: もう Vました (đã làm rồi) ↔ まだ Vていません (vẫn chưa làm) — cặp đối đáp kinh điển trong công việc."}]}, "6": {"title": "Bài 31 — Minna no Nihongo", "intro": "Bài 31 dạy thể ý chí (意向形) để rủ rê thân mật, nói dự định, kế hoạch — và mẫu phỏng đoán ～かもしれません.", "points": [{"pattern": "Động từ thể ý chí (意向形)", "meaning": "thể rủ rê thân mật: …đi / …thôi", "form": "Nhóm 1: hàng お + う (書く→書こう) ; Nhóm 2: bỏ る + よう ; Nhóm 3: しよう・こよう", "explain": "意向形 là dạng thân mật của ましょう: dùng để rủ bạn bè (行こう = đi thôi) hoặc tự nhủ với bản thân. Trong văn lịch sự không dùng trực tiếp với người trên.", "examples": [{"jp": "そろそろ 帰（かえ）ろう。", "vi": "Thôi, về thôi nào."}, {"jp": "明日（あした） 早（はや）く 起（お）きよう。", "vi": "Ngày mai (tôi sẽ) dậy sớm thôi."}]}, {"pattern": "意向形 + と 思（おも）います", "meaning": "tôi định / tôi dự định làm V", "form": "Động từ thể ý chí + と + 思います / 思っています", "explain": "～ようと思います diễn tả ý định vừa hình thành hoặc dự định của bản thân (nói về mình). ～ようと思っています nhấn mạnh dự định đã có từ trước và vẫn đang giữ — sắc thái “đã định sẵn trong lòng”.", "examples": [{"jp": "来年（らいねん） 日本（にほん）へ 留学（りゅうがく）しようと 思（おも）います。", "vi": "Năm sau tôi định đi du học Nhật."}, {"jp": "将来（しょうらい） 自分（じぶん）の 会社（かいしゃ）を 作（つく）ろうと 思（おも）って います。", "vi": "Tương lai tôi (đã) định sẽ lập công ty riêng."}]}, {"pattern": "Vる つもりです / Vる 予定（よてい）です", "meaning": "dự định làm V (chắc chắn trong đầu) / có lịch trình làm V", "form": "Động từ thể từ điển + つもりです・予定です ; phủ định ý định: Vない つもりです", "explain": "つもり là ý định chủ quan của người nói (mức độ quyết tâm cao, dùng cho mình và hỏi người nghe). 予定 là kế hoạch đã được SẮP XẾP khách quan (lịch trình, vé đã đặt) — dùng được cho cả tổ chức, đoàn tàu, công ty.", "examples": [{"jp": "来月（らいげつ） 国（くに）へ 帰（かえ）る つもりです。", "vi": "Tháng sau tôi dự định về nước."}, {"jp": "会議（かいぎ）は 3（さん）時（じ）に 終（お）わる 予定（よてい）です。", "vi": "Cuộc họp dự kiến kết thúc lúc 3 giờ."}], "note": "Không nói ×あした 雨が 降る つもりです vì thời tiết không có ý chí. Với thời tiết dùng でしょう/かもしれません."}, {"pattern": "普通形 + かもしれません", "meaning": "có thể… / biết đâu… (phỏng đoán 50%)", "form": "Thể thường (bỏ だ với N・な形) + かもしれません ; thân mật: かもしれない", "explain": "かもしれません diễn tả khả năng xảy ra khoảng 50% — thấp hơn でしょう nhiều. Dùng khi không có căn cứ chắc chắn: có thể đến, có thể không. Rất hay dùng để nói giảm nói tránh khi chưa chắc chắn.", "examples": [{"jp": "明日（あした）は 雨（あめ）が 降（ふ）るかもしれません。", "vi": "Ngày mai có thể trời mưa."}, {"jp": "彼（かれ）は 忙（いそが）しくて、パーティーに 来（こ）ないかもしれません。", "vi": "Anh ấy bận nên có thể không đến bữa tiệc được."}]}]}, "7": {"title": "Bài 32 — Minna no Nihongo", "intro": "Bài 32 dạy đưa lời khuyên sức khỏe/hành vi bằng ～たほうがいい, và dự đoán thời tiết, sự việc bằng でしょう.", "points": [{"pattern": "Vた ほうが いいです", "meaning": "nên làm V (khuyên)", "form": "Động từ thể た + ほうが いいです", "explain": "たほうがいい đưa ra lời khuyên “nên làm thế này thì tốt hơn” — so sánh ngầm với việc không làm. Dùng nhiều trong bối cảnh sức khỏe, học tập, an toàn. Với người trên, nên làm mềm bằng と思います ở cuối.", "examples": [{"jp": "もっと 野菜（やさい）を 食（た）べたほうが いいですよ。", "vi": "Bạn nên ăn nhiều rau hơn đấy."}, {"jp": "熱（ねつ）があるんです。— 病院（びょういん）へ 行（い）ったほうが いいですよ。", "vi": "Tôi bị sốt. — Bạn nên đi bệnh viện đi."}]}, {"pattern": "Vない ほうが いいです", "meaning": "không nên làm V (khuyên ngăn)", "form": "Động từ thể ない + ほうが いいです", "explain": "Phiên bản khuyên ngăn của mẫu trên: việc đó làm thì hại nhiều hơn lợi. Cặp đôi たほうがいい/ないほうがいい là bộ khung cho mọi lời khuyên trong tiếng Nhật sơ trung cấp.", "examples": [{"jp": "夜（よる）遅（おそ）くまで 起（お）きないほうが いいです。", "vi": "Bạn không nên thức khuya."}, {"jp": "無理（むり）を しないほうが いいですよ。", "vi": "Bạn không nên cố quá sức đâu."}]}, {"pattern": "普通形 + でしょう (dự đoán)", "meaning": "chắc là… (dự đoán có căn cứ)", "form": "Thể thường (bỏ だ với N・な形) + でしょう", "explain": "でしょう ở Bài 32 dùng cho dự đoán khách quan — đặc biệt là bản tin thời tiết: căn cứ vào dữ liệu, người nói khẳng định với độ tin cậy cao. Phân biệt với かもしれません (50%) và と思います (ý kiến chủ quan).", "examples": [{"jp": "明日（あした）の 午後（ごご）は 雨（あめ）が 降（ふ）るでしょう。", "vi": "Chiều mai chắc trời sẽ mưa."}, {"jp": "来週（らいしゅう）は 暖（あたた）かく なるでしょう。", "vi": "Tuần sau trời chắc sẽ ấm lên."}], "note": "Thứ tự độ chắc chắn: はずです > でしょう > と思います > かもしれません. Bài 46 sẽ học はずです."}]}, "8": {"title": "Bài 33 — Minna no Nihongo", "intro": "Bài 33 dạy thể mệnh lệnh và thể cấm đoán — dạng câu thấy trên biển báo, hướng dẫn khẩn cấp và lời dặn dò mạnh mẽ.", "points": [{"pattern": "Động từ thể mệnh lệnh (命令形)", "meaning": "Hãy làm V! (ra lệnh)", "form": "Nhóm 1: hàng え (書く→書け) ; Nhóm 2: bỏ る + ろ ; Nhóm 3: しろ・こい", "explain": "命令形 là mệnh lệnh trực tiếp, rất mạnh — trong đời sống chỉ dùng trong tình huống khẩn cấp, thể thao, quân đội, hoặc cha mẹ với con nhỏ. Với người ngang hàng/bề trên mà dùng 命令形 là cực kỳ thất lễ.", "examples": [{"jp": "危（あぶ）ない！ 早（はや）く 逃（に）げろ。", "vi": "Nguy hiểm! Chạy nhanh lên!"}, {"jp": "静（しず）かに しろ。", "vi": "Trật tự đi! (lời quát thân mật/thô)"}], "note": "Trong lớp học và nơi làm việc, hãy dùng てください thay cho 命令形. Nhận biết 命令形 chủ yếu để ĐỌC biển báo và hiểu phim ảnh."}, {"pattern": "Động từ thể cấm đoán (禁止形)", "meaning": "Cấm làm V! / Không được làm V!", "form": "Động từ thể từ điển + な", "explain": "禁止形 = thể từ điển + な, là lệnh cấm tuyệt đối, cặp đôi với 命令形. Xuất hiện trên biển cấm, quy định an toàn và lời cảnh báo nghiêm khắc.", "examples": [{"jp": "ここに 車（くるま）を 止（と）めるな。", "vi": "Cấm đỗ xe ở đây!"}, {"jp": "絶対（ぜったい）に 触（さわ）るな。", "vi": "Tuyệt đối không được chạm vào!"}], "note": "Dạng lịch sự của cấm đoán là ～てはいけません (Bài 15) và ～ないでください (Bài 17) — tùy quan hệ mà chọn mức độ."}, {"pattern": "～と 読（よ）みます / ～と 書（か）いて あります", "meaning": "đọc là… / được viết là…", "form": "Chữ・Từ + と + 読みます・書いてあります・言います", "explain": "Khi hỏi cách đọc một chữ Hán hoặc ý nghĩa một ký hiệu, dùng cấu trúc trích dẫn と: この漢字は どう読みますか (chữ Hán này đọc thế nào). Biển báo, ký hiệu thường được giải thích bằng ～という意味です (có nghĩa là…).", "examples": [{"jp": "この 漢字（かんじ）は 何（なん）と 読（よ）みますか。— 「禁煙（きんえん）」と 読（よ）みます。", "vi": "Chữ Hán này đọc là gì? — Đọc là “kin'en” (cấm hút thuốc)."}, {"jp": "この マークは たばこを 吸（す）っては いけないという 意味（いみ）です。", "vi": "Ký hiệu này có nghĩa là không được hút thuốc."}]}]}, "9": {"title": "Bài 34 — Minna no Nihongo", "intro": "Bài 34 hệ thống hóa cách nói “trước khi / sau khi” với độ chính xác cao: 前に, あとで, てから khác nhau ra sao.", "points": [{"pattern": "Vる 前（まえ）に", "meaning": "trước khi làm V (nhắc lại có hệ thống)", "form": "Động từ thể từ điển + 前に", "explain": "Bài 18 đã gặp 前に; ở Bài 34 mẫu này được đặt cạnh あとで để đối chiếu: dù việc chính ở quá khứ, động từ trước 前に vẫn luôn ở thể từ điển vì hành động đó chưa xảy ra tại mốc “trước”.", "examples": [{"jp": "出（で）かける 前（まえ）に、電気（でんき）を 消（け）します。", "vi": "Trước khi ra ngoài, tôi tắt điện."}, {"jp": "日本（にほん）へ 来（く）る 前（まえ）に、日本語（にほんご）を 勉強（べんきょう）しました。", "vi": "Trước khi đến Nhật, tôi đã học tiếng Nhật."}]}, {"pattern": "Vた あとで", "meaning": "sau khi làm V xong thì…", "form": "Động từ thể た + あとで ; Danh từ + の + あとで", "explain": "あとで chỉ mốc “sau khi việc trước đã hoàn tất”. Động từ đi trước あとで bắt buộc ở thể た (đã xong) — đối xứng hoàn hảo với 前に + thể từ điển (chưa làm).", "examples": [{"jp": "仕事（しごと）が 終（お）わった あとで、飲（の）みに 行（い）きましょう。", "vi": "Sau khi xong việc, chúng ta đi uống nhé."}, {"jp": "ごはんを 食（た）べた あとで、薬（くすり）を 飲（の）みます。", "vi": "Sau khi ăn cơm xong, tôi uống thuốc."}]}, {"pattern": "Vて から と Vた あとで の 違（ちが）い", "meaning": "phân biệt: てから và あとで", "form": "てから: hai hành động của cùng chủ ngữ, liền nhau ; あとで: mốc thời gian chung, chủ ngữ có thể khác", "explain": "てから nhấn mạnh trình tự hành động của MỘT người, hai việc nối sát nhau. あとで chỉ đơn thuần đặt mốc thời gian, hai vế có thể khác chủ ngữ và cách nhau khá xa. Trong nhiều câu đời thường hai mẫu thay thế được cho nhau, nhưng thi cử sẽ kiểm tra đúng điểm khác biệt này.", "examples": [{"jp": "手（て）を 洗（あら）ってから、食（た）べます。", "vi": "Rửa tay xong rồi ăn. (cùng chủ ngữ, liền nhau)"}, {"jp": "会議（かいぎ）が 終（お）わった あとで、部長（ぶちょう）に 報告（ほうこく）します。", "vi": "Sau khi cuộc họp kết thúc, tôi báo cáo cho trưởng phòng. (chủ ngữ hai vế khác nhau)"}]}]}, "10": {"title": "Bài 35 — Minna no Nihongo", "intro": "Bài 35 dạy thể điều kiện ば: “nếu/cứ… thì…”, dùng cho quy luật, điều kiện giả định và xin lời khuyên về cách làm.", "points": [{"pattern": "Động từ thể điều kiện ば (条件形)", "meaning": "nếu làm V thì…", "form": "Nhóm 1: hàng え + ば (書く→書けば) ; Nhóm 2: bỏ る + れば ; Nhóm 3: すれば・くれば", "explain": "Thể ば tạo mệnh đề điều kiện trung tính, mạnh về quy luật và tính logic: điều kiện xảy ra thì kết quả tất yếu theo sau. Tính từ -i đổi い thành ければ, tính từ -na/danh từ thêm なら hoặc であれば.", "examples": [{"jp": "春（はる）に なれば、花（はな）が 咲（さ）きます。", "vi": "Nếu sang xuân thì hoa sẽ nở."}, {"jp": "安（やす）ければ、買（か）います。", "vi": "Nếu rẻ thì tôi mua."}]}, {"pattern": "N なら", "meaning": "nếu là N thì… (điều kiện theo chủ đề)", "form": "Danh từ + なら + đề xuất/kết luận liên quan", "explain": "なら lấy một chủ đề người nghe vừa nhắc tới làm tiền đề: “nếu nói đến N / nếu là N thì…”. Thường dùng để gợi ý, giới thiệu dựa trên điều đối phương vừa nói.", "examples": [{"jp": "温泉（おんせん）なら、箱根（はこね）が いいですよ。", "vi": "Nếu là suối nước nóng thì Hakone là tuyệt nhất đấy."}, {"jp": "明日（あした）なら、わたしは 大丈夫（だいじょうぶ）です。", "vi": "Nếu là ngày mai thì tôi không sao."}]}, {"pattern": "疑問詞（ぎもんし）+ Vば いいですか", "meaning": "tôi nên làm thế nào thì được? (hỏi cách làm)", "form": "Từ hỏi + Động từ thể ば + いいですか", "explain": "Cặp bài trùng với Bài 26: hỏi bằng たら いいですか hay ば いいですか đều được. Đây là câu cửa miệng khi cần hướng dẫn thao tác máy móc, thủ tục hành chính.", "examples": [{"jp": "どうすれば いいですか。", "vi": "Tôi nên làm thế nào ạ?"}, {"jp": "どこで 降（お）りれば いいですか。", "vi": "Tôi nên xuống ở đâu ạ?"}], "note": "Ba mẫu điều kiện たら・ば・と khác nhau: と = quy luật tự nhiên (vế sau không được là ý chí); ば = logic/quy luật, hơi văn viết; たら = linh hoạt nhất, vế sau tự do nhất."}]}, "11": {"title": "Bài 36 — Minna no Nihongo", "intro": "Bài 36 xoay quanh ～ように: nói mục đích “để có thể…”, sự thay đổi “trở nên…” và nỗ lực duy trì thói quen.", "points": [{"pattern": "Vる ように、～", "meaning": "để (có thể)… — mục đích hướng tới một trạng thái", "form": "Động từ thể từ điển / thể khả năng / thể ない + ように + hành động", "explain": "ように chỉ mục đích mà kết quả KHÔNG nằm hoàn toàn trong tầm kiểm soát trực tiếp của chủ ngữ, hoặc diễn đạt một trạng thái mong đạt tới: nghe được tiếng Nhật, không quên, dậy được sớm. Khác ために (Bài 42) dùng cho mục đích chủ động, trực tiếp.", "examples": [{"jp": "日本語（にほんご）が 話（はな）せるように、毎日（まいにち） 練習（れんしゅう）します。", "vi": "Để có thể nói được tiếng Nhật, tôi luyện tập mỗi ngày."}, {"jp": "忘（わす）れないように、ノートに 書（か）きます。", "vi": "Để không quên, tôi ghi vào sổ tay."}]}, {"pattern": "Vる ように なります", "meaning": "trở nên (có thể)… / nay đã… (thay đổi trạng thái)", "form": "Động từ thể từ điển / khả năng + ように なります", "explain": "ように なります đánh dấu một sự THAY ĐỔI đã hoàn tất so với trước kia: trước không làm được, nay làm được; trước không có thói quen, nay đã thành quen.", "examples": [{"jp": "日本語（にほんご）が 話（はな）せるように なりました。", "vi": "Tôi đã trở nên nói được tiếng Nhật rồi."}, {"jp": "野菜（やさい）を 食（た）べるように なりました。", "vi": "Tôi nay đã ăn rau được rồi (trước kia không ăn)."}]}, {"pattern": "Vる ように します / して います", "meaning": "cố gắng (duy trì việc)…", "form": "Động từ thể từ điển / thể ない + ように します", "explain": "ように します là nỗ lực TỰ GIÁC duy trì một hành vi: cố gắng ăn đúng giờ, cố gắng không hút thuốc. Thêm ています thành thói quen đang duy trì.", "examples": [{"jp": "健康（けんこう）のために、毎日（まいにち） 運動（うんどう）するように して います。", "vi": "Vì sức khỏe, tôi cố gắng vận động mỗi ngày."}, {"jp": "甘（あま）い 物（もの）を 食（た）べないように します。", "vi": "Tôi sẽ cố gắng không ăn đồ ngọt."}], "note": "Ba mẫu ように phân biệt bằng động từ sau nó: trần thuật mục đích / なります = thay đổi / します = nỗ lực."}]}, "12": {"title": "Bài 37 — Minna no Nihongo", "intro": "Bài 37 dạy thể bị động — một trong những cấu trúc đặc trưng nhất của tiếng Nhật, dùng cả cho việc “bị hại” lẫn diễn đạt khách quan.", "points": [{"pattern": "Động từ thể bị động (受身形)", "meaning": "thể bị động: được / bị…", "form": "Nhóm 1: hàng あ + れる (書く→書かれる) ; Nhóm 2: bỏ る + られる ; Nhóm 3: される・こられる", "explain": "Thể bị động đổi góc nhìn câu: người CHỊU tác động lên làm chủ ngữ (は), người gây ra tác động lùi xuống với trợ từ に. Người Nhật ưa dùng bị động để tránh nêu đích danh người gây ra việc không hay.", "examples": [{"jp": "わたしは 先生（せんせい）に ほめられました。", "vi": "Tôi được thầy khen."}, {"jp": "わたしは 部長（ぶちょう）に 注意（ちゅうい）されました。", "vi": "Tôi bị trưởng phòng nhắc nhở."}]}, {"pattern": "N1 は N2 に N3 を V(受身)", "meaning": "(tôi) bị (ai) làm gì với (đồ của tôi) — bị động sở hữu", "form": "Chủ thể bị hại + は + Người gây + に + Vật sở hữu + を + Bị động", "explain": "Mẫu “bị động gián tiếp” rất Nhật Bản: chủ ngữ không trực tiếp bị tác động mà bị tác động lên ĐỒ SỞ HỮU hoặc người thân của mình — và câu luôn hàm ý phiền toái, thiệt thòi.", "examples": [{"jp": "わたしは 泥棒（どろぼう）に 財布（さいふ）を 盗（ぬす）まれました。", "vi": "Tôi bị kẻ trộm lấy mất ví."}, {"jp": "彼女（かのじょ）は 雨（あめ）に 降（ふ）られて、約束（やくそく）に 遅（おく）れました。", "vi": "Cô ấy bị (trời) mưa làm cho đến trễ buổi hẹn."}], "note": "Loại bị động “bị trời mưa, bị con khóc, bị người yêu bỏ” (迷惑の受身) không có trong tiếng Việt — cần làm quen dần qua ví dụ."}, {"pattern": "N は ～で 作（つく）られます (bị động khách quan)", "meaning": "N được làm bằng… (không nêu người gây)", "form": "Vật + は + Nguyên liệu・Nơi + で + Bị động", "explain": "Khi người gây không quan trọng hoặc là sự thật chung, bị động dùng để diễn đạt khách quan như văn khoa học, giới thiệu sản phẩm: rượu vang được làm từ nho, lễ hội được tổ chức hằng năm.", "examples": [{"jp": "ワインは ぶどうで 作（つく）られます。", "vi": "Rượu vang được làm từ nho."}, {"jp": "この 祭（まつ）りは 毎年（まいとし） 8月（はちがつ）に 行（おこな）われます。", "vi": "Lễ hội này được tổ chức vào tháng 8 hằng năm."}]}]}, "13": {"title": "Bài 38 — Minna no Nihongo", "intro": "Bài 38 dạy danh từ hóa bằng の: biến cả một hành động thành “việc…” để nói về việc quên, việc biết, và đánh giá một hành động.", "points": [{"pattern": "普通形 + の (danh từ hóa)", "meaning": "việc… / điều… (biến mệnh đề thành danh từ)", "form": "Câu thể thường + の + は・が・を…", "explain": "の làm nhiệm vụ như こと (Bài 18) nhưng gần gũi, cụ thể hơn: nó chỉ việc/hành động đang diễn ra trước mắt hoặc rất cụ thể. Sau の, ta gắn mọi trợ từ như với một danh từ bình thường.", "examples": [{"jp": "彼（かれ）が 走（はし）るのは 速（はや）いです。", "vi": "Việc anh ấy chạy thì nhanh (anh ấy chạy nhanh)."}, {"jp": "人（ひと）が 多（おお）いのが この 店（みせ）の 特徴（とくちょう）です。", "vi": "Đông khách là đặc điểm của quán này."}]}, {"pattern": "Vる のを 忘（わす）れました", "meaning": "quên làm V (quên mất việc phải làm)", "form": "Động từ thể từ điển + のを + 忘れました", "explain": "Quên một HÀNH ĐỘNG dùng のを忘れました; quên một ĐỒ VẬT (để quên ở đâu) dùng を置いてきました / 忘れ物をしました. Nhầm hai mẫu này là lỗi rất phổ biến.", "examples": [{"jp": "電気（でんき）を 消（け）すのを 忘（わす）れました。", "vi": "Tôi quên tắt điện."}, {"jp": "約束（やくそく）の 時間（じかん）を 忘（わす）れて しまいました。", "vi": "Tôi đã quên mất giờ hẹn."}]}, {"pattern": "普通形 + のは ～です", "meaning": "việc… thì… (đánh giá một hành động)", "form": "Câu thể thường + のは + Tính từ cảm xúc (楽しい・大変・危ない…)", "explain": "のは + tính từ cảm xúc là khung đánh giá trải nghiệm: việc học thì vui, việc dậy sớm thì vất vả. Đây cũng là cấu trúc nền của câu chẻ ở cấp cao hơn.", "examples": [{"jp": "日本語（にほんご）を 習（なら）うのは 楽（たの）しいです。", "vi": "Việc học tiếng Nhật thì vui."}, {"jp": "一人（ひとり）で 引（ひ）っ越（こ）しをするのは 大変（たいへん）です。", "vi": "Việc một mình chuyển nhà thì vất vả."}]}]}, "14": {"title": "Bài 39 — Minna no Nihongo", "intro": "Bài 39 dạy nêu nguyên nhân bằng thể て và trợ từ で: giải thích vì sao gặp rắc rối, vì sao muộn, và lời xin lỗi/cảm ơn kèm lý do.", "points": [{"pattern": "Vて / い形くて / な形で、～ (nguyên nhân)", "meaning": "vì… nên… (nguyên nhân bằng thể nối)", "form": "Động từ thể て・い形くて・な形で + kết quả (thường là cảm xúc, tình huống ngoài ý muốn)", "explain": "Thể nối câu học ở Bài 16 còn một nhiệm vụ nữa: nêu NGUYÊN NHÂN. Vế sau thường là kết quả không mong muốn hoặc cảm xúc (困る, 遅れる, 残念). Không dùng thể て-nguyên nhân cho mệnh lệnh, ý chí ở vế sau.", "examples": [{"jp": "事故（じこ）が あって、バスが 遅（おく）れました。", "vi": "Vì có tai nạn nên xe buýt đến muộn."}, {"jp": "熱（ねつ）が あって、仕事（しごと）を 休（やす）みました。", "vi": "Vì bị sốt nên tôi nghỉ làm."}]}, {"pattern": "N で (nguyên nhân – sự kiện)", "meaning": "vì (sự kiện/thiên tai/bệnh tật)…", "form": "Danh từ sự kiện + で + kết quả", "explain": "で sau danh từ chỉ sự kiện (地震, 台風, 事故, 病気) nêu nguyên nhân khách quan gây ra kết quả. Đây là lối viết bản tin kinh điển: 地震で ビルが 倒れました.", "examples": [{"jp": "台風（たいふう）で 木（き）が 倒（たお）れました。", "vi": "Vì bão nên cây đổ."}, {"jp": "雪（ゆき）で 電車（でんしゃ）が 止（と）まりました。", "vi": "Vì tuyết nên tàu điện dừng."}]}, {"pattern": "Vて すみません / ありがとうございました", "meaning": "xin lỗi vì đã… / cảm ơn vì đã…", "form": "Động từ thể て + すみません・ありがとうございました", "explain": "Khi xin lỗi hoặc cảm ơn KÈM LÝ DO, lý do đó gắn bằng thể て ngay trước lời xin lỗi/cảm ơn. Cấu trúc nhỏ này xuất hiện hằng ngày trong giao tiếp lịch sự của người Nhật.", "examples": [{"jp": "遅（おく）れて すみません。", "vi": "Xin lỗi vì tôi đến muộn."}, {"jp": "手伝（てつだ）って くれて、ありがとうございました。", "vi": "Cảm ơn anh đã giúp đỡ tôi."}]}]}, "15": {"title": "Bài 40 — Minna no Nihongo", "intro": "Bài 40 dạy lồng câu hỏi vào trong câu (～か), thử làm một việc (～てみます), và hai cách dùng mới của なら・でも.", "points": [{"pattern": "疑問文 + か (câu hỏi lồng)", "meaning": "…hay không / …là gì, được lồng vào giữa câu", "form": "Câu hỏi thể thường + か + Động từ (知っていますか・教えてください・わかりません…)", "explain": "Muốn nói “không biết là có… hay không”, ta đóng gói cả câu hỏi thành thể thường + か rồi gắn vào câu chính. Câu hỏi có từ hỏi (何, どこ, いつ) giữ nguyên từ hỏi; câu hỏi có/không thì thêm ～かどうか.", "examples": [{"jp": "明日（あした） 雨（あめ）が 降（ふ）るか どうか、わかりません。", "vi": "Tôi không biết ngày mai trời có mưa hay không."}, {"jp": "会議（かいぎ）は 何時（なんじ）に 終（お）わるか 教（おし）えて ください。", "vi": "Hãy cho tôi biết cuộc họp kết thúc lúc mấy giờ."}], "note": "かどうか dùng riêng cho câu hỏi dạng có/không (yes-no). Có từ hỏi rồi thì không cần かどうか."}, {"pattern": "Vて みます", "meaning": "làm V thử xem", "form": "Động từ thể て + みます", "explain": "てみます nghĩa là làm thử để XEM KẾT QUẢ thế nào: ăn thử, mặc thử, dùng thử. Cửa hàng nào ở Nhật cũng dùng mẫu này: どうぞ 試着してみてください (xin mời mặc thử).", "examples": [{"jp": "この 靴（くつ）を はいて みても いいですか。", "vi": "Tôi đi thử đôi giày này có được không?"}, {"jp": "新（あたら）しい レストランに 行（い）って みましょう。", "vi": "Chúng ta thử đến nhà hàng mới xem sao."}]}, {"pattern": "N なら (đề xuất theo chủ đề)", "meaning": "nếu (nói đến) N thì… (gợi ý, giới thiệu)", "form": "Danh từ + なら + thông tin/gợi ý", "explain": "なら ở Bài 40 dùng để đón ý người nghe rồi đưa gợi ý — gần nghĩa “còn nếu là N thì…”. Đây là tiền thân của mẫu điều kiện なら hoàn chỉnh ở trình độ cao hơn.", "examples": [{"jp": "奈良（なら）なら、東大寺（とうだいじ）が 有名（ゆうめい）です。", "vi": "Nếu (đi) Nara thì chùa Todaiji nổi tiếng đấy."}, {"jp": "ビールなら、この ブランドが おいしいですよ。", "vi": "Nếu là bia thì nhãn hiệu này ngon đấy."}]}, {"pattern": "N でも (ví dụ tiêu biểu)", "meaning": "(ví dụ như) N chẳng hạn", "form": "Danh từ + でも + đề xuất nhẹ nhàng", "explain": "でも sau danh từ nêu một VÍ DỤ ĐIỂN HÌNH trong nhiều lựa chọn, thường để đề xuất một cách khiêm tốn: お茶でも 飲みませんか (uống trà chẳng hạn nhé). Sắc thái mềm hơn hẳn khi nêu thẳng tên món.", "examples": [{"jp": "映画（えいが）でも 見（み）に 行（い）きませんか。", "vi": "Đi xem phim chẳng hạn, bạn có muốn không?"}, {"jp": "コーヒーでも いかがですか。", "vi": "Bạn dùng cà phê chẳng hạn nhé?"}]}]}, "16": {"title": "Bài 41 — Minna no Nihongo", "intro": "Bài 41 nâng cấp cho – nhận hành động lên mức TRANG TRỌNG: khi người làm ơn cho mình là cấp trên, khách hàng đáng kính.", "points": [{"pattern": "Vて いただきます", "meaning": "(tôi) vinh hạnh được (cấp trên) làm V cho", "form": "Người bề trên + に + Động từ thể て + いただきます", "explain": "いただきます là dạng khiêm nhường của もらいます: dùng khi người làm giúp là BỀ TRÊN (sếp, thầy, khách hàng). Chủ ngữ luôn là người nói (bề dưới), và mẫu này thể hiện sự kính trọng, biết ơn đúng mực trong công sở Nhật.", "examples": [{"jp": "わたしは 社長（しゃちょう）に 推薦状（すいせんじょう）を 書（か）いて いただきました。", "vi": "Tôi đã được giám đốc viết cho thư giới thiệu."}, {"jp": "先生（せんせい）に 論文（ろんぶん）を 見（み）て いただきました。", "vi": "Tôi được thầy xem cho bài luận văn."}], "note": "Cặp ba mức độ: てくれます (thường) → てもらいます (lịch sự vừa) → ていただきます (kính trọng với bề trên)."}, {"pattern": "Vて くださいます", "meaning": "(cấp trên) làm V cho (tôi)", "form": "Người bề trên + は/が + Động từ thể て + くださいます", "explain": "くださいます là dạng tôn kính của くれます: chủ ngữ là bề trên chủ động làm điều tốt cho mình. Hai mẫu ていただきます/くださいます nói cùng một sự việc từ hai phía — chọn phía nào làm chủ ngữ tùy trọng tâm câu.", "examples": [{"jp": "部長（ぶちょう）が 駅（えき）まで 送（おく）って くださいました。", "vi": "Trưởng phòng đã (tốt bụng) tiễn tôi ra ga."}, {"jp": "先生（せんせい）が 丁寧（ていねい）に 説明（せつめい）して くださいました。", "vi": "Thầy đã giải thích cho tôi một cách tận tình."}]}, {"pattern": "Vて いただけませんか", "meaning": "Anh/chị có thể vui lòng làm V giúp được không ạ? (nhờ vả trang trọng nhất ở N4)", "form": "Động từ thể て + いただけませんか", "explain": "Đây là đỉnh lịch sự của lời nhờ vả ở trình độ này: dạng phủ định nghi vấn của ていただきます. Dùng với khách hàng, cấp trên cao, người hoàn toàn xa lạ trong tình huống trang trọng.", "examples": [{"jp": "すみません、この 書類（しょるい）に サインして いただけませんか。", "vi": "Xin lỗi, anh có thể vui lòng ký vào tài liệu này giúp tôi được không ạ?"}, {"jp": "写真（しゃしん）を 撮（と）って いただけませんか。", "vi": "Anh có thể vui lòng chụp ảnh giúp tôi được không ạ?"}], "note": "Thang lịch sự nhờ vả: てください → てくださいませんか → ていただけませんか. Lên một bậc là tăng hẳn một mức tôn trọng."}]}, "17": {"title": "Bài 42 — Minna no Nihongo", "intro": "Bài 42 dạy nêu mục đích bằng ～ために: học để làm gì, tiết kiệm vì ai — và cách nói số lượng “ít nhất / đến tận”.", "points": [{"pattern": "Vる ために", "meaning": "để làm V (mục đích chủ động)", "form": "Động từ thể từ điển + ために + hành động thực hiện", "explain": "ために chỉ mục đích mà chủ ngữ CHỦ ĐỘNG kiểm soát được, hai vế thường cùng chủ ngữ. Đối lập với ように (Bài 36) dùng khi kết quả ngoài tầm kiểm soát trực tiếp hoặc ở dạng khả năng/phủ định.", "examples": [{"jp": "日本（にほん）で 働（はたら）くために、日本語（にほんご）を 勉強（べんきょう）して います。", "vi": "Để làm việc ở Nhật, tôi đang học tiếng Nhật."}, {"jp": "家（いえ）を 買（か）うために、お金（かね）を 貯（た）めて います。", "vi": "Để mua nhà, tôi đang tiết kiệm tiền."}], "note": "Phân biệt nhanh: sau ために là động từ Ý CHÍ (買う, 働く); sau ように thường là động từ KHẢ NĂNG hoặc phủ định (話せるように, 忘れないように)."}, {"pattern": "N の ために", "meaning": "vì (lợi ích của) N / vì (mục đích) N", "form": "Danh từ + の + ために", "explain": "の ために sau danh từ mang hai nghĩa: vì lợi ích của ai đó (家族のために働く) hoặc vì một sự kiện/mục đích (試験のために). Ngữ cảnh quyết định cách hiểu.", "examples": [{"jp": "家族（かぞく）のために、一生懸命（いっしょうけんめい） 働（はたら）きます。", "vi": "Tôi làm việc hết mình vì gia đình."}, {"jp": "健康（けんこう）のために、毎朝（まいあさ） 走（はし）ります。", "vi": "Vì sức khỏe, sáng nào tôi cũng chạy bộ."}]}, {"pattern": "数量 + は / も (ít nhất / những)", "meaning": "cần ít nhất… / mất những, tốn những…", "form": "Số lượng + は (dự đoán tối thiểu) / も (nhấn mạnh nhiều)", "explain": "Số lượng + は diễn tả mức TỐI THIỂU cần thiết theo dự đoán (ít nhất phải có chừng đó). Số lượng + も nhấn mạnh con số LỚN hơn kỳ vọng (những tận…). Cặp trợ từ nhỏ này làm câu nói về con số trở nên rất “Nhật”.", "examples": [{"jp": "この 仕事（しごと）は 3（さん）日（にち）は かかります。", "vi": "Công việc này mất ít nhất 3 ngày."}, {"jp": "パーティーに 50（ごじゅう）人（にん）も 来（き）ました。", "vi": "Buổi tiệc có những 50 người đến."}]}]}, "18": {"title": "Bài 43 — Minna no Nihongo", "intro": "Bài 43 dạy phỏng đoán qua vẻ bề ngoài bằng ～そうです: trông có vẻ ngon, sắp mưa — và mẫu ～てきます đa nghĩa.", "points": [{"pattern": "V(ます stem) + そうです", "meaning": "có vẻ sắp… / trông như sắp…", "form": "Động từ bỏ ます + そうです ; phủ định: Vなさそうです", "explain": "そうです gắn vào gốc ます diễn tả ấn tượng TRỰC QUAN ngay trước mắt: trời sắp mưa, em bé sắp ngã, máy sắp hỏng. Chỉ dùng cho sự việc sắp xảy ra hoặc đang hiển hiện, không dùng cho dự đoán xa.", "examples": [{"jp": "雨（あめ）が 降（ふ）りそうです。", "vi": "Trời có vẻ sắp mưa."}, {"jp": "この 荷物（にもつ）は 落（お）ちそうです。", "vi": "Hành lý này trông như sắp rơi."}], "note": "Tuyệt đối phân biệt với そうです truyền văn (Bài 47): truyền văn gắn vào THỂ THƯỜNG (降るそうです = nghe nói trời mưa), vẻ bề ngoài gắn vào GỐC ます (降りそうです = có vẻ sắp mưa)."}, {"pattern": "形容詞 + そうです", "meaning": "(trông) có vẻ…", "form": "い形 bỏ い + そうです (いい→よさそうです) ; な形 + そうです", "explain": "Tính từ + そうです là “nhìn bề ngoài đoán”: món ăn trông ngon, người trông khỏe. Riêng ない thì thành なさそうです. Không dùng そうです cho chính cảm xúc của mình (không tự nói ×私は嬉しそうです về bản thân).", "examples": [{"jp": "この ケーキは おいしそうです。", "vi": "Cái bánh này trông ngon."}, {"jp": "彼女（かのじょ）は 元気（げんき）そうです。", "vi": "Cô ấy trông có vẻ khỏe."}]}, {"pattern": "Vて きます", "meaning": "đi làm V rồi về / (thay đổi) dần đến nay / bắt đầu…", "form": "Động từ thể て + きます", "explain": "てきます có ba sắc thái chính: (1) đi đâu làm việc gì rồi quay về (買ってきます = đi mua rồi về); (2) sự thay đổi tiến triển đến hiện tại (増えてきました = đã tăng lên đến nay); (3) bắt đầu một xu hướng. Ngữ cảnh quyết định nghĩa.", "examples": [{"jp": "ちょっと たばこを 買（か）って きます。", "vi": "Tôi đi mua thuốc lá một lát rồi về."}, {"jp": "最近（さいきん）、日本語（にほんご）を 勉強（べんきょう）する 人（ひと）が 増（ふ）えて きました。", "vi": "Dạo gần đây, số người học tiếng Nhật đã ngày càng tăng."}]}]}, "19": {"title": "Bài 44 — Minna no Nihongo", "intro": "Bài 44 dạy nói về mức độ quá mức (～すぎます), dễ/khó làm (～やすい/にくい), và chủ động thay đổi trạng thái (～く/に します).", "points": [{"pattern": "V(ます stem) すぎます / 形容詞 すぎます", "meaning": "quá… / làm V quá mức", "form": "Động từ bỏ ます + すぎます ; い形 bỏ い + すぎます ; な形 + すぎます", "explain": "すぎます gắn vào sau gốc từ để chỉ mức độ VƯỢT QUA chuẩn mực cho phép — luôn hàm ý tiêu cực, quá đà. Nó tự chia như động từ nhóm 2 (すぎる, すぎた, すぎない).", "examples": [{"jp": "昨夜（ゆうべ） 飲（の）みすぎました。", "vi": "Tối qua tôi uống quá nhiều."}, {"jp": "この 問題（もんだい）は 難（むずか）しすぎます。", "vi": "Bài toán này khó quá mức."}], "note": "すぎます đứng sau tính từ thì tính từ mất đuôi い: 高い → 高すぎます (không phải 高いすぎます)."}, {"pattern": "V(ます stem) やすい / にくい", "meaning": "dễ làm V / khó làm V", "form": "Động từ bỏ ます + やすい・にくい (chia như tính từ -i)", "explain": "やすい・にくい đánh giá độ dễ/khó của hành động do tính chất của đối tượng: chữ dễ đọc, đường khó đi, thịt khó cắt. Cả hai chia đúng như tính từ -i.", "examples": [{"jp": "この 本（ほん）は 字（じ）が 大（おお）きくて、読（よ）みやすいです。", "vi": "Cuốn sách này chữ to nên dễ đọc."}, {"jp": "この 道（みち）は 暗（くら）くて、歩（ある）きにくいです。", "vi": "Đường này tối nên khó đi."}]}, {"pattern": "い形く / な形・N に します", "meaning": "làm cho… trở nên… (chủ động thay đổi)", "form": "い形 bỏ い + く + します ; な形・Danh từ + に + します", "explain": "～く/に します diễn tả chủ ngữ CHỦ ĐỘNG làm thay đổi trạng thái của vật: vặn nhỏ nhạc, làm phòng sạch. Đừng nhầm với ～くなります/になります (tự trở nên — thay đổi tự nhiên).", "examples": [{"jp": "音（おと）を 小（ちい）さく して ください。", "vi": "Hãy vặn nhỏ âm lượng giúp tôi."}, {"jp": "部屋（へや）を きれいに しました。", "vi": "Tôi đã dọn phòng sạch sẽ."}]}, {"pattern": "N に します", "meaning": "chọn / quyết định lấy N", "form": "Danh từ + に + します", "explain": "にします sau danh từ nghĩa là quyết định chọn: gọi món trong nhà hàng, chọn lịch trình. Câu cửa miệng: わたしは コーヒーに します (tôi lấy cà phê).", "examples": [{"jp": "飲（の）み物（もの）は 何（なに）に しますか。— ジュースに します。", "vi": "Đồ uống bạn lấy gì? — Tôi lấy nước trái cây."}, {"jp": "旅行（りょこう）の 日（ひ）は 来週（らいしゅう）の 土曜日（どようび）に しました。", "vi": "Ngày đi du lịch tôi đã quyết định là thứ Bảy tuần sau."}]}]}, "20": {"title": "Bài 45 — Minna no Nihongo", "intro": "Bài 45 dạy xử lý tình huống bằng ～場合は và sự trái kỳ vọng bằng ～のに: chuẩn bị cho điều bất ngờ, và than phiền điều không như mong đợi.", "points": [{"pattern": "普通形 + 場合は（ばあいは）", "meaning": "trong trường hợp… thì…", "form": "Thể thường + 場合は + biện pháp xử lý", "explain": "場合は là mẫu trang trọng để nêu tình huống giả định kèm cách xử lý — ngôn ngữ của hướng dẫn sử dụng, quy định, thông báo: trường hợp khẩn cấp, trường hợp muộn, trường hợp không hiểu.", "examples": [{"jp": "地震（じしん）の 場合（ばあい）は、エレベーターを 使（つか）わないで ください。", "vi": "Trong trường hợp có động đất, xin đừng dùng thang máy."}, {"jp": "遅（おく）れる 場合（ばあい）は、電話（でんわ）して ください。", "vi": "Trong trường hợp đến muộn, hãy gọi điện báo."}]}, {"pattern": "普通形 + のに", "meaning": "…thế mà / mặc dù… (trái với kỳ vọng, bất mãn)", "form": "Thể thường (な形・N + な) + のに + kết quả trái ngược", "explain": "のに diễn tả hai sự việc MÂU THUẪN: vế trước là điều kiện mà lẽ ra phải dẫn tới kết quả khác. Luôn kèm cảm xúc ngạc nhiên, tiếc nuối hoặc phàn nàn của người nói — khác が・けれど trung tính.", "examples": [{"jp": "一生懸命（いっしょうけんめい） 勉強（べんきょう）したのに、試験（しけん）に 落（お）ちました。", "vi": "Đã học hành chăm chỉ thế mà tôi vẫn trượt kỳ thi."}, {"jp": "薬（くすり）を 飲（の）んだのに、熱（ねつ）が 下（さ）がりません。", "vi": "Đã uống thuốc thế mà sốt không hạ."}], "note": "な形 và danh từ trước のに phải có な: 静かなのに, 休みなのに. Đây cũng là chủ điểm thi JLPT rất hay ra."}]}, "21": {"title": "Bài 46 — Minna no Nihongo", "intro": "Bài 46 dạy ～たばかり (vừa mới làm xong) và ～はずです (chắc chắn theo suy luận) — hai mẫu về mức độ chắc chắn và độ “mới” của sự việc.", "points": [{"pattern": "Vた ばかりです", "meaning": "vừa mới làm V xong", "form": "Động từ thể た + ばかりです", "explain": "ばかり sau thể た chỉ việc VỪA mới xảy ra theo cảm nhận của người nói — khoảng thời gian “vừa” này mang tính chủ quan: vừa ăn cách đây 5 phút cũng được, vừa tốt nghiệp cách đây 1 tháng cũng được nếu người nói còn cảm giác mới mẻ.", "examples": [{"jp": "昼（ひる）ごはんを 食（た）べたばかりです。", "vi": "Tôi vừa mới ăn trưa xong."}, {"jp": "日本（にほん）へ 来（き）たばかりで、まだ 何（なに）も わかりません。", "vi": "Tôi vừa mới đến Nhật nên chưa biết gì cả."}], "note": "Phân biệt với たところです (Bài N3 sẽ gặp): ところ nhấn mạnh khoảnh khắc ngay tức thì, khách quan hơn ばかり."}, {"pattern": "普通形 + はずです", "meaning": "chắc chắn là… (theo suy luận, lịch trình)", "form": "Thể thường + はずです ; phủ định: はずが ありません / ～ない はずです", "explain": "はずです là kết luận từ căn cứ chắc chắn: lịch trình đã định, quy luật, lời hẹn. Độ tin cậy cao nhất trong các mẫu dự đoán đã học — vì thế khi thực tế khác với はず, người nói rất ngạc nhiên (～はずなのに).", "examples": [{"jp": "電車（でんしゃ）は 9（きゅう）時（じ）に 着（つ）くはずです。", "vi": "Tàu điện chắc chắn 9 giờ sẽ đến (theo lịch trình)."}, {"jp": "彼（かれ）は 約束（やくそく）を 守（まも）る 人（ひと）ですから、来（く）るはずです。", "vi": "Anh ấy là người giữ lời hứa nên chắc chắn sẽ đến."}], "note": "Thang chắc chắn hoàn chỉnh: かもしれません (50%) → でしょう (khá chắc) → はずです (chắc chắn theo căn cứ) → に違いありません (N3, chắc chắn khẳng định)."}]}, "22": {"title": "Bài 47 — Minna no Nihongo", "intro": "Bài 47 dạy hai mẫu nghe – đoán: ～そうです (truyền văn, nghe nói) và ～ようです (dự đoán có căn cứ quan sát).", "points": [{"pattern": "普通形 + そうです (伝聞)", "meaning": "nghe nói là… / theo tin tức thì…", "form": "Thể thường + そうです ; nguồn tin: ～によると", "explain": "そうです truyền văn thuật lại thông tin NGHE ĐƯỢC từ người khác, báo đài — người nói không chịu trách nhiệm về độ chính xác. Thường kèm nguồn: ニュースによると (theo tin tức), 天気予報によると (theo dự báo thời tiết).", "examples": [{"jp": "天気予報（てんきよほう）によると、明日（あした）は 雨（あめ）だそうです。", "vi": "Theo dự báo thời tiết, nghe nói ngày mai trời mưa."}, {"jp": "田中（たなか）さんは 来月（らいげつ） 結婚（けっこん）するそうです。", "vi": "Nghe nói anh Tanaka tháng sau kết hôn."}], "note": "Nhắc lại điểm phân biệt sống còn: 降るそうです = NGHE NÓI trời mưa (truyền văn, thể thường); 降りそうです = CÓ VẺ sắp mưa (quan sát trực tiếp, gốc ます)."}, {"pattern": "普通形 + ようです", "meaning": "có vẻ như… / hình như… (dự đoán từ quan sát)", "form": "Thể thường (な形・N + の) + ようです", "explain": "ようです là dự đoán dựa trên điều MẮT THẤY TAI NGHE của chính người nói: thấy nhà sáng đèn thì đoán có người ở nhà. Mềm và chắc hơn みたいです (dạng thân mật cùng nghĩa).", "examples": [{"jp": "隣（となり）の 部屋（へや）は 静（しず）かです。だれも いないようです。", "vi": "Phòng bên yên tĩnh. Có vẻ như không có ai."}, {"jp": "彼（かれ）は 風邪（かぜ）を ひいたようです。", "vi": "Anh ấy có vẻ như bị cảm rồi."}]}, {"pattern": "N の ような / N の ように", "meaning": "giống như N / như N (so sánh ví von)", "form": "Danh từ + のような + Danh từ ; Danh từ + のように + Động từ/Tính từ", "explain": "のような・のように dùng N làm chuẩn ví von: giọng hát như ca sĩ, chạy nhanh như gió. Cặp này là phiên bản trang trọng của みたいな・みたいに.", "examples": [{"jp": "彼女（かのじょ）の 声（こえ）は 歌手（かしゅ）の ようです。", "vi": "Giọng của cô ấy giống như ca sĩ."}, {"jp": "鳥（とり）のように 空（そら）を 飛（と）びたいです。", "vi": "Tôi muốn bay trên trời như chim."}]}]}, "23": {"title": "Bài 48 — Minna no Nihongo", "intro": "Bài 48 dạy thể sai khiến: bắt/cho phép người khác làm việc gì, và mẫu xin phép trang trọng ～させてください.", "points": [{"pattern": "Động từ thể sai khiến (使役形)", "meaning": "bắt / cho (ai) làm V", "form": "Nhóm 1: hàng あ + せる (書く→書かせる) ; Nhóm 2: bỏ る + させる ; Nhóm 3: させる・こさせる", "explain": "Thể sai khiến tạo ra quan hệ HAI TẦNG: người ra lệnh (chủ ngữ は) và người thực hiện hành động (đánh dấu に). Nghĩa “bắt làm” hay “cho phép làm” phụ thuộc vào ngữ cảnh và quan hệ hai bên.", "examples": [{"jp": "先生（せんせい）は 学生（がくせい）に 本（ほん）を 読（よ）ませました。", "vi": "Thầy cho học sinh đọc sách."}, {"jp": "母（はは）は 子どもに 野菜（やさい）を 食（た）べさせます。", "vi": "Mẹ bắt con ăn rau."}], "note": "Tự động từ sai khiến thì người thực hiện dùng を; tha động từ thì người thực hiện dùng に, tân ngữ giữ を."}, {"pattern": "V(使役)て ください", "meaning": "xin hãy cho tôi làm V (xin phép trang trọng)", "form": "Động từ thể sai khiến + て + ください", "explain": "させてください là cách XIN PHÉP cho chính mình làm việc gì — khiêm tốn và trang trọng hơn てもいいですか, rất hợp khi trình bày trong cuộc họp, xin ý kiến cấp trên.", "examples": [{"jp": "わたしに 説明（せつめい）させて ください。", "vi": "Xin hãy cho tôi được trình bày."}, {"jp": "ちょっと 考（かんが）えさせて ください。", "vi": "Xin cho tôi suy nghĩ một chút."}], "note": "Trong công sở, cặp đôi vàng: 上司に 報告させる (bắt cấp dưới báo cáo) ↔ 説明させてください (xin được trình bày)."}]}, "24": {"title": "Bài 49 — Minna no Nihongo", "intro": "Bài 49 mở cánh cửa kính ngữ tôn kính (尊敬語): nâng cao hành động của cấp trên, khách hàng khi nói về họ.", "points": [{"pattern": "お + V(ます stem) + に なります", "meaning": "(bề trên) làm V — tôn kính dạng cơ bản", "form": "お + Động từ bỏ ます + に + なります", "explain": "Đây là công thức tôn kính phổ quát cho động từ nhóm 1 và 2: biến bất kỳ hành động nào của bề trên thành dạng kính trọng. Chủ ngữ của câu luôn là NGƯỜI ĐƯỢC KÍNH (sếp, khách, thầy), tuyệt đối không dùng cho hành động của chính mình.", "examples": [{"jp": "社長（しゃちょう）は もう お帰（かえ）りに なりました。", "vi": "Giám đốc đã về rồi ạ."}, {"jp": "先生（せんせい）は 何時（なんじ）に お見（み）えに なりますか。", "vi": "Thầy sẽ đến lúc mấy giờ ạ?"}], "note": "Động từ 1 âm tiết gốc ます (見る→見, 寝る→寝) và động từ nhóm 3 thường KHÔNG dùng được mẫu お～に なります — phải dùng động từ tôn kính riêng ở điểm dưới."}, {"pattern": "Động từ tôn kính đặc biệt", "meaning": "các động từ tôn kính phải thuộc lòng", "form": "行く・来る・いる→いらっしゃる ; 食べる・飲む→召し上がる ; 言う→おっしゃる ; 見る→ご覧になる ; する→なさる ; 知っている→ご存じです", "explain": "Một nhóm động từ tần suất cao có dạng tôn kính RIÊNG hoàn toàn khác gốc — phải học thuộc như từ vựng mới. Đây là phần thi JLPT và giao tiếp công sở đều kiểm tra kỹ.", "examples": [{"jp": "お客（きゃく）さまは 二階（にかい）に いらっしゃいます。", "vi": "Quý khách đang ở tầng hai ạ."}, {"jp": "社長（しゃちょう）は 何（なに）と おっしゃいましたか。", "vi": "Giám đốc đã nói gì vậy ạ?"}]}, {"pattern": "Vられて (tôn kính bằng bị động)", "meaning": "(bề trên) làm V — cách tôn kính nhẹ", "form": "Động từ thể bị động dùng với nghĩa tôn kính", "explain": "Thể bị động học ở Bài 37 còn kiêm nhiệm vụ tôn kính mức độ NHẸ: 先生が 説明されました vừa hiểu là “thầy được giải thích” (sai) vừa hiểu là “thầy đã giải thích” (tôn kính) — ngữ cảnh quyết định. Người Nhật dùng cách này khi muốn kính trọng vừa phải.", "examples": [{"jp": "部長（ぶちょう）は 明日（あした） 出張（しゅっちょう）されます。", "vi": "Trưởng phòng ngày mai đi công tác ạ."}, {"jp": "先生（せんせい）は もう 帰（かえ）られました。", "vi": "Thầy đã về rồi ạ."}], "note": "Mức tôn kính: Vられる (nhẹ) < おVに なります (chuẩn) < động từ tôn kính đặc biệt (cao nhất, trang trọng nhất)."}]}, "25": {"title": "Bài 50 — Minna no Nihongo", "intro": "Bài cuối của N4 dạy kính ngữ khiêm nhường (謙譲語): hạ thấp hành động của bản thân để tôn trọng người nghe — hoàn thiện hệ thống kính ngữ.", "points": [{"pattern": "お + V(ます stem) + します", "meaning": "(tôi) xin làm V cho (bề trên) — khiêm nhường dạng cơ bản", "form": "お + Động từ bỏ ます + します / いたします", "explain": "Công thức khiêm nhường phổ quát: chủ ngữ là NGƯỜI NÓI (hoặc người nhà mình) thực hiện hành động HƯỚNG TỚI bề trên. Thay します bằng いたします sẽ càng trang trọng.", "examples": [{"jp": "わたしが 荷物（にもつ）を お持（も）ちします。", "vi": "Tôi xin cầm hành lý giúp ạ."}, {"jp": "駅（えき）まで お送（おく）りします。", "vi": "Tôi xin tiễn anh ra ga ạ."}], "note": "Cặp đối xứng cần nhớ: おVに なります = bề trên làm (tôn kính); おVします = tôi làm cho bề trên (khiêm nhường). Nhầm hai chiều này là lỗi kính ngữ nghiêm trọng nhất."}, {"pattern": "Động từ khiêm nhường đặc biệt", "meaning": "các động từ khiêm nhường phải thuộc lòng", "form": "行く・来る→参る ; 言う→申す・申し上げる ; 食べる・もらう→いただく ; 見る→拝見する ; 会う→お目にかかる ; 知っている→存じています ; する→いたす", "explain": "Giống tôn kính, nhóm động từ thường dùng cũng có dạng khiêm nhường riêng. Nói về bản thân trước khách hàng mà dùng động từ thường sẽ thiếu chuyên nghiệp trong môi trường Nhật.", "examples": [{"jp": "わたしは 田中（たなか）と 申（もう）します。", "vi": "Tôi tên là Tanaka (khiêm nhường)."}, {"jp": "資料（しりょう）を 拝見（はいけん）してから、ご連絡（れんらく）いたします。", "vi": "Sau khi xem tài liệu, tôi sẽ liên lạc lại ạ."}]}, {"pattern": "～で ございます", "meaning": "là… ạ (dạng trang trọng cao của です)", "form": "Danh từ・Tính từ + で ございます", "explain": "ございます là dạng lịch sự nâng cao của あります, và でございます thay cho です trong phục vụ khách hàng, lễ tân, phát thanh. Nghe thấy ở mọi cửa hàng Nhật: こちらで ございます (đây ạ).", "examples": [{"jp": "会場（かいじょう）は 二階（にかい）で ございます。", "vi": "Hội trường ở tầng hai ạ."}, {"jp": "お会計（かいけい）は 5000（ごせん）円（えん）で ございます。", "vi": "Tổng thanh toán là 5.000 yên ạ."}], "note": "Kết thúc N4, học viên đã có đủ ba tầng: thường ngữ (です/ます) — tôn kính (nâng người nghe) — khiêm nhường (hạ bản thân). Đây là bộ khung kính ngữ cho mọi giao tiếp xã hội tại Nhật."}]}}, "N3": {"1": {"title": "Unit 01 · 名詞 A — Danh từ A · Mimi kara Oboeru", "intro": "Bài giảng ngữ pháp N3 trọng tâm số 1: nhóm mẫu chỉ thời điểm – quá trình xảy ra quanh một hành động (うちに, あいだ, ところ).", "points": [{"pattern": "Vる / Vている / Vた + ところ", "meaning": "đang ở đúng giai đoạn… của hành động", "form": "Vる ところ (sắp làm) / Vている ところ (đang làm dở) / Vた ところ (vừa mới làm xong)", "explain": "ところ biến một hành động thành một “điểm” trên dòng thời gian: trước khi bắt đầu (Vる ところ), ngay giữa quá trình (Vている ところ), và ngay sau khi hoàn tất (Vた ところ). Ba dạng này luôn đi thành bộ và rất hay ra trong thi N3.", "examples": [{"jp": "これから 出（で）かけるところです。", "vi": "Tôi đang sắp ra ngoài đây."}, {"jp": "今（いま）、ごはんを 食（た）べたところです。", "vi": "Tôi vừa mới ăn cơm xong."}], "note": "Vた ところ là khoảnh khắc NGAY sau khi xong (tính bằng phút), khác Vた ばかり (Bài 46 N4) là “vừa” theo cảm nhận chủ quan, có thể đã qua cả tháng."}, {"pattern": "～うちに", "meaning": "trong lúc… (hãy tranh thủ trước khi trạng thái thay đổi)", "form": "Vる・Vている・Vない + うちに ; N の うちに", "explain": "うちに gắn với một khoảng thời gian mà trạng thái còn đang duy trì, kèm hàm ý “tranh thủ kẻo muộn”: trời còn sáng, còn trẻ, chưa quên. Vế sau thường là hành động chủ động hoặc một thay đổi tất yếu.", "examples": [{"jp": "若（わか）いうちに、いろいろな 経験（けいけん）を したいです。", "vi": "Trong lúc còn trẻ, tôi muốn có nhiều trải nghiệm."}, {"jp": "忘（わす）れないうちに、メモして おきます。", "vi": "Trong lúc chưa quên, tôi ghi chú lại."}]}, {"pattern": "～あいだ / ～あいだに", "meaning": "trong suốt khoảng… / trong khoảng… (một thời điểm nào đó)", "form": "Vている・N の + あいだ (suốt khoảng) ; あいだに (tại một điểm trong khoảng)", "explain": "あいだ đi một mình nghĩa là SUỐT toàn bộ khoảng thời gian vế sau cũng kéo dài liên tục; thêm に thì vế sau là một sự kiện xảy ra tại MỘT ĐIỂM trong khoảng đó. Khác biệt nhỏ này là bẫy thi cử kinh điển.", "examples": [{"jp": "母（はは）が 料理（りょうり）を作（つく）っているあいだ、子（こ）どもは 宿題（しゅくだい）を して いた。", "vi": "Trong suốt lúc mẹ nấu ăn, đứa trẻ làm bài tập."}, {"jp": "留守（るす）の あいだに、荷物（にもつ）が 届（とど）いた。", "vi": "Trong lúc vắng nhà (tại một thời điểm nào đó), hành lý đã được giao đến."}]}, {"pattern": "Vた とたん(に)", "meaning": "vừa mới… thì ngay lập tức…", "form": "Động từ thể た + とたん(に) + sự việc bất ngờ", "explain": "とたん chỉ hai sự việc xảy ra SÁT NHAU như phản xạ, vế sau luôn là điều bất ngờ, ngoài ý chí người nói: vừa mở cửa thì mèo chạy ra, vừa đứng dậy thì chóng mặt.", "examples": [{"jp": "ドアを 開（あ）けたとたん、猫（ねこ）が 飛（と）び出（だ）した。", "vi": "Vừa mở cửa thì con mèo phóng ra ngoài."}, {"jp": "立（た）ったとたん、めまいが した。", "vi": "Vừa đứng dậy thì tôi bị chóng mặt ngay."}]}]}, "2": {"title": "Unit 02 · 動詞 A — Động từ A · Mimi kara Oboeru", "intro": "Bài giảng N3 trọng tâm: nhóm mẫu quyết định và trạng thái khách quan — ことにする, ことになる, ようになる.", "points": [{"pattern": "Vる / Vない + ことに します", "meaning": "(tôi) quyết định làm / không làm V", "form": "Động từ thể từ điển・thể ない + ことに します・しました", "explain": "ことにする gói một hành động thành một QUYẾT ĐỊNH của bản thân. Quá khứ ことにしました dùng khi tuyên bố quyết định vừa đưa ra — câu cửa miệng trong họp hành, chia tay, thay đổi kế hoạch.", "examples": [{"jp": "来月（らいげつ）から たばこを やめることに しました。", "vi": "Tôi đã quyết định từ tháng sau sẽ bỏ thuốc lá."}, {"jp": "今日（きょう）は 早（はや）く 帰（かえ）ることに します。", "vi": "Hôm nay tôi quyết định về sớm."}]}, {"pattern": "Vる / Vない + ことに なります", "meaning": "(sự việc) đã được quyết định là… / theo quy định thì…", "form": "Động từ thể từ điển・thể ない + ことに なります・なっています", "explain": "ことになる là “phía bị quyết định”: việc do công ty, quy định, hoàn cảnh quyết định — người nói không phải chủ thể quyết. ことになっています còn nghĩa là QUY ĐỊNH vốn đã như vậy.", "examples": [{"jp": "来月（らいげつ）、大阪（おおさか）へ 転勤（てんきん）することに なりました。", "vi": "Tháng sau tôi sẽ chuyển công tác đến Osaka (công ty đã quyết định)."}, {"jp": "この 部屋（へや）では たばこを 吸（す）わないことに なって います。", "vi": "Phòng này quy định là không hút thuốc."}], "note": "Phân biệt sống còn: することにした = TÔI quyết; することになった = ĐƯỢC quyết (bởi người khác/hoàn cảnh)."}, {"pattern": "Vる + ように なる (nâng cấp)", "meaning": "đến lúc trở nên… (thay đổi dài hạn)", "form": "Động từ thể từ điển + ように なる", "explain": "Ôn lại từ Bài 36 với sắc thái N3: nhấn mạnh kết quả của cả một QUÁ TRÌNH dài — sau nhiều năm luyện tập, sau thời gian dài sống ở Nhật. Hay kết hợp với やっと (cuối cùng thì), 最近 (gần đây).", "examples": [{"jp": "練習（れんしゅう）の おかげで、泳（およ）げるように なりました。", "vi": "Nhờ luyện tập, tôi đã bơi được rồi."}, {"jp": "子（こ）どもが 一人（ひとり）で 着替（きが）えられるように なった。", "vi": "Đứa trẻ đã tự thay quần áo được rồi."}]}]}, "3": {"title": "Tổng hợp 1 · 連用名詞 — Danh từ liên động từ · Mimi kara Oboeru", "intro": "Bài giảng tổng hợp N3: các mẫu diễn tả việc sự việc diễn ra đồng thời và hoàn cảnh đi kèm — 最中, ところに, ついでに.", "points": [{"pattern": "～最中（さいちゅう）に", "meaning": "đang đúng lúc cao trào của… thì (bị xen vào)", "form": "Vている・N の + 最中に + sự việc xen ngang", "explain": "最中 chỉ đỉnh điểm của một quá trình đang diễn ra, và vế sau thường là việc xen ngang gây gián đoạn: đang họp thì điện thoại reo, đang ngủ say thì có động đất.", "examples": [{"jp": "会議（かいぎ）の 最中（さいちゅう）に、電話（でんわ）が 鳴（な）った。", "vi": "Đang giữa cuộc họp thì điện thoại reo."}, {"jp": "寝（ね）ている 最中（さいちゅう）に、地震（じしん）が 起（お）きた。", "vi": "Đang lúc ngủ thì xảy ra động đất."}]}, {"pattern": "Vている ところに / ところへ", "meaning": "đang đúng lúc… thì (ai đó xuất hiện / việc khác ập tới)", "form": "Động từ thể ている + ところに・ところへ・ところを", "explain": "ところに dùng khi một sự kiện thứ hai chen vào đúng khoảnh khắc hành động đang diễn ra — tạo kịch tính cho câu chuyện kể.ところを còn dùng trong câu cảm ơn/xin lỗi trang trọng: お忙しいところを、ありがとうございます.", "examples": [{"jp": "出（で）かけようと している ところに、友達（ともだち）が 来（き）た。", "vi": "Đang lúc tôi sắp ra ngoài thì bạn tôi đến."}, {"jp": "お忙（いそが）しい ところを、お越（こ）しいただき ありがとうございます。", "vi": "Cảm ơn quý khách đã đến dù đang bận rộn ạ."}]}, {"pattern": "～ついでに", "meaning": "nhân tiện (khi làm việc chính thì làm luôn việc phụ)", "form": "Vる・Vた・N の + ついでに", "explain": "ついでに tận dụng một dịp có sẵn để làm thêm việc phụ không tốn công riêng: đi siêu thị nhân tiện ghé bưu điện. Việc chính luôn là hành động di chuyển hoặc một việc đã định sẵn.", "examples": [{"jp": "買（か）い物（もの）の ついでに、郵便局（ゆうびんきょく）に 寄（よ）りました。", "vi": "Nhân tiện đi mua sắm, tôi ghé qua bưu điện."}, {"jp": "駅（えき）へ 行（い）く ついでに、この 手紙（てがみ）を 出（だ）して ください。", "vi": "Nhân tiện ra ga, hãy gửi giúp tôi lá thư này."}]}]}, "4": {"title": "Unit 03 · 形容詞 A — Tính từ A · Mimi kara Oboeru", "intro": "Bài giảng N3 trọng tâm: nhóm mẫu phỏng đoán – tính chất “có vẻ, có mùi” — っぽい, らしい, みたい.", "points": [{"pattern": "～っぽい", "meaning": "có vẻ / có hơi hướng… (ấn tượng cảm tính)", "form": "Danh từ・Động từ gốc ます + っぽい (chia như tính từ -i)", "explain": "っぽい chỉ tính chất cảm nhận bằng trực giác: người trông trẻ con (子供っぽい), vải như lụa, nói năng ra vẻ người lớn. Thường mang sắc thái hơi tiêu cực hoặc thân mật, ít dùng trong văn trang trọng.", "examples": [{"jp": "彼女（かのじょ）は 子（こ）どもっぽいところが ある。", "vi": "Cô ấy có nét hơi trẻ con."}, {"jp": "この 生地（きじ）は 絹（きぬ）っぽいです。", "vi": "Loại vải này có vẻ giống lụa."}]}, {"pattern": "～らしい", "meaning": "đúng chất / ra dáng… (điển hình của một hình mẫu)", "form": "Danh từ + らしい (chia như tính từ -i)", "explain": "らしい sau danh từ nghĩa là “đúng với hình mẫu lý tưởng của danh từ đó”: 男らしい (đúng chất đàn ông), 春らしい天気 (thời tiết đúng chất mùa xuân). Khác っぽい ở chỗ らしい mang sắc thái tích cực, khách quan hơn.", "examples": [{"jp": "今日（きょう）は 春（はる）らしい 暖（あたた）かさです。", "vi": "Hôm nay ấm áp đúng chất mùa xuân."}, {"jp": "彼（かれ）は 彼（かれ）らしい 意見（いけん）を 言（い）った。", "vi": "Anh ấy đã nói ý kiến rất đúng chất của anh ấy."}], "note": "らしい còn một nghĩa khác hẳn: “hình như” (truyền văn suy đoán — 彼は来ないらしい). Cần phân biệt bằng vị trí: sau DANH TỪ = đúng chất; sau THỂ THƯỜNG = hình như."}, {"pattern": "～みたいだ / ～みたいな", "meaning": "giống như / dường như…", "form": "N・Thể thường + みたいだ ; みたいな + Danh từ ; みたいに + Động từ", "explain": "みたい là phiên bản thân mật của ようだ (Bài 47): ví von một vật với vật khác, hoặc phỏng đoán nhẹ. Văn viết và văn trang trọng phải dùng よう, hội thoại hằng ngày dùng みたい.", "examples": [{"jp": "彼女（かのじょ）の 日本語（にほんご）は 日本人（にほんじん）みたいです。", "vi": "Tiếng Nhật của cô ấy như người Nhật vậy."}, {"jp": "雨（あめ）が 降（ふ）るみたいです。", "vi": "Hình như trời sắp mưa."}]}]}, "5": {"title": "Tổng hợp 2 · 形容詞＋まる/める — Tính từ + まる/める · Mimi kara Oboeru", "intro": "Bài giảng tổng hợp N3: cách người Nhật biến cảm xúc thành động từ và mẫu diễn tả biểu hiện cảm xúc của người thứ ba — ～がる, ～げ.", "points": [{"pattern": "～がる", "meaning": "(người thứ ba) tỏ ra / có biểu hiện…", "form": "Tính từ -i bỏ い・Tính từ -na・Vたい bỏ い + がる (động từ nhóm 1)", "explain": "がる gắn sau từ chỉ cảm xúc/cảm giác để miêu tả BIỂU HIỆN BÊN NGOÀI của người thứ ba: ta không thể khẳng định cảm xúc bên trong của người khác, chỉ được nói họ “tỏ ra” như vậy. Đây là nguyên tắc ngữ pháp – văn hóa rất Nhật.", "examples": [{"jp": "子（こ）どもが 新（あたら）しい おもちゃを ほしがって います。", "vi": "Đứa trẻ đang tỏ ra muốn món đồ chơi mới."}, {"jp": "彼（かれ）は 恥（は）ずかしがって、何（なに）も 話（はな）さなかった。", "vi": "Anh ấy tỏ ra xấu hổ nên chẳng nói gì."}], "note": "Không dùng がる cho chính mình ở thì hiện tại khẳng định (×私は行きたがります về bản thân là sai ngữ dụng) — với mình thì dùng thẳng たい."}, {"pattern": "～げ", "meaning": "trông có vẻ… (qua nét mặt, thái độ)", "form": "Tính từ -i bỏ い・Tính từ -na + げ + な/に", "explain": "げ biến cảm xúc thành “vẻ bề ngoài quan sát được”: 悲しげな顔 (gương mặt buồn buồn), 嬉しげに笑う (cười với vẻ vui). Gần nghĩa そうですが trang trọng và văn chương hơn, hay dùng trong văn viết.", "examples": [{"jp": "彼女（かのじょ）は 寂（さび）しげに 窓（まど）の 外（そと）を 見（み）て いた。", "vi": "Cô ấy nhìn ra ngoài cửa sổ với vẻ cô đơn."}, {"jp": "彼（かれ）は 自信（じしん）ありげに 答（こた）えた。", "vi": "Anh ấy trả lời với vẻ đầy tự tin."}]}]}, "6": {"title": "Unit 04 · 名詞 B — Danh từ B · Mimi kara Oboeru", "intro": "Bài giảng N3 trọng tâm: nhóm mẫu điều kiện – hậu quả trong lập luận: ばよかった, てもかまわない, しかない.", "points": [{"pattern": "Vば よかった / Vなければ よかった", "meaning": "giá mà đã làm / đã không làm… (hối tiếc)", "form": "Động từ thể ば + よかったです ; Thể ない + なければ よかった", "explain": "～ばよかった là mẫu HỐI TIẾC về quá khứ: việc đã rồi, nói “giá mà lúc đó…”. Phủ định của nó なければよかった tiếc vì ĐÃ làm điều không nên. Luôn đi với cảm xúc tiếc nuối, tự trách.", "examples": [{"jp": "もっと 早（はや）く 出（で）かければ よかった。", "vi": "Giá mà tôi ra khỏi nhà sớm hơn."}, {"jp": "あんなことを 言（い）わなければ よかった。", "vi": "Giá mà tôi đã không nói điều như thế."}]}, {"pattern": "Vても かまいません", "meaning": "làm V cũng không sao (cho phép – văn viết)", "form": "Động từ thể て + も かまいません", "explain": "かまいません là phiên bản trang trọng, văn bản của もいいです: quy định, thông báo dùng mẫu này để cho phép chính thức. Ở dạng câu hỏi てもかまいませんか cũng lịch sự hơn てもいいですか.", "examples": [{"jp": "ここに 車（くるま）を 止（と）めても かまいません。", "vi": "Đỗ xe ở đây cũng không sao."}, {"jp": "質問（しつもん）が あれば、授業中（じゅぎょうちゅう）でも 聞（き）いても かまいません。", "vi": "Nếu có thắc mắc, cứ hỏi ngay trong giờ học cũng được."}]}, {"pattern": "Vる しかない / N しかない", "meaning": "chỉ còn cách… / đành phải…", "form": "Động từ thể từ điển + しかない ; Danh từ + しかない", "explain": "しかない khẳng định KHÔNG CÒN LỰA CHỌN NÀO KHÁC: hoặc là giới hạn số lượng (tiền chỉ còn…), hoặc là sự bất đắc dĩ phải chấp nhận một hành động (đành đi bộ).", "examples": [{"jp": "バスが ないから、歩（ある）いて 行（い）くしかない。", "vi": "Không có xe buýt nên đành phải đi bộ."}, {"jp": "財布（さいふ）には 千円（せんえん）しかない。", "vi": "Trong ví chỉ còn có 1.000 yên."}]}]}, "7": {"title": "Unit 05 · 動詞 B — Động từ B · Mimi kara Oboeru", "intro": "Bài giảng N3 trọng tâm: thể sai khiến bị động và trạng thái kéo dài không mong muốn — ～させられる, ～っぱなし.", "points": [{"pattern": "V(使役受身) せられる・させられる", "meaning": "bị bắt phải làm V (sai khiến bị động)", "form": "Nhóm 1: hàng あ + せられる/される ; Nhóm 2: させられる ; Nhóm 3: させられる・こさせられる", "explain": "Sai khiến bị động gói hai lớp nghĩa: vừa BỊ ĐỘNG vừa BỊ BẮT BUỘC — người nói là nạn nhân của sự ép buộc: bị bắt uống, bị bắt chờ, bị bắt làm thêm giờ. Nhóm 1 có dạng rút gọn ～される (飲まされる) dùng phổ biến hơn.", "examples": [{"jp": "上司（じょうし）に 残業（ざんぎょう）させられた。", "vi": "Tôi bị cấp trên bắt làm thêm giờ."}, {"jp": "子（こ）どもの とき、ピアノを 習（なら）わされた。", "vi": "Hồi nhỏ, tôi bị bắt học piano."}]}, {"pattern": "Vっぱなし", "meaning": "để nguyên trạng thái… (bỏ mặc, không xử lý)", "form": "Động từ gốc ます + っぱなし", "explain": "っぱなし chỉ một trạng thái bị BỎ MẶC kéo dài mà lẽ ra phải kết thúc: mở cửa để nguyên, bật TV để nguyên, để xe ngoài mưa. Luôn hàm ý cẩu thả, đáng chê trách.", "examples": [{"jp": "エアコンを つけっぱなしで 出（で）かけて しまった。", "vi": "Tôi đã ra ngoài mà để điều hòa bật nguyên."}, {"jp": "窓（まど）を 開（あ）けっぱなしに しないで ください。", "vi": "Đừng để cửa sổ mở nguyên như vậy."}], "note": "So sánh ba anh em: ておく (để có chủ đích tốt), てある (đã sắp đặt sẵn), っぱなし (bỏ mặc vô trách nhiệm)."}]}, "8": {"title": "Unit 06 · カタカナ A — Từ mượn A · Mimi kara Oboeru", "intro": "Bài giảng N3 trọng tâm: nhóm trợ từ nâng cao cho quan hệ và tương tác — によって, に対して.", "points": [{"pattern": "～によって / ～による", "meaning": "tùy theo… / do… / bởi… (ba nghĩa lớn)", "form": "Danh từ + によって・による + Danh từ", "explain": "によって là trợ từ đa năng nhất N3: (1) TÙY THEO — kết quả thay đổi theo điều kiện (人によって意見が違う); (2) NGUYÊN NHÂN — do thiên tai, sự kiện; (3) BỞI — tác nhân trong câu bị động trang trọng. Nghĩa nào do ngữ cảnh quyết định.", "examples": [{"jp": "考（かんが）え方（かた）は 人（ひと）によって 違（ちが）います。", "vi": "Cách suy nghĩ tùy theo từng người mà khác nhau."}, {"jp": "この 橋（はし）は 大雨（おおあめ）によって 壊（こわ）れた。", "vi": "Cây cầu này bị phá hủy do mưa lớn."}]}, {"pattern": "～に対（たい）して / ～に対（たい）する", "meaning": "đối với… / hướng vào đối tượng nào", "form": "Danh từ + に対して・に対する + Danh từ", "explain": "に対して chỉ thái độ, hành động HƯỚNG VỀ một đối tượng cụ thể: lễ phép đối với khách, ý kiến đối với kế hoạch, câu hỏi đối với giáo viên. Thường đi với thái độ hai chiều (thân thiện/lạnh nhạt, đồng ý/phản đối).", "examples": [{"jp": "お客（きゃく）さんに 対（たい）して 失礼（しつれい）な 言（い）い方（かた）を しては いけません。", "vi": "Không được nói năng thiếu lễ phép đối với khách hàng."}, {"jp": "この 計画（けいかく）に 対（たい）して、反対意見（はんたいいけん）が 多（おお）い。", "vi": "Đối với kế hoạch này, có nhiều ý kiến phản đối."}], "note": "Phân biệt について (về — chủ đề thông tin) với に対して (đối với — thái độ hướng vào đối tượng): 日本語について勉強する (học về tiếng Nhật) khác 日本語に対して… (không tự nhiên)."}]}, "9": {"title": "Unit 07 · 形容詞 B — Tính từ B · Mimi kara Oboeru", "intro": "Bài giảng N3 trọng tâm: danh từ hóa tính từ (～さ) và mức độ tột cùng (～ほど, ～くらい).", "points": [{"pattern": "形容詞の 名詞化：～さ", "meaning": "độ / mức… (biến tính từ thành danh từ đo lường được)", "form": "い形 bỏ い + さ ; な形 + さ", "explain": "さ biến tính từ thành danh từ chỉ MỨC ĐỘ khách quan, đo được: cao → độ cao, nặng → trọng lượng. Dùng trong văn kỹ thuật, miêu tả sản phẩm, cảm nhận đầu tiên về một tính chất (この嬉しさ = niềm vui này).", "examples": [{"jp": "この 荷物（にもつ）の 重（おも）さは 10（じゅう）キロです。", "vi": "Trọng lượng của hành lý này là 10 kg."}, {"jp": "富士山（ふじさん）の 高（たか）さを 初（はじ）めて 知（し）った。", "vi": "Tôi lần đầu biết chiều cao của núi Phú Sĩ."}], "note": "Nhóm ～み (深み, 温かみ) chỉ tính chất cảm nhận chủ quan, sâu sắc — ít dùng và mang màu văn chương hơn さ."}, {"pattern": "～ほど", "meaning": "đến mức… / càng… (mức độ cực đoan)", "form": "V・い形・な形 + ほど ; Danh từ + ほど", "explain": "ほど chỉ mức độ cao tới ngưỡng làm chuẩn so sánh: bận đến mức không ngủ được, ngon đến mức muốn ăn mỗi ngày. Dạng phủ định ～ほど～ない là so sánh cao nhất trá hình: “không có gì … bằng” (Bài N2 sẽ đào sâu).", "examples": [{"jp": "立（た）てないほど 疲（つか）れました。", "vi": "Tôi mệt đến mức không đứng dậy nổi."}, {"jp": "今日（きょう）は 昨日（きのう）ほど 寒（さむ）くないです。", "vi": "Hôm nay không lạnh đến mức như hôm qua."}]}, {"pattern": "～くらい / ～ぐらい", "meaning": "đến mức… / khoảng chừng…", "form": "V・い形 + くらい ; Số lượng + くらい (khoảng)", "explain": "くらい có hai đời sống: chỉ mức độ cảm tính (泣きたいくらい = đến mức muốn khóc) và chỉ lượng xấp xỉ (1時間くらい = khoảng 1 tiếng). Trong văn trang trọng, ほど được ưa hơn cho mức độ cực đoan.", "examples": [{"jp": "びっくりするくらい 景色（けしき）が きれいだった。", "vi": "Phong cảnh đẹp đến mức khiến tôi kinh ngạc."}, {"jp": "駅（えき）まで 歩（ある）いて 15（じゅうご）分（ふん）くらい かかります。", "vi": "Đi bộ ra ga mất khoảng 15 phút."}]}]}, "10": {"title": "Unit 08 · 副詞 A — Trạng từ A · Mimi kara Oboeru", "intro": "Bài giảng N3 trọng tâm: các trợ từ nhấn mạnh sắc thái — こそ, さえ, ても (dù cho ở mức cực đoan).", "points": [{"pattern": "～こそ", "meaning": "chính… mới là / chính là… (nhấn mạnh độc tôn)", "form": "Danh từ・Câu + こそ", "explain": "こそ tước ngôi nhấn mạnh của は/が và trao cho từ đứng trước nó: CHÍNH người này, CHÍNH lần này. Hay gặp trong câu quyết tâm (今度こそ = chính lần này nhất định…) và lời cảm ơn sâu sắc (ありがとうこそ…).", "examples": [{"jp": "今度（こんど）こそ 試験（しけん）に 受（う）かります。", "vi": "Chính lần này tôi nhất định sẽ đậu kỳ thi."}, {"jp": "こちらこそ、よろしく お願（ねが）いします。", "vi": "Chính tôi mới là người phải nhờ anh giúp đỡ ạ."}]}, {"pattern": "～さえ", "meaning": "ngay cả / thậm chí… (đưa ví dụ cực đoan)", "form": "Danh từ + さえ ; Vて + さえ", "explain": "さえ nêu một trường hợp CỰC ĐOAN nhất để suy ra phần còn lại: ngay cả trẻ con cũng hiểu (thì ai cũng hiểu), thậm chí tên cũng quên. Thường đi với kết luận khái quát phía sau.", "examples": [{"jp": "この 問題（もんだい）は 子（こ）どもでさえ わかります。", "vi": "Bài toán này ngay cả trẻ con cũng hiểu."}, {"jp": "忙（いそが）しくて、食事（しょくじ）をする 時間（じかん）さえ なかった。", "vi": "Tôi bận đến mức thậm chí thời gian ăn cũng không có."}], "note": "Cặp mẫu điều kiện ～さえ～ば (chỉ cần… là đủ) sẽ hoàn thiện ở N2: お金さえあれば = chỉ cần có tiền là được."}, {"pattern": "～ても (cực đoan)", "meaning": "dù có… đến đâu cũng (vẫn không đổi)", "form": "Vて・い形くて・な形でも + kết quả bất biến (nâng cấp Bài 25)", "explain": "Ở N3, ても được mở rộng với các từ lượng cực đoan (いくら, どんなに, たとえ) để nhấn mạnh mọi trường hợp đều bất biến. たとえ～ても là khung “dù cho có… đi nữa” trang trọng trong văn viết.", "examples": [{"jp": "たとえ 雨（あめ）が 降（ふ）っても、試合（しあい）は 行（おこな）われます。", "vi": "Dù cho trời mưa đi nữa, trận đấu vẫn diễn ra."}, {"jp": "どんなに 忙（いそが）しくても、家族（かぞく）との 時間（じかん）は 大切（たいせつ）に したい。", "vi": "Dù bận đến đâu, tôi vẫn muốn trân trọng thời gian với gia đình."}]}]}, "11": {"title": "Unit 09 · 名詞 C — Danh từ C · Mimi kara Oboeru", "intro": "Bài giảng N3 trọng tâm: ba trợ từ quan hệ kinh điển — について (về), にとって (đối với góc nhìn), として (với tư cách).", "points": [{"pattern": "～について", "meaning": "về… (chủ đề của thông tin, nghiên cứu, suy nghĩ)", "form": "Danh từ + について + 話す・調べる・考える・知る…", "explain": "について gắn chủ đề cho các hành động THÔNG TIN: nói về,調べ về, nghĩ về, bài thuyết trình về. Dạng bổ nghĩa là についての + Danh từ (日本についての本).", "examples": [{"jp": "日本の 文化（ぶんか）について 調（しら）べて います。", "vi": "Tôi đang tìm hiểu về văn hóa Nhật Bản."}, {"jp": "将来（しょうらい）について 先生（せんせい）に 相談（そうだん）しました。", "vi": "Tôi đã trao đổi với thầy về tương lai."}]}, {"pattern": "～にとって", "meaning": "đối với… (theo góc nhìn, sự đánh giá của ai)", "form": "Danh từ (người/tổ chức) + にとって + đánh giá", "explain": "にとって đặt LĂNG KÍNH đánh giá: một việc là quan trọng/khó/cần thiết XÉT THEO quan điểm của ai. Vế sau luôn là phán đoán chủ quan (大切だ, 難しい, 必要だ) — không dùng cho sự thật khách quan.", "examples": [{"jp": "わたしにとって、家族（かぞく）が いちばん 大切（たいせつ）です。", "vi": "Đối với tôi, gia đình là quan trọng nhất."}, {"jp": "外国人（がいこくじん）にとって、漢字（かんじ）は 難（むずか）しいです。", "vi": "Đối với người nước ngoài, chữ Hán rất khó."}], "note": "Ba anh em cần phân biệt: について = về (chủ đề); にとって = đối với (góc đánh giá); に対して = đối với (thái độ hướng vào đối tượng)."}, {"pattern": "～として", "meaning": "với tư cách là… / coi như là…", "form": "Danh từ + として", "explain": "として xác định TƯ CÁCH, VAI TRÒ mà một người/vật đảm nhiệm trong câu: đi Nhật với tư cách lưu học sinh, được biết đến như một nhà văn, dùng như một công cụ.", "examples": [{"jp": "彼（かれ）は 留学生（りゅうがくせい）として 日本（にほん）へ 来（き）ました。", "vi": "Anh ấy đến Nhật với tư cách là du học sinh."}, {"jp": "この 建物（たてもの）は 博物館（はくぶつかん）として 使（つか）われて います。", "vi": "Tòa nhà này được sử dụng làm bảo tàng."}]}]}, "12": {"title": "Unit 10 · 動詞 C — Động từ C · Mimi kara Oboeru", "intro": "Bài giảng N3 trọng tâm: động từ phức hợp chỉ giai đoạn hành động — ～始める, ～続ける, ～終わる, ～かける.", "points": [{"pattern": "V(ます stem) 始（はじ）める / 続（つづ）ける / 終（お）わる", "meaning": "bắt đầu làm / tiếp tục làm / làm xong", "form": "Động từ gốc ます + 始める・続ける・終わる・出す", "explain": "Động từ phức hợp gắn GIAI ĐOẠN vào hành động chính: 始める = điểm mở đầu, 続ける = duy trì liên tục, 終わる = điểm kết thúc. 出す mang nghĩa bỗng nhiên bắt đầu (降り出す = đổ mưa bất chợt).", "examples": [{"jp": "雨（あめ）が 降（ふ）り始（はじ）めました。", "vi": "Trời bắt đầu mưa."}, {"jp": "彼（かれ）は 3（さん）時間（じかん）も 話（はな）し続（つづ）けた。", "vi": "Anh ấy nói liên tục suốt 3 tiếng."}, {"jp": "レポートを 書（か）き終（お）わったら、帰（かえ）ります。", "vi": "Viết xong báo cáo thì tôi về."}]}, {"pattern": "V(ます stem) かける / かけの + N", "meaning": "làm dở dang… / đang làm nửa chừng", "form": "Động từ gốc ます + かける ; かけの + Danh từ", "explain": "かける chỉ hành động MỚI BẮT ĐẦU hoặc ĐANG DỞ DANG bị dừng lại: nói dở câu, ăn dở bữa. Dạng danh từ かけの (食べかけのパン = ổ bánh mì ăn dở) rất hay gặp khi miêu tả hiện trường.", "examples": [{"jp": "言（い）いかけて、やめた。", "vi": "Tôi định nói rồi lại thôi (nói dở chừng)."}, {"jp": "机（つくえ）の 上（うえ）に 読（よ）みかけの 本（ほん）が 置（お）いて ある。", "vi": "Trên bàn để cuốn sách đang đọc dở."}]}]}, "13": {"title": "Unit 11 · カタカナ B — Từ mượn B · Mimi kara Oboeru", "intro": "Bài giảng N3 trọng tâm: gia đình ～わけ — hệ thống mẫu suy luận, phủ định suy luận cực kỳ đặc trưng của tiếng Nhật.", "points": [{"pattern": "～わけです", "meaning": "hèn gì / thảo nào / tức là… (kết luận dễ hiểu)", "form": "Thể thường + わけです", "explain": "わけです dùng khi người nói ĐÃ HIỂU RA lý do và thấy sự việc là đương nhiên: thấy ai nói tiếng Nhật giỏi thì “hèn gì, anh ấy từng sống ở Nhật”. Cũng dùng để diễn giải lại ý: つまり～わけです (tức là…).", "examples": [{"jp": "日本（にほん）に 10（じゅう）年（ねん） 住（す）んで いたんです。日本語（にほんご）が 上手（じょうず）なわけです。", "vi": "Anh ấy đã sống ở Nhật 10 năm. Hèn gì tiếng Nhật giỏi."}, {"jp": "つまり、反対（はんたい）というわけですね。", "vi": "Tức là anh phản đối, đúng không ạ?"}]}, {"pattern": "～わけでは ありません / ～わけが ありません", "meaning": "không hẳn là… (phủ định một phần) / không thể nào… (phủ định hoàn toàn)", "form": "Thể thường + わけでは ありません ; Thể thường + わけが ありません", "explain": "わけではない phủ định NHẸ một phần: không hẳn là ghét (chỉ là không giỏi). わけがない phủ định TUYỆT ĐỐI khả năng: đời nào có chuyện đó. Nhầm hai mẫu này làm câu nói thay đổi hẳn sắc thái.", "examples": [{"jp": "嫌（きら）いなわけでは ありません。ただ、苦手（にがて）なんです。", "vi": "Không hẳn là tôi ghét. Chỉ là tôi không giỏi thôi."}, {"jp": "彼（かれ）が うそを つくわけが ありません。", "vi": "Không thể nào anh ấy lại nói dối."}]}, {"pattern": "～わけには いきません", "meaning": "không thể làm V (vì lý do xã hội, đạo lý)", "form": "Động từ thể từ điển + わけには いきません ; Vない わけには いきません = không thể không làm", "explain": "わけにはいかない KHÔNG nói về khả năng vật lý mà về LẼ THƯỜNG TÌNH: đã hứa thì không thể không giữ, là trưởng nhóm thì không thể bỏ về. Dạng kép ないわけにはいかない nghĩa là “không thể không làm” (bắt buộc về mặt xã hội).", "examples": [{"jp": "約束（やくそく）したから、行（い）かないわけには いきません。", "vi": "Vì đã hứa rồi nên tôi không thể không đi."}, {"jp": "みんなが 働（はたら）いているのに、自分（じぶん）だけ 休（やす）むわけには いかない。", "vi": "Mọi người đang làm việc, tôi không thể một mình nghỉ được."}]}]}, "14": {"title": "Tổng hợp 3 · 料理の動詞 — Động từ nấu ăn · Mimi kara Oboeru", "intro": "Bài giảng tổng hợp N3: hai mẫu về đích đến của quá trình — ～たて (vừa mới làm xong, còn nguyên chất lượng) và ～ようにする (rèn thói quen).", "points": [{"pattern": "V(ます stem) たて", "meaning": "vừa mới làm V xong (còn tươi nguyên, nguyên vẹn)", "form": "Động từ gốc ます + たて + の + Danh từ", "explain": "たて gắn vào động từ tạo tính chất “mới tinh vừa hoàn thành”: bánh vừa nướng, nhà vừa xây, cá vừa câu. Luôn đi kèm cảm giác chất lượng cao nhất tại thời điểm vừa xong.", "examples": [{"jp": "焼（や）きたての パンは おいしいです。", "vi": "Bánh mì vừa mới nướng rất ngon."}, {"jp": "この 家（いえ）は 建（た）てたてで、まだ だれも 住（す）んで いません。", "vi": "Ngôi nhà này vừa mới xây xong, chưa ai ở."}]}, {"pattern": "Vる / Vない + ように する (rèn thói quen)", "meaning": "cố gắng tạo thói quen… (nhắc lại có hệ thống)", "form": "Động từ thể từ điển・thể ない + ように する・しています", "explain": "Ôn tập nâng cao mẫu Bài 36: ở N3, ようにする thường xuất hiện trong lời khuyên sức khỏe, hướng dẫn nghề nghiệp — nơi việc DUY TRÌ thói quen là trọng tâm. Kết hợp phó từ できるだけ (càng nhiều càng tốt) rất tự nhiên.", "examples": [{"jp": "できるだけ 歩（ある）くように して います。", "vi": "Tôi cố gắng đi bộ càng nhiều càng tốt."}, {"jp": "夜（よる）更（ふ）かしを しないように しましょう。", "vi": "Chúng ta hãy cố gắng không thức khuya nhé."}]}]}, "15": {"title": "Unit 12 · 副詞 B・連体詞・接続詞 — Trạng từ B, định ngữ, liên từ · Mimi kara Oboeru", "intro": "Bài giảng N3 khép lại với ba trợ từ giới hạn – nhấn mạnh nâng cao: ばかり, だけ (sắc thái), でも (thậm chí).", "points": [{"pattern": "～ばかり", "meaning": "toàn là… / cứ mãi… (thiên lệch, phàn nàn)", "form": "Danh từ + ばかり ; Vて + ばかり います", "explain": "ばかり chỉ sự THIÊN LỆCH quá mức về một phía: toàn ăn đồ ngọt, cứ chơi game mãi. Gần như luôn mang sắc thái phê phán, khác だけ trung tính. てばかりいる chỉ người cứ lặp đi lặp lại một hành vi.", "examples": [{"jp": "うちの 子（こ）は ゲームばかり して います。", "vi": "Con tôi cứ chơi game suốt."}, {"jp": "甘（あま）い 物（もの）ばかり 食（た）べると、太（ふと）りますよ。", "vi": "Cứ ăn toàn đồ ngọt thì sẽ béo đấy."}], "note": "Phân biệt: パンだけ食べる = chỉ ăn bánh mì (sự thật); パンばかり食べる = toàn ăn bánh mì (phàn nàn sự thiên lệch)."}, {"pattern": "～だけ (sắc thái nâng cao)", "meaning": "càng… càng tốt / hết mức có thể", "form": "Vる だけ + V ; できるだけ", "explain": "Ngoài nghĩa “chỉ”, だけ còn xuất hiện trong khung できるだけ (càng… càng tốt, hết mức) và VるだけV (làm bao nhiêu tùy thích): 食べたいだけ食べていい = cứ ăn bao nhiêu tùy thích.", "examples": [{"jp": "休（やす）みは できるだけ 家族（かぞく）と 過（す）ごしたいです。", "vi": "Ngày nghỉ tôi muốn dành cho gia đình càng nhiều càng tốt."}, {"jp": "今日（きょう）は 思（おも）うだけ 泣（な）いても いい。", "vi": "Hôm nay em cứ khóc bao nhiêu tùy thích cũng được."}]}, {"pattern": "～でも (thậm chí – cực đoan)", "meaning": "ngay cả / thậm chí (nêu cực đoan để khái quát)", "form": "Danh từ + でも ; 疑問詞 + でも (bất cứ…)", "explain": "でも sau danh từ nêu trường hợp cực đoan như さえ: 子どもでも わかる (ngay cả trẻ con cũng hiểu). Sau từ hỏi, でも tạo nghĩa phổ quát: 何でも (bất cứ cái gì), どこでも (bất cứ đâu) — trợ thủ đắc lực trong hội thoại dịch vụ.", "examples": [{"jp": "そんな うそは 子（こ）どもでも 見破（みやぶ）ります。", "vi": "Lời nói dối như thế ngay cả trẻ con cũng nhìn thấu."}, {"jp": "何（なん）でも 聞（き）いて ください。", "vi": "Anh cứ hỏi bất cứ điều gì ạ."}]}]}}, "N2": {"1": {"title": "Unit 01 · 名詞A — Danh từ A · Mimi kara Oboeru", "intro": "Bài giảng ngữ pháp N2 trọng tâm số 1: nhóm mẫu phạm vi – ngoại lệ trang trọng: を問わず, をはじめ, に限り, を除いて.", "points": [{"pattern": "～を問（と）わず", "meaning": "bất kể / không phân biệt…", "form": "Danh từ + を問わず", "explain": "を問わず phủ định mọi điều kiện phân biệt: tuổi tác, kinh nghiệm, quốc tịch đều không thành vấn đề. Là ngôn ngữ của thông báo tuyển dụng, quy định tham dự trang trọng.", "examples": [{"jp": "経験（けいけん）を 問（と）わず、だれでも 応募（おうぼ）できます。", "vi": "Bất kể kinh nghiệm, ai cũng có thể ứng tuyển."}, {"jp": "年齢（ねんれい）・性別（せいべつ）を 問（と）わず、参加（さんか）できます。", "vi": "Không phân biệt tuổi tác, giới tính đều tham gia được."}]}, {"pattern": "～をはじめ（として）", "meaning": "bắt đầu từ… / tiêu biểu là… và nhiều nữa", "form": "Danh từ + をはじめ（として）+ liệt kê mở rộng", "explain": "をはじめ nêu một thành viên TIÊU BIỂU đứng đầu danh sách hàm ý còn nhiều thành phần tương tự theo sau — khác はじめに (đầu tiên, trình tự thời gian) ở chỗ đây là liệt kê phạm vi.", "examples": [{"jp": "日本（にほん）には、東京（とうきょう）をはじめ、大きな 都市（とし）が たくさん あります。", "vi": "Ở Nhật, tiêu biểu là Tokyo, có rất nhiều thành phố lớn."}, {"jp": "校長（こうちょう）をはじめ、先生方（せんせいがた）に お礼（れい）を 申（もう）し上（あ）げます。", "vi": "Tôi xin cảm ơn thầy hiệu trưởng và toàn thể quý thầy cô."}]}, {"pattern": "～に限（かぎ）り / ～に限（かぎ）る", "meaning": "chỉ giới hạn ở… / chỉ riêng…", "form": "Danh từ + に限り・に限る", "explain": "に限り giới hạn phạm vi hiệu lực một cách chính thức: chỉ hôm nay, chỉ dành cho thành viên, chỉ lần này. Hay thấy trong thông báo bán hàng, ưu đãi, quy định.", "examples": [{"jp": "本日（ほんじつ）に 限（かぎ）り、全品（ぜんぴん） 2（に）割（わり）引（び）きです。", "vi": "Chỉ riêng hôm nay, toàn bộ sản phẩm giảm 20%."}, {"jp": "会員（かいいん）に 限（かぎ）り、無料（むりょう）で 参加（さんか）できます。", "vi": "Chỉ giới hạn cho hội viên mới được tham gia miễn phí."}]}, {"pattern": "～を除（のぞ）いて", "meaning": "ngoại trừ… / trừ… ra", "form": "Danh từ + を除いて・を除き", "explain": "を除いて loại một phần tử khỏi phạm vi phán đoán, phần còn lại đồng loạt như nhau. Dạng văn viết rút gọn là を除き.", "examples": [{"jp": "日曜日（にちようび）を 除（のぞ）いて、毎日（まいにち） 開（あ）いて います。", "vi": "Ngoại trừ chủ nhật, ngày nào cũng mở cửa."}, {"jp": "彼（かれ）を 除（のぞ）いて、全員（ぜんいん） 賛成（さんせい）した。", "vi": "Trừ anh ấy ra, tất cả đều tán thành."}]}]}, "2": {"title": "Unit 02 · 動詞A — Động từ A · Mimi kara Oboeru", "intro": "Bài giảng N2 trọng tâm: nhóm mẫu “không thể không / đành phải” — ざるをえない, ないわけにはいかない, かねる・かねない.", "points": [{"pattern": "Vない + ざるをえない", "meaning": "không thể không làm / đành phải làm V", "form": "Động từ thể ない bỏ い + ざるをえない (する→せざるをえない)", "explain": "ざるをえない là mẫu văn viết trang trọng của “bất đắc dĩ phải làm”: hoàn cảnh ép buộc, dù không muốn vẫn phải làm. Sắc thái nặng và chính thức hơn なければならない nhiều.", "examples": [{"jp": "上司（じょうし）の 命令（めいれい）では、行（い）かざるをえない。", "vi": "Đã là lệnh của cấp trên thì đành phải đi."}, {"jp": "事実（じじつ）を 話（はな）さざるをえなくなった。", "vi": "Tôi rơi vào tình thế đành phải nói ra sự thật."}]}, {"pattern": "Vない わけには いかない", "meaning": "không thể không làm V (vì lẽ xã hội)", "form": "Động từ thể ない + わけには いかない", "explain": "Phủ định kép tạo khẳng định bắt buộc: đã ở vào vị thế/lời hứa này thì về mặt đạo lý không thể không làm. Khác ざるをえない ở chỗ nhấn mạnh RÀO CẢN XÃ HỘI, thể diện chứ không phải hoàn cảnh vật chất.", "examples": [{"jp": "みんなに 約束（やくそく）した以上（いじょう）、やらないわけには いかない。", "vi": "Đã hứa với mọi người rồi thì không thể không làm."}, {"jp": "部下（ぶか）の ミスは、上司（じょうし）として 責任（せきにん）を 取（と）らないわけには いかない。", "vi": "Lỗi của cấp dưới, với tư cách cấp trên tôi không thể không chịu trách nhiệm."}]}, {"pattern": "V(ます stem) かねる / かねない", "meaning": "khó mà làm được (từ chối khéo) / có nguy cơ sẽ… (điều xấu)", "form": "Động từ gốc ます + かねる・かねない", "explain": "かねる là cách TỪ CHỐI KHIÊM NHƯỜNG trong công vụ: 分かりかねます = tôi khó mà biết được (xin lỗi không trả lời được). かねない là cảnh báo một kết quả XẤU có thể xảy ra: 事故になりかねない = có nguy cơ thành tai nạn.", "examples": [{"jp": "その 件（けん）については、お答（こた）えしかねます。", "vi": "Về việc đó, tôi xin phép khó mà trả lời được ạ."}, {"jp": "このままでは、大事故（だいじこ）に なりかねない。", "vi": "Cứ thế này thì có nguy cơ trở thành tai nạn lớn."}], "note": "Hai từ trông giống nhau nhưng sắc thái ngược chiều: かねる = KHÔNG làm được (lịch sự); かねない = CÓ THỂ xảy ra (điều xấu)."}]}, "3": {"title": "Unit 03 · 形容詞A — Tính từ A · Mimi kara Oboeru", "intro": "Bài giảng N2 trọng tâm: nhóm tiếp vĩ từ chỉ khuynh hướng — がち, 気味, っぽい (nâng cấp).", "points": [{"pattern": "～がち", "meaning": "hay / thường có xu hướng… (tiêu cực)", "form": "Danh từ・Động từ gốc ます + がち", "explain": "がち chỉ một KHUYNH HƯỚNG lặp lại không mong muốn: hay ốm, hay quên, trời hay âm u. Gần như luôn đi với điều tiêu cực hoặc đáng lo, rất hợp văn miêu tả, báo cáo.", "examples": [{"jp": "最近（さいきん）、電車（でんしゃ）は 遅（おく）れがちです。", "vi": "Dạo gần đây tàu điện hay bị chậm."}, {"jp": "彼（かれ）は 病気（びょうき）がちで、よく 会社（かいしゃ）を 休（やす）む。", "vi": "Anh ấy hay ốm nên thường nghỉ làm."}]}, {"pattern": "～気味（ぎみ）", "meaning": "hơi có cảm giác / chiều hướng…", "form": "Danh từ・Động từ gốc ます + 気味", "explain": "気味 diễn tả trạng thái “hơi hơi” ở mức cảm nhận: hơi mệt, hơi thiếu ngủ, hơi cảm. Nhẹ và ngắn hạn hơn がち (khuynh hướng lâu dài).", "examples": [{"jp": "少（すこ）し 疲（つか）れ気味（ぎみ）です。", "vi": "Tôi hơi có cảm giác mệt."}, {"jp": "風邪（かぜ）気味（ぎみ）なので、早（はや）く 寝（ね）ます。", "vi": "Tôi hơi có triệu chứng cảm nên đi ngủ sớm."}]}, {"pattern": "～っぽい (nâng cấp văn viết)", "meaning": "có tính / trông như… (ấn tượng mạnh)", "form": "Danh từ・Động từ gốc ます + っぽい", "explain": "Ôn lại từ N3 với các kết hợp trừu tượng ở N2: 忘れっぽい (hay quên), 怒りっぽい (hay nổi nóng), 安っぽい (trông rẻ tiền). っぽい gắn được cả vào gốc động từ để chỉ tính cách, thói quen của con người.", "examples": [{"jp": "祖父（そふ）は 忘（わす）れっぽく なった。", "vi": "Ông tôi trở nên hay quên."}, {"jp": "その かばんは 安（やす）っぽく 見（み）える。", "vi": "Cái túi đó trông rẻ tiền."}]}]}, "4": {"title": "Unit 04 · 名詞B — Danh từ B · Mimi kara Oboeru", "intro": "Bài giảng N2 trọng tâm: nhóm mẫu căn cứ – tiêu chuẩn trong văn lập luận: に基づいて, をもとに, に沿って, に応じて.", "points": [{"pattern": "～に基（もと）づいて / ～に基（もと）づく", "meaning": "dựa trên / căn cứ vào…", "form": "Danh từ + に基づいて・に基づく + Danh từ", "explain": "に基づいて chỉ nền tảng CHÍNH THỨC của một hành động: dữ liệu, luật pháp, sự thật, kinh nghiệm. Là động từ xương sống của văn báo cáo, luận văn, thông cáo.", "examples": [{"jp": "調査（ちょうさ）の 結果（けっか）に 基（もと）づいて、計画（けいかく）を 立（た）てた。", "vi": "Dựa trên kết quả điều tra, chúng tôi đã lập kế hoạch."}, {"jp": "事実（じじつ）に 基（もと）づく 報道（ほうどう）が 求（もと）められる。", "vi": "Báo chí được yêu cầu phải đưa tin dựa trên sự thật."}]}, {"pattern": "～をもとに（して）", "meaning": "lấy… làm gốc / dựa vào… mà sáng tạo", "form": "Danh từ + をもとに", "explain": "をもとに gần nghĩa に基づいて nhưng thiên về lấy chất liệu gốc để tạo ra cái MỚI: phim dựa trên tiểu thuyết, thiết kế dựa trên ý tưởng. Phân biệt: số liệu/luật lệ → に基づく; chất liệu sáng tác → をもとに.", "examples": [{"jp": "この 映画（えいが）は 実話（じつわ）をもとに 作（つく）られた。", "vi": "Bộ phim này được làm dựa trên câu chuyện có thật."}, {"jp": "アンケートの 結果（けっか）をもとに、新製品（しんせいひん）を 開発（かいはつ）した。", "vi": "Dựa vào kết quả khảo sát, chúng tôi đã phát triển sản phẩm mới."}]}, {"pattern": "～に沿（そ）って / ～に沿（そ）う", "meaning": "theo đúng / dọc theo…", "form": "Danh từ + に沿って・に沿う + Danh từ", "explain": "に沿って có hai nghĩa: đi dọc theo vật dài (sông, đường) và hành động THEO ĐÚNG một phương châm, kế hoạch, nguyện vọng đã vạch sẵn.", "examples": [{"jp": "川（かわ）に 沿（そ）って 歩（ある）くと、海（うみ）に 出（で）ます。", "vi": "Đi dọc theo con sông thì sẽ ra biển."}, {"jp": "計画（けいかく）に 沿（そ）って 事業（じぎょう）を 進（すす）めます。", "vi": "Chúng tôi tiến hành dự án theo đúng kế hoạch."}]}, {"pattern": "～に応（おう）じて", "meaning": "tùy theo / đáp ứng theo…", "form": "Danh từ + に応じて", "explain": "に応じて chỉ sự THAY ĐỔI TƯƠNG ỨNG: giá thay đổi theo nhu cầu, cách xử lý thay đổi theo tình huống. Khác によって (tùy theo — phân loại) ở chỗ に応じて nhấn mạnh sự đáp ứng linh hoạt, liên tục.", "examples": [{"jp": "収入（しゅうにゅう）に 応（おう）じて、生活（せいかつ）の 水準（すいじゅん）を 変（か）えるべきだ。", "vi": "Nên thay đổi mức sống tùy theo thu nhập."}, {"jp": "お客様（きゃくさま）の ご希望（きぼう）に 応（おう）じて、対応（たいおう）いたします。", "vi": "Chúng tôi sẽ xử lý đáp ứng theo yêu cầu của quý khách ạ."}]}]}, "5": {"title": "Unit 05 · カタカナA — Từ Katakana A · Mimi kara Oboeru", "intro": "Bài giảng N2 trọng tâm: nhóm mẫu biến đổi song hành — につれて, にしたがって, とともに, 一方だ.", "points": [{"pattern": "～につれて", "meaning": "càng… càng… / theo đà… thì…", "form": "Động từ thể từ điển・Danh từ + につれて", "explain": "につれて diễn tả hai sự thay đổi DIỄN RA SONG SONG theo tỷ lệ: một bên thay đổi thì bên kia tự nhiên thay đổi theo. Thường không dùng cho hành động ý chí một lần.", "examples": [{"jp": "年（とし）を 取（と）るにつれて、体力（たいりょく）が 落（お）ちてきた。", "vi": "Theo đà tuổi tác tăng lên, thể lực suy giảm dần."}, {"jp": "上（うえ）へ 上（のぼ）るにつれて、景色（けしき）が よく なった。", "vi": "Càng lên cao, phong cảnh càng đẹp."}]}, {"pattern": "～にしたがって", "meaning": "theo như / tuân theo… ; càng… càng…", "form": "Động từ thể từ điển・Danh từ + にしたがって", "explain": "にしたがって có hai đời sống: (1) tuân theo chỉ thị, quy tắc của cấp trên; (2) biến đổi song hành như につれて nhưng văn viết và khách quan hơn.", "examples": [{"jp": "指示（しじ）に したがって、作業（さぎょう）を 進（すす）めて ください。", "vi": "Hãy tiến hành công việc theo chỉ thị."}, {"jp": "人口（じんこう）が 増（ふ）えるにしたがって、住宅（じゅうたく）問題（もんだい）も 深刻（しんこく）に なった。", "vi": "Dân số càng tăng, vấn đề nhà ở càng nghiêm trọng."}]}, {"pattern": "～とともに", "meaning": "cùng với… / đồng thời với sự thay đổi…", "form": "Danh từ・Động từ thể từ điển + とともに", "explain": "とともに mang ba nghĩa: cùng đi với ai, cùng lúc với một sự kiện, và song hành biến đổi. Là mẫu trang trọng, hay mở đầu các bài phát biểu, văn bản chính thức.", "examples": [{"jp": "卒業（そつぎょう）とともに、故郷（ふるさと）を 離（はな）れた。", "vi": "Tốt nghiệp xong là tôi rời quê hương (cùng thời điểm)."}, {"jp": "技術（ぎじゅつ）の 進歩（しんぽ）とともに、生活（せいかつ）も 便利（べんり）に なった。", "vi": "Cùng với tiến bộ kỹ thuật, cuộc sống cũng tiện lợi hơn."}]}, {"pattern": "～一方（いっぽう）だ", "meaning": "cứ ngày càng… (một chiều không đổi)", "form": "Động từ thể từ điển + 一方だ", "explain": "一方だ khẳng định một xu hướng CHỈ ĐI MỘT CHIỀU mà không hề đảo ngược: giá cứ tăng mãi, dân số cứ giảm mãi. Thường dùng cho các vấn đề xã hội đáng lo ngại.", "examples": [{"jp": "物価（ぶっか）は 上（あ）がる 一方（いっぽう）だ。", "vi": "Vật giá cứ tăng mãi không ngừng."}, {"jp": "若者（わかもの）の 読書離（どくしょばな）れは 進（すす）む 一方（いっぽう）だ。", "vi": "Tình trạng giới trẻ xa rời việc đọc sách cứ ngày càng tiến triển."}]}]}, "6": {"title": "Unit 06 · 副詞A・接続詞 — Trạng từ A · Liên từ · Mimi kara Oboeru", "intro": "Bài giảng N2 trọng tâm: gia đình ～もの — các mẫu về bản chất, hoài niệm và phủ định mạnh.", "points": [{"pattern": "～ものだ (bản chất – lời khuyên chung)", "meaning": "vốn dĩ… là / phải… mới phải lẽ", "form": "Thể thường + ものだ", "explain": "ものだ nói về một SỰ THẬT PHỔ QUÁT hoặc một lẽ thường của đời sống: con người ai cũng mắc lỗi, trẻ con thì phải được yêu thương. Cũng dùng để nhắc nhở điều đương nhiên trong xã hội.", "examples": [{"jp": "人（ひと）の 心（こころ）は 変（か）わりやすいものだ。", "vi": "Lòng người vốn dễ thay đổi."}, {"jp": "約束（やくそく）は 守（まも）るものだ。", "vi": "Lời hứa là thứ phải giữ."}]}, {"pattern": "Vた ものだ (hoài niệm)", "meaning": "ngày xưa thường hay… (hồi tưởng)", "form": "Động từ thể た + ものだ", "explain": "たものだ nhìn lại quá khứ với cảm xúc hoài niệm: ngày xưa hay chơi ở sông này, hồi bé thường bị mắng. Luôn đi với ngữ cảnh nhớ lại (子どものころ, 昔).", "examples": [{"jp": "子（こ）どものころ、この 川（かわ）で よく 遊（あそ）んだものだ。", "vi": "Hồi nhỏ, tôi thường hay chơi ở con sông này."}, {"jp": "若（わか）いころは、一晩中（ひとばんじゅう） 話（はな）したものだ。", "vi": "Hồi trẻ, chúng tôi thường nói chuyện suốt cả đêm."}]}, {"pattern": "～ものでは ない", "meaning": "không được phép / không nên… (răn dạy)", "form": "Động từ thể từ điển + ものでは ない", "explain": "ものではない là lời răn mang tính NGUYÊN TẮC SỐNG: không nên nói dối, không được coi thường người khác. Mạnh và đạo lý hơn てはいけない, thường từ người trên nói xuống.", "examples": [{"jp": "人（ひと）の 悪口（わるぐち）を 言（い）うものでは ない。", "vi": "Không nên nói xấu người khác."}, {"jp": "約束（やくそく）を 簡単（かんたん）に 破（やぶ）るものでは ない。", "vi": "Không được dễ dàng phá vỡ lời hứa."}]}, {"pattern": "～ものか / ～もんか", "meaning": "làm gì có chuyện…! (phủ định quyết liệt)", "form": "Thể thường + ものか・もんか", "explain": "ものか phủ định với cảm xúc PHẢN BÁC mạnh: đời nào tôi lại thua, làm gì có chuyện tin được. もんか là dạng thân mật. Câu mang hình thức hỏi nhưng nghĩa là khẳng định phủ định.", "examples": [{"jp": "あんな 店（みせ）に 二度（にど）と 行（い）くものか。", "vi": "Đời nào tôi lại đến cái quán đó lần thứ hai."}, {"jp": "彼（かれ）の 言（い）うことが 信（しん）じられるものか。", "vi": "Làm gì có chuyện tin được lời anh ta nói."}]}]}, "7": {"title": "Unit 07 · 名詞C — Danh từ C · Mimi kara Oboeru", "intro": "Bài giảng N2 trọng tâm: các mẫu khẳng định dự đoán ở mức cao nhất — に違いない, に決まっている, はずがない, まい.", "points": [{"pattern": "～に違（ちが）いない", "meaning": "chắc chắn là… (suy luận đầy tin tưởng)", "form": "Thể thường + に違いない", "explain": "に違いない là kết luận chắc chắn từ SUY LUẬN của người nói — tương đương “không sai vào đâu được”. Độ chắc cao hơn でしょう, ngang はずですが mang tính trực giác, cảm tính cá nhân hơn.", "examples": [{"jp": "彼（かれ）は 知（し）っているに 違（ちが）いない。", "vi": "Anh ấy chắc chắn là biết chuyện đó."}, {"jp": "こんなに 練習（れんしゅう）したのだから、成功（せいこう）するに 違（ちが）いない。", "vi": "Đã luyện tập đến mức này thì chắc chắn sẽ thành công."}]}, {"pattern": "～はずが ない", "meaning": "không thể nào… (phủ định dự đoán chắc chắn)", "form": "Thể thường + はずが ない", "explain": "はずがない là mặt trái của はずだ: căn cứ vào mọi dấu hiệu, việc đó KHÔNG THỂ xảy ra. Dùng khi bác bỏ một phỏng đoán của người khác hoặc tự trấn an.", "examples": [{"jp": "彼（かれ）が 嘘（うそ）を つくはずが ない。", "vi": "Không thể nào anh ấy lại nói dối."}, {"jp": "こんな 簡単（かんたん）な 問題（もんだい）が 解（と）けないはずが ない。", "vi": "Bài toán đơn giản thế này, không thể nào không giải được."}]}, {"pattern": "～まい", "meaning": "chắc sẽ không… / quyết không… (phủ định ý chí văn viết)", "form": "Động từ thể từ điển + まい ( nhóm 2 bỏ る + まい ; する→するまい/すまい ; 来る→くるまい/こまい )", "explain": "まい là trợ từ phủ định trang trọng hai mặt: dự đoán phủ định khách quan (雨は降るまい = chắc trời không mưa đâu) và ý chí phủ định của người nói (二度と行くまい = quyết không đi nữa). Thường gặp trong văn viết, diễn văn.", "examples": [{"jp": "彼（かれ）は もう 来（く）るまい。", "vi": "Anh ấy chắc sẽ không đến nữa đâu."}, {"jp": "二度（にど）と 同（おな）じ 失敗（しっぱい）は するまいと 心（こころ）に 誓（ちか）った。", "vi": "Tôi thề trong lòng sẽ không bao giờ lặp lại thất bại tương tự."}]}]}, "8": {"title": "Unit 08 · 動詞B — Động từ B · Mimi kara Oboeru", "intro": "Bài giảng N2 trọng tâm: các đuôi động từ diễn đạt “khó mà / đủ sức” — がたい, かねる (ôn), 得る・得ない, きる・きれない.", "points": [{"pattern": "V(ます stem) がたい", "meaning": "khó mà làm được (về mặt tâm lý, lẽ thường)", "form": "Động từ gốc ます + がたい", "explain": "がたい chỉ việc KHÓ thực hiện không phải vì kỹ thuật mà vì cảm xúc/lẽ đời: khó tin, khó chấp nhận, khó tha thứ. Họ hàng của にくい nhưng tầng nghĩa sâu hơn hẳn.", "examples": [{"jp": "彼（かれ）の 行動（こうどう）は 理解（りかい）しがたい。", "vi": "Hành động của anh ấy khó mà hiểu được."}, {"jp": "それは 信（しん）じがたい 出来事（できごと）だった。", "vi": "Đó là một sự việc khó mà tin nổi."}]}, {"pattern": "V得（う）る / V得（え）ない", "meaning": "có thể xảy ra / không thể nào xảy ra", "form": "Động từ gốc ます + 得る（うる・える）/ 得ない（えない）", "explain": "得る/得ない bàn về KHẢ NĂNG TỒN TẠI của một sự việc trong suy luận: có thể có chuyện đó (あり得る) hoặc tuyệt đối không thể (あり得ない). Cặp từ cửa miệng trong tranh luận logic.", "examples": [{"jp": "そんな ミスは あり得（え）ない。", "vi": "Lỗi như thế không thể nào xảy ra."}, {"jp": "考（かんが）え得（う）る 限（かぎ）りの 対策（たいさく）を 講（こう）じた。", "vi": "Chúng tôi đã áp dụng mọi biện pháp có thể nghĩ ra."}]}, {"pattern": "Vきる / Vきれない", "meaning": "làm cho kỳ hết / không làm xuể", "form": "Động từ gốc ます + きる・きれない", "explain": "きる là làm đến TẬN CÙNG: đọc hết, chạy hết quãng đường, dùng hết tiền. Phủ định きれない là nhiều/quá sức đến mức không xử lý xuể: đếm không xuể, nói không hết.", "examples": [{"jp": "この 長（なが）い 小説（しょうせつ）を 一週間（いっしゅうかん）で 読（よ）みきった。", "vi": "Tôi đã đọc hết cuốn tiểu thuyết dài này trong một tuần."}, {"jp": "感謝（かんしゃ）の 気持（きも）ちは 言（い）いきれない。", "vi": "Lòng biết ơn của tôi không lời nào nói hết được."}]}]}, "9": {"title": "Unit 09 · カタカナB — Từ Katakana B · Mimi kara Oboeru", "intro": "Bài giảng N2 trọng tâm: các mẫu bao phủ toàn bộ phạm vi — にわたって, を通じて, だらけ.", "points": [{"pattern": "～にわたって / ～にわたる", "meaning": "trải dài suốt… (toàn bộ khoảng thời gian, phạm vi)", "form": "Danh từ (thời gian・phạm vi) + にわたって・にわたる + Danh từ", "explain": "にわたって nhấn mạnh sự bao phủ TRỌN VẸN một khoảng lớn: thảo luận suốt 3 ngày, thiệt hại trên diện rộng. Luôn đi với những con số/phạm vi ấn tượng.", "examples": [{"jp": "会議（かいぎ）は 3（さん）日間（にちかん）に わたって 行（おこな）われた。", "vi": "Cuộc họp diễn ra suốt 3 ngày."}, {"jp": "被害（ひがい）は 広（ひろ）い 地域（ちいき）に わたっている。", "vi": "Thiệt hại trải rộng trên một khu vực lớn."}]}, {"pattern": "～を通（つう）じて / ～を通（とお）して", "meaning": "thông qua… / qua trung gian… ; suốt (thời gian)", "form": "Danh từ + を通じて・を通して", "explain": "を通じて có hai nghĩa: qua một TRUNG GIAN (người, phương tiện, tổ chức) và SUỐT một khoảng thời gian không gián đoạn (一年を通じて = suốt cả năm). 通して thiên về chủ động dùng một phương tiện.", "examples": [{"jp": "友人（ゆうじん）を 通（つう）じて、彼（かれ）と 知（し）り合（あ）った。", "vi": "Thông qua bạn bè, tôi quen biết anh ấy."}, {"jp": "この 地域（ちいき）は 一年（いちねん）を 通（つう）じて 雨（あめ）が 多（おお）い。", "vi": "Khu vực này suốt cả năm mưa nhiều."}]}, {"pattern": "～だらけ", "meaning": "đầy rẫy… (toàn thứ không tốt)", "form": "Danh từ + だらけ", "explain": "だらけ chỉ một bề mặt/không gian bị bao phủ bởi thứ KHÔNG MONG MUỐN: đầy lỗi, đầy bụi, đầy vết thương. Cặp với phủ định cảm xúc — không ai nói 花だらけ với nghĩa khen (phải là 花がいっぱい).", "examples": [{"jp": "彼（かれ）の レポートは 間違（まちが）いだらけだ。", "vi": "Báo cáo của anh ấy đầy lỗi sai."}, {"jp": "転（ころ）んで、服（ふく）が 泥（どろ）だらけに なった。", "vi": "Tôi ngã nên quần áo đầy bùn đất."}]}]}, "10": {"title": "Unit 10 · 形容詞B — Tính từ B · Mimi kara Oboeru", "intro": "Bài giảng N2 trọng tâm: các khung so sánh – điều kiện sắc bén: ほど～ない, くらいなら, さえ～ば.", "points": [{"pattern": "N ほど ～ない", "meaning": "không có gì… bằng N (so sánh nhất trá hình)", "form": "Danh từ + ほど + phủ định", "explain": "ほど + phủ định tạo nghĩa so sánh TUYỆT ĐỐI: lấy N làm đỉnh, khẳng định không đối thủ nào vượt qua. Mẫu này trang trọng và giàu cảm xúc hơn ～が一番…です.", "examples": [{"jp": "母（はは）の 料理（りょうり）ほど おいしいものは ない。", "vi": "Không có gì ngon bằng món ăn của mẹ."}, {"jp": "健康（けんこう）ほど 大切（たいせつ）なものは ない。", "vi": "Không có gì quan trọng bằng sức khỏe."}]}, {"pattern": "Vる くらいなら", "meaning": "thà… còn hơn là làm V", "form": "Động từ thể từ điển + くらいなら + lựa chọn ít tệ hơn", "explain": "くらいなら đặt một hành động vào vị trí “điều tệ không chấp nhận được” rồi đưa phương án thay thế: thà đi bộ còn hơn chen chuyến tàu đó. Cấu trúc tranh luận rất mạnh.", "examples": [{"jp": "あんな 高（たか）い 店（みせ）で 食（た）べるくらいなら、自分（じぶん）で 作（つく）る。", "vi": "Thà tự nấu còn hơn ăn ở quán đắt như thế."}, {"jp": "嘘（うそ）を つくくらいなら、黙（だま）っていたい。", "vi": "Thà im lặng còn hơn nói dối."}]}, {"pattern": "～さえ ～ば", "meaning": "chỉ cần… là (đủ)…", "form": "Danh từ + さえ + Thể điều kiện ば", "explain": "さえ…ば xác định ĐIỀU KIỆN DUY NHẤT, TỐI THIỂU: chỉ cần điều đó thỏa mãn, mọi thứ khác không thành vấn đề. Đây là hoàn thiện của さえ đã học ở N3.", "examples": [{"jp": "お金（かね）さえ あれば、何（なん）でも 買（か）える。", "vi": "Chỉ cần có tiền là mua được mọi thứ."}, {"jp": "元気（げんき）でさえ いれば、それで いい。", "vi": "Chỉ cần khỏe mạnh là đủ rồi."}]}]}, "11": {"title": "Unit 11 · 名詞D — Danh từ D · Mimi kara Oboeru", "intro": "Bài giảng N2 trọng tâm: các mẫu đối chiếu và phân loại đối tượng — 一方で, 向け・向き, に対して (nâng cấp).", "points": [{"pattern": "～一方（いっぽう）で", "meaning": "mặt khác / trong khi đó (hai mặt đối chiếu)", "form": "Câu 1。一方で、Câu 2。(hoặc ～一方で ở giữa câu)", "explain": "一方で đặt hai mặt của một vấn đề lên bàn cân: một mặt tiện lợi, mặt khác rủi ro. Là liên từ xương sống của văn nghị luận, báo cáo phân tích ở trình độ N2.", "examples": [{"jp": "便利（べんり）に なる 一方（いっぽう）で、危険（きけん）も 増（ふ）えた。", "vi": "Trong khi tiện lợi hơn, mặt khác nguy hiểm cũng tăng lên."}, {"jp": "都会（とかい）は 仕事（しごと）が 多（おお）い 一方（いっぽう）で、生活費（せいかつひ）が 高（たか）い。", "vi": "Thành phố lớn nhiều việc làm, mặt khác chi phí sinh hoạt lại cao."}]}, {"pattern": "～向（む）け / ～向（む）き", "meaning": "dành cho (thiết kế, chủ đích) / phù hợp với (tự nhiên vốn vậy)", "form": "Danh từ + 向け（の）/ 向き（の）", "explain": "向け là sản phẩm/hành động được THIẾT KẾ CÓ CHỦ ĐÍCH cho một đối tượng (子ども向けの番組 = chương trình làm cho trẻ em). 向き là tính chất VỐN PHÙ HỢP tự nhiên (初心者向き = hợp với người mới, không ai thiết kế riêng).", "examples": [{"jp": "これは 外国人（がいこくじん）向（む）けの ガイドブックです。", "vi": "Đây là sách hướng dẫn dành cho người nước ngoài."}, {"jp": "この 道（みち）は 車（くるま）の 通行（つうこう）には 向（む）きません。", "vi": "Con đường này không phù hợp cho xe cộ qua lại."}], "note": "Cặp 向け/向き là một trong những cặp phân biệt kinh điển nhất của thi N2 — nhớ bằng câu: 向け = người làm ra nhắm tới; 向き = bản chất sự vật tự hợp."}, {"pattern": "～に比（くら）べて", "meaning": "so với…", "form": "Danh từ + に比べて・に比べ", "explain": "に比べて là khung so sánh khách quan, trang trọng hơn より đơn thuần — hay dùng khi đối chiếu số liệu, thời đại, khu vực trong văn bản.", "examples": [{"jp": "去年（きょねん）に 比（くら）べて、今年（ことし）は 雨（あめ）が 少（すく）ない。", "vi": "So với năm ngoái, năm nay mưa ít hơn."}, {"jp": "都市（とし）に 比（くら）べて、田舎（いなか）は 静（しず）かです。", "vi": "So với thành phố, nông thôn yên tĩnh hơn."}]}]}, "12": {"title": "Unit 12 · 動詞C — Động từ C · Mimi kara Oboeru", "intro": "Bài giảng N2 trọng tâm: các mẫu chuyển biến đang diễn ra và sự nhượng bộ mạnh: つつある, ながらも, にもかかわらず.", "points": [{"pattern": "V(ます stem) つつある", "meaning": "đang dần… (biến đổi đang tiến triển)", "form": "Động từ gốc ます + つつある", "explain": "つつある là phiên bản văn viết của てきている/ていく cho các BIẾN ĐỔI LỚN: dân số đang giảm, môi trường đang được cải thiện. Không dùng cho hành động nhỏ hằng ngày của cá nhân.", "examples": [{"jp": "少子化（しょうしか）は 進（すす）みつつある。", "vi": "Tình trạng già hóa, ít trẻ em đang tiến triển."}, {"jp": "景気（けいき）は 少（すこ）しずつ 回復（かいふく）しつつある。", "vi": "Nền kinh tế đang dần hồi phục."}]}, {"pattern": "～ながら（も）", "meaning": "tuy… nhưng vẫn… (nhượng bộ)", "form": "Thể thường (N・な形 + の) + ながらも ; Vます stem + ながらも (văn viết)", "explain": "ながらも ở N2 không còn là “vừa… vừa” mà là NHƯỢNG BỘ: biết là nhỏ mà quý, tuy nghèo mà hạnh phúc. Hai sự thật trái ngược cùng tồn tại trong một chủ thể.", "examples": [{"jp": "狭（せま）いながらも、楽（たの）しい わが家（や）だ。", "vi": "Tuy chật hẹp nhưng là ngôi nhà vui vẻ của chúng tôi."}, {"jp": "体（からだ）に 悪（わる）いと 知（し）りながらも、たばこが やめられない。", "vi": "Biết là hại sức khỏe mà vẫn không bỏ được thuốc lá."}], "note": "Phân biệt hai ながら: ながら (N3) nối hai HÀNH ĐỘNG cùng lúc; ながらも (N2) nối hai SỰ THẬT trái ngược."}, {"pattern": "～にもかかわらず", "meaning": "bất chấp / mặc dù… (trang trọng)", "form": "Thể thường (N・な形 + な・である) + にもかかわらず", "explain": "にもかかわらず là nhượng bộ ở mức trang trọng nhất — lương tâm của văn bản chính thức: bất chấp thời tiết xấu, bất chấp đã cảnh báo nhiều lần. Mạnh và khách quan hơn のに (vốn mang cảm xúc cá nhân).", "examples": [{"jp": "悪天候（あくてんこう）にもかかわらず、イベントは 開催（かいさい）された。", "vi": "Bất chấp thời tiết xấu, sự kiện vẫn được tổ chức."}, {"jp": "何度（なんど）も 注意（ちゅうい）したにもかかわらず、彼（かれ）は 同（おな）じ ミスを 繰（く）り返（かえ）した。", "vi": "Mặc dù đã nhắc nhở nhiều lần, anh ấy vẫn lặp lại lỗi cũ."}]}]}, "13": {"title": "Unit 13 · 副詞B・連体詞 — Trạng từ B · Định ngữ · Mimi kara Oboeru", "intro": "Bài giảng N2 khép lại với nhóm mẫu “ngay tức thì” trong văn kể: が早いか, やいなや, 次第, て以来.", "points": [{"pattern": "Vる が早（はや）いか", "meaning": "vừa mới… thì ngay lập tức… (nhanh như chớp)", "form": "Động từ thể từ điển + が早いか + hành động tức thì (thường ở quá khứ)", "explain": "が早いか diễn tả hai hành động dính nhau gần như tại cùng một khoảnh khắc, với sắc thái nhanh bất ngờ — chỉ dùng trong văn KỂ, không dùng cho kế hoạch tương lai.", "examples": [{"jp": "ベルが 鳴（な）るが 早（はや）いか、学生（がくせい）たちは 教室（きょうしつ）を 飛（と）び出（だ）した。", "vi": "Chuông vừa reo là học sinh ùa ra khỏi lớp ngay."}, {"jp": "家（いえ）に 着（つ）くが 早（はや）いか、彼（かれ）は 寝（ね）て しまった。", "vi": "Vừa về đến nhà là anh ấy ngủ thiếp đi ngay."}]}, {"pattern": "Vる やいなや", "meaning": "ngay khoảnh khắc… vừa xảy ra thì…", "form": "Động từ thể từ điển + やいなや (văn viết); Vた やいなや cũng được dùng", "explain": "やいなや là anh em văn chương của が早いか và とたん: khoảnh khắc vế trước chạm tới là vế sau bùng nổ. Thường dùng trong tiểu thuyết, bài tường thuật sống động.", "examples": [{"jp": "彼女（かのじょ）は 顔（かお）を 見（み）るやいなや、泣（な）き出（だ）した。", "vi": "Vừa nhìn thấy mặt anh ấy là cô ấy bật khóc ngay."}, {"jp": "ドアが 開（あ）くやいなや、犬（いぬ）が 飛（と）び出（だ）してきた。", "vi": "Cửa vừa mở là con chó lao ngay ra."}]}, {"pattern": "V(ます stem) 次第（しだい）", "meaning": "ngay khi… xong thì lập tức… (trang trọng, công vụ)", "form": "Động từ gốc ます + 次第", "explain": "次第 trong thông báo công vụ nghĩa là “ngay khi việc trước hoàn tất”: hàng về tới là gửi ngay, quyết định xong là liên lạc ngay. Nó cam kết một hành động tiếp nối KHÔNG chậm trễ.", "examples": [{"jp": "商品（しょうひん）が 届（とど）き次第（しだい）、ご連絡（れんらく）いたします。", "vi": "Ngay khi hàng về tới, chúng tôi sẽ liên lạc ạ."}, {"jp": "分（わ）かり次第（しだい）、お知（し）らせします。", "vi": "Ngay khi có thông tin, chúng tôi sẽ thông báo."}], "note": "次第 còn là danh từ “sự tình/diễn biến” (事情次第) — phân biệt bằng vị trí: sau gốc ます thì là mẫu thời gian."}, {"pattern": "Vて 以来（いらい）", "meaning": "kể từ khi… (trở đi, kéo dài đến nay)", "form": "Động từ thể て + 以来 ; Danh từ + 以来", "explain": "て以来 đóng khung một quãng thời gian DÀI từ một cột mốc quá khứ đến hiện tại, trong đó một trạng thái được duy trì hoặc một việc không hề xảy ra lần nào nữa.", "examples": [{"jp": "日本（にほん）へ 来（き）て 以来（いらい）、一度（いちど）も 国（くに）へ 帰（かえ）って いません。", "vi": "Kể từ khi đến Nhật, tôi chưa về nước lần nào."}, {"jp": "卒業（そつぎょう）して 以来（いらい）、彼（かれ）とは 会（あ）って いない。", "vi": "Kể từ khi tốt nghiệp, tôi không gặp anh ấy nữa."}]}]}}};
